            const DATA_SANDBOX_MAPPING_FIELDS = [
                { key: 'canonical_user_id', label: 'Canonical User ID', required: true },
                { key: 'event_name', label: 'Event Name', required: true },
                { key: 'event_time', label: 'Event Time', required: true },
                { key: 'source_event_id', label: 'Source Event ID' },
                { key: 'campaign', label: 'Campaign' },
                { key: 'adset', label: 'Adset' },
                { key: 'media_source', label: 'Media Source' },
            ];
            let dataSandboxAwaitingJobs = [];
            let dataSandboxFieldCandidates = [];
            let dataSandboxFieldSuggestions = [];
            let dataSandboxMappingVersions = [];
            let dataSandboxSampleEvents = [];
            let dataSandboxSampleContextKey = '';
            let dataSandboxReprocessJobId = '';
            let dataSandboxReprocessJobName = '';

            function setDataSandboxMappingStatus(message = '', isError = false) {
                if (!dataSandboxMappingStatusDiv) return;
                dataSandboxMappingStatusDiv.textContent = message;
                dataSandboxMappingStatusDiv.style.color = isError ? 'var(--red)' : 'var(--green)';
            }

            function getSelectedAwaitingJobForConnector(connectorName = dataSandboxMappingConnectorSelect.value) {
                const selectedJob = getSelectedAwaitingJob();
                const selectedJobSource = String(selectedJob?.source_stats?.[0]?.source || '');
                if (!selectedJob || !connectorName || selectedJobSource !== connectorName) {
                    return null;
                }
                return selectedJob;
            }

            function getDataSandboxMappingScope() {
                const connectorName = dataSandboxMappingConnectorSelect.value;
                const selectedJob = getSelectedAwaitingJobForConnector(connectorName);
                if (selectedJob) {
                    return {
                        scopeType: 'job',
                        scopeKey: selectedJob.id,
                        scopeLabel: `job override for ${selectedJob.name}`,
                    };
                }
                return {
                    scopeType: 'source',
                    scopeKey: null,
                    scopeLabel: connectorName ? `source mapping for ${connectorName}` : 'source mapping',
                };
            }

            function getDataSandboxSourceScope() {
                const connectorName = dataSandboxMappingConnectorSelect.value;
                return {
                    scopeType: 'source',
                    scopeKey: null,
                    scopeLabel: connectorName ? `source mapping for ${connectorName}` : 'source mapping',
                };
            }

            function clearDataSandboxReprocessTracking() {
                dataSandboxReprocessJobId = '';
                dataSandboxReprocessJobName = '';
            }

            function syncDataSandboxReprocessState(imports = cachedImports) {
                if (!dataSandboxReprocessJobId) {
                    return;
                }
                const trackedJob = (imports || []).find((job) => String(job.id || '') === String(dataSandboxReprocessJobId)) || null;
                if (!trackedJob) {
                    clearDataSandboxReprocessTracking();
                    syncDataSandboxMappingActions();
                    return;
                }
                const displayName = dataSandboxReprocessJobName || trackedJob.name || trackedJob.id;
                if (isImportJobInFlight(trackedJob)) {
                    importExpandedJobIds.add(trackedJob.id);
                    setDataSandboxMappingStatus(`Reprocessing ${displayName}. ${trackedJob.status}${getImportProgressText(trackedJob) ? ` - ${getImportProgressText(trackedJob)}` : ''}`);
                    syncDataSandboxMappingActions();
                    return;
                }

                const failureReason = getImportFailureReason(trackedJob);
                if (failureReason) {
                    setDataSandboxMappingStatus(`${displayName} finished with an issue: ${failureReason}`, true);
                } else {
                    setDataSandboxMappingStatus(`${displayName} finished reprocessing. Status: ${trackedJob.status || 'Ready to Use'}.`);
                }
                clearDataSandboxReprocessTracking();
                syncDataSandboxMappingActions();
            }

            function syncDataSandboxMappingActions() {
                const connectorName = dataSandboxMappingConnectorSelect.value;
                const selectedJob = getSelectedAwaitingJobForConnector(connectorName);
                const trackedJob = dataSandboxReprocessJobId
                    ? (cachedImports || []).find((job) => String(job.id || '') === String(dataSandboxReprocessJobId)) || null
                    : null;
                const reprocessActive = Boolean(trackedJob && isImportJobInFlight(trackedJob));
                if (dataSandboxSaveMappingBtn) {
                    dataSandboxSaveMappingBtn.textContent = selectedJob ? 'Save Mapping Memory' : 'Save Mapping';
                    dataSandboxSaveMappingBtn.title = selectedJob
                        ? 'Save the connector mapping for future imports without rerunning the paused import.'
                        : 'Save the current connector mapping for future imports.';
                }
                if (dataSandboxProcessMappingBtn) {
                    dataSandboxProcessMappingBtn.textContent = reprocessActive ? 'Reprocessing Import...' : 'Save and Reprocess Import';
                    dataSandboxProcessMappingBtn.title = reprocessActive
                        ? 'The selected import is currently rerunning with the updated mapping.'
                        : selectedJob
                        ? 'Persist the corrected mapping, apply it to this paused import, and rerun normalization and dedupe.'
                        : 'Select a paused import job for this connector first.';
                    dataSandboxProcessMappingBtn.disabled = reprocessActive || !selectedJob;
                }
                if (!dataSandboxActionHint) return;
                if (!connectorName) {
                    dataSandboxActionHint.textContent = 'Select a connector to edit saved mapping memory or resume a paused import.';
                    return;
                }
                if (reprocessActive && trackedJob) {
                    const progressText = getImportProgressText(trackedJob);
                    dataSandboxActionHint.textContent = `Reprocessing ${trackedJob.name || trackedJob.id}. ${trackedJob.status}${progressText ? ` - ${progressText}` : ''}. The import list below will keep refreshing until it finishes.`;
                    return;
                }
                if (selectedJob) {
                    dataSandboxActionHint.textContent = `Save Mapping Memory updates future imports for ${connectorName}. Save and Reprocess Import applies the current setup to ${selectedJob.name}, reruns normalization and dedupe, and keeps the successful mapping as future memory.`;
                    return;
                }
                dataSandboxActionHint.textContent = `Save Mapping updates connector memory for future ${connectorName} imports. Reprocessing is only available after you select a paused Awaiting Mapping import for the same connector.`;
            }

            function setDataSandboxMappingJsonValue(mapping = {}) {
                if (!dataSandboxMappingJson) return;
                dataSandboxMappingJson.value = JSON.stringify(mapping || {}, null, 2);
                syncNoCodeSetupArtifacts(['data-sandbox-mapping-json']);
            }

            function getDataSandboxCurrentMapping(options = {}) {
                const { silent = false } = options;
                try {
                    return JSON.parse(dataSandboxMappingJson.value || '{}');
                } catch (error) {
                    if (!silent) {
                        throw error;
                    }
                    return {};
                }
            }

            function getDataSandboxSuggestion(fieldKey = '') {
                return (dataSandboxFieldSuggestions || []).find((item) => String(item.field || '') === String(fieldKey || '')) || null;
            }

            function getDataSandboxSampleContextKey(connectorName = dataSandboxMappingConnectorSelect.value) {
                const selectedJob = getSelectedAwaitingJobForConnector(connectorName);
                return `${String(connectorName || '').trim()}::${selectedJob?.id || 'source'}`;
            }

            function getDataSandboxSampleEventName(sampleEvent = {}) {
                const mapping = getDataSandboxCurrentMapping({ silent: true });
                const suggestedEventNamePath = String(getDataSandboxSuggestion('event_name')?.suggested_path || '').trim();
                return String(
                    getPathValue(sampleEvent, mapping.event_name)
                    || getPathValue(sampleEvent, suggestedEventNamePath)
                    || pickValue(sampleEvent, ['event_name', 'eventName', 'event_type', 'name'], null)
                    || ''
                ).trim();
            }

            function getDataSandboxSampleUserValue(sampleEvent = {}) {
                const mapping = getDataSandboxCurrentMapping({ silent: true });
                const suggestedUserPath = String(getDataSandboxSuggestion('canonical_user_id')?.suggested_path || '').trim();
                return String(
                    getPathValue(sampleEvent, mapping.canonical_user_id)
                    || getPathValue(sampleEvent, suggestedUserPath)
                    || pickValue(sampleEvent, ['player_id', 'user_id', 'uid', 'PID', 'customer_user_id', 'appsflyer_id'], null)
                    || ''
                ).trim();
            }

            function describeDataSandboxSampleEvent(sampleEvent = {}, index = 0) {
                const eventName = getDataSandboxSampleEventName(sampleEvent);
                const userValue = getDataSandboxSampleUserValue(sampleEvent);
                const parts = [`Sample ${index + 1}`];
                if (eventName) {
                    parts.push(eventName);
                }
                if (userValue) {
                    parts.push(userValue);
                }
                return parts.join(' · ');
            }

            function setDataSandboxSampleValue(sampleEvent = {}, options = {}) {
                if (!dataSandboxSampleJson) return;
                const { source = 'candidate', force = false } = options;
                const nextValue = JSON.stringify(sampleEvent || {}, null, 2);
                const currentValue = (dataSandboxSampleJson.value || '').trim();
                const priorAutoValue = dataSandboxSampleJson.dataset.autoValue || '';
                const currentSource = dataSandboxSampleJson.dataset.sampleSource || '';
                if (force || !currentValue || currentValue === priorAutoValue || currentSource !== 'manual') {
                    dataSandboxSampleJson.value = nextValue;
                    dataSandboxSampleJson.dataset.autoValue = nextValue;
                    dataSandboxSampleJson.dataset.sampleSource = source;
                    syncNoCodeSetupArtifacts(['data-sandbox-sample-json']);
                }
            }

            function setDataSandboxSampleEvents(sampleEvents = [], options = {}) {
                const events = Array.isArray(sampleEvents) ? sampleEvents.filter((item) => item && typeof item === 'object') : [];
                const contextKey = String(options.contextKey || '').trim();
                const contextChanged = contextKey && contextKey !== dataSandboxSampleContextKey;
                dataSandboxSampleEvents = events;
                if (contextKey) {
                    dataSandboxSampleContextKey = contextKey;
                }
                if (events.length > 0) {
                    const previousIndex = Number.parseInt(dataSandboxSamplePicker?.value || '0', 10);
                    const nextIndex = contextChanged ? 0 : Math.min(Number.isFinite(previousIndex) ? previousIndex : 0, events.length - 1);
                    if (dataSandboxSamplePicker) {
                        dataSandboxSamplePicker.innerHTML = events.map((sampleEvent, index) => (
                            `<option value="${index}">${escapeHtml(describeDataSandboxSampleEvent(sampleEvent, index))}</option>`
                        )).join('');
                        dataSandboxSamplePicker.value = String(nextIndex);
                        dataSandboxSamplePicker.disabled = events.length <= 1;
                    }
                    setDataSandboxSampleValue(events[nextIndex], { source: 'candidate', force: contextChanged });
                } else if (dataSandboxSamplePicker) {
                    dataSandboxSamplePicker.innerHTML = '<option value="">No raw samples loaded</option>';
                    dataSandboxSamplePicker.disabled = true;
                    const currentValue = (dataSandboxSampleJson?.value || '').trim();
                    const autoValue = dataSandboxSampleJson?.dataset.autoValue || '';
                    const currentSource = dataSandboxSampleJson?.dataset.sampleSource || '';
                    if (dataSandboxSampleJson && (!currentValue || currentValue === autoValue || currentSource !== 'manual')) {
                        dataSandboxSampleJson.value = '';
                        dataSandboxSampleJson.dataset.autoValue = '';
                        dataSandboxSampleJson.dataset.sampleSource = '';
                        syncNoCodeSetupArtifacts(['data-sandbox-sample-json']);
                    }
                }
                renderDataSandboxSampleMeta();
            }

            function getDataSandboxFieldPresenceStats(path = '') {
                const normalizedPath = String(path || '').trim();
                if (!normalizedPath || !Array.isArray(dataSandboxSampleEvents) || !dataSandboxSampleEvents.length) {
                    return null;
                }
                let presentCount = 0;
                const eventNames = new Set();
                dataSandboxSampleEvents.forEach((sampleEvent) => {
                    const value = getPathValue(sampleEvent, normalizedPath);
                    if (value === null || value === undefined || value === '') {
                        return;
                    }
                    presentCount += 1;
                    const eventName = getDataSandboxSampleEventName(sampleEvent);
                    if (eventName) {
                        eventNames.add(eventName);
                    }
                });
                return {
                    presentCount,
                    totalSamples: dataSandboxSampleEvents.length,
                    eventNameCount: eventNames.size,
                };
            }

            function getDataSandboxMappingMemory() {
                const versions = Array.isArray(dataSandboxMappingVersions) ? dataSandboxMappingVersions : [];
                return DATA_SANDBOX_MAPPING_FIELDS.map((fieldConfig) => {
                    const suggestion = getDataSandboxSuggestion(fieldConfig.key);
                    const counts = new Map();
                    let populatedVersions = 0;
                    versions.forEach((item) => {
                        const payloadMapping = item?.payload?.mapping || {};
                        const path = String(payloadMapping[fieldConfig.key] || '').trim();
                        if (!path) {
                            return;
                        }
                        populatedVersions += 1;
                        counts.set(path, (counts.get(path) || 0) + 1);
                    });
                    const rankedPaths = Array.from(counts.entries())
                        .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]));
                    const learnedPath = String(suggestion?.suggested_path || '').trim();
                    const manualConfirmationCount = Number(suggestion?.manual_confirmation_count || 0);
                    const successfulImportCount = Number(suggestion?.successful_import_count || 0);
                    const hasLearnedMemory = manualConfirmationCount > 0 || successfulImportCount > 0;
                    const topPath = hasLearnedMemory ? learnedPath : (rankedPaths[0]?.[0] || '');
                    const topCount = rankedPaths[0]?.[1] || 0;
                    const profile = suggestion?.profile || {};
                    return {
                        ...fieldConfig,
                        totalVersions: versions.length,
                        populatedVersions,
                        topPath,
                        topCount,
                        manualConfirmationCount,
                        successfulImportCount,
                        profile,
                        hasLearnedMemory,
                        stable: hasLearnedMemory ? (successfulImportCount + manualConfirmationCount > 1) : (populatedVersions > 1 && rankedPaths.length === 1),
                        crossEventSignal: Number(profile.event_type_coverage || 0) >= 0.6,
                        alternatives: rankedPaths.slice(1, 3),
                    };
                });
            }

            function renderDataSandboxMemory() {
                if (!dataSandboxMemoryGrid) return;
                const connectorName = dataSandboxMappingConnectorSelect.value;
                if (!connectorName) {
                    if (dataSandboxMemorySummary) {
                        dataSandboxMemorySummary.textContent = '';
                    }
                    dataSandboxMemoryGrid.innerHTML = '';
                    return;
                }
                const memoryItems = getDataSandboxMappingMemory();
                const currentMapping = getDataSandboxCurrentMapping({ silent: true });
                const savedVersionCount = Number(Array.isArray(dataSandboxMappingVersions) ? dataSandboxMappingVersions.length : 0);
                const selectedJob = getSelectedAwaitingJobForConnector(connectorName);
                const learnedSignalCount = memoryItems.reduce(
                    (total, item) => total + Number(item.manualConfirmationCount || 0) + Number(item.successfulImportCount || 0),
                    0,
                );
                if (dataSandboxMemorySummary) {
                    if (learnedSignalCount > 0) {
                        dataSandboxMemorySummary.textContent = `Learned from confirmed saves and successful imports${savedVersionCount > 0 ? `, with ${savedVersionCount} saved source mapping version${savedVersionCount === 1 ? '' : 's'} for context` : ''}.`;
                    } else if (savedVersionCount > 0) {
                        dataSandboxMemorySummary.textContent = `Built from ${savedVersionCount} saved source mapping version${savedVersionCount === 1 ? '' : 's'}.`;
                    } else {
                        dataSandboxMemorySummary.textContent = 'No learned mapping memory yet. Suggestions are currently heuristic.';
                    }
                }
                dataSandboxMemoryGrid.innerHTML = memoryItems.map((memoryItem) => {
                    const suggestion = getDataSandboxSuggestion(memoryItem.key);
                    const currentPath = String(currentMapping[memoryItem.key] || '').trim();
                    const badges = [];
                    if (memoryItem.successfulImportCount > 0) {
                        badges.push(`<span class="mapping-memory-badge is-good">${escapeHtml(`${memoryItem.successfulImportCount} successful import${memoryItem.successfulImportCount === 1 ? '' : 's'}`)}</span>`);
                    }
                    if (memoryItem.manualConfirmationCount > 0) {
                        badges.push(`<span class="mapping-memory-badge is-info">${escapeHtml(`${memoryItem.manualConfirmationCount} confirmed save${memoryItem.manualConfirmationCount === 1 ? '' : 's'}`)}</span>`);
                    }
                    if (memoryItem.stable) {
                        badges.push(`<span class="mapping-memory-badge is-good">Stable memory</span>`);
                    } else if (memoryItem.crossEventSignal) {
                        badges.push('<span class="mapping-memory-badge is-info">Cross-event raw signal</span>');
                    }
                    if (memoryItem.topPath && (memoryItem.hasLearnedMemory || memoryItem.populatedVersions > 0)) {
                        badges.push(`<span class="mapping-memory-badge is-info">Current preferred path</span>`);
                    }
                    if (memoryItem.topPath && suggestion?.suggested_path === memoryItem.topPath) {
                        badges.push('<span class="mapping-memory-badge is-good">Matches current suggestion</span>');
                    } else if (memoryItem.topPath && currentPath && currentPath !== memoryItem.topPath) {
                        badges.push('<span class="mapping-memory-badge is-warn">Current selection differs</span>');
                    }
                    if (suggestion?.suggested_path && currentPath && currentPath !== suggestion.suggested_path) {
                        badges.push('<span class="mapping-memory-badge is-warn">Manual correction in setup</span>');
                    }
                    const topPathMarkup = memoryItem.topPath
                        ? `<div class="mapping-memory-path"><strong>Preferred path:</strong> ${escapeHtml(memoryItem.topPath)}</div>`
                        : '<div class="mapping-memory-path"><strong>Preferred path:</strong> No saved memory yet</div>';
                    const memoryHelpContent = `
                        ${memoryItem.successfulImportCount > 0 || memoryItem.manualConfirmationCount > 0
                            ? `<div><strong>Learned memory:</strong> ${memoryItem.successfulImportCount} successful import${memoryItem.successfulImportCount === 1 ? '' : 's'} and ${memoryItem.manualConfirmationCount} confirmed save${memoryItem.manualConfirmationCount === 1 ? '' : 's'} currently reinforce this path.</div>`
                            : (memoryItem.populatedVersions > 0
                                ? `<div><strong>Saved history:</strong> ${memoryItem.populatedVersions}/${memoryItem.totalVersions} saved source versions include this field.</div>`
                                : '<div><strong>Learned memory:</strong> No prior confirmed mapping evidence yet.</div>')}
                        ${memoryItem.crossEventSignal
                            ? `<div><strong>Cross-event stability:</strong> present across ${(Number(memoryItem.profile.event_type_coverage || 0) * 100).toFixed(0)}% of sampled event-name groups.</div>`
                            : ''}
                        <div><strong>Correction rule:</strong> ${selectedJob
                            ? 'Use Save Mapping Memory if future imports should inherit the correction without touching the paused job. Use Save and Reprocess Import when the current paused import should rerun with this setup.'
                            : 'Save the mapping after you correct a field to persist that choice into future source-memory history.'}</div>
                        ${memoryItem.alternatives.length
                            ? `<div><strong>Other saved paths:</strong> ${escapeHtml(memoryItem.alternatives.map(([path, count]) => `${path} (${count})`).join(', '))}</div>`
                            : ''}
                    `;
                    return `
                        <div class="mapping-memory-card">
                            <div class="mapping-memory-label">
                                <span>${escapeHtml(memoryItem.label)}</span>
                                ${buildHelpTooltip(memoryHelpContent, `Show ${memoryItem.label} saved mapping details`)}
                            </div>
                            ${topPathMarkup}
                            <div class="mapping-memory-badges">${badges.join('')}</div>
                        </div>
                    `;
                }).join('');
            }

            function renderDataSandboxSampleMeta() {
                if (!dataSandboxSampleMeta) return;
                const currentValue = (dataSandboxSampleJson?.value || '').trim();
                const autoValue = dataSandboxSampleJson?.dataset.autoValue || '';
                const source = dataSandboxSampleJson?.dataset.sampleSource || '';
                const selectedIndex = Number.parseInt(dataSandboxSamplePicker?.value || '0', 10);
                const selectedSample = dataSandboxSampleEvents[selectedIndex] || null;
                if (selectedSample) {
                    const parts = [];
                    parts.push(`Loaded from raw sample ${selectedIndex + 1}/${dataSandboxSampleEvents.length}.`);
                    const eventName = getDataSandboxSampleEventName(selectedSample);
                    const userValue = getDataSandboxSampleUserValue(selectedSample);
                    if (eventName) {
                        parts.push(`Event ${eventName}.`);
                    }
                    if (userValue) {
                        parts.push(`ID signal ${userValue}.`);
                    }
                    if (source === 'manual' && currentValue && currentValue !== autoValue) {
                        parts.push('The sample setup differs from the loaded raw event.');
                    } else {
                        parts.push('Preview and Coverage use this true raw sample payload.');
                    }
                    dataSandboxSampleMeta.textContent = parts.join(' ');
                    return;
                }
                dataSandboxSampleMeta.textContent = currentValue
                    ? 'Using the current sample setup file for Preview and Coverage.'
                    : 'Load a paused import job to pull true raw sample events into the setup file.';
            }

            function renderDataSandboxGuidedMapping() {
                if (!dataSandboxGuidedMapping) return;
                const connectorName = dataSandboxMappingConnectorSelect.value;
                const selectedJob = getSelectedAwaitingJobForConnector(connectorName);
                const scope = getDataSandboxMappingScope();
                const currentMapping = getDataSandboxCurrentMapping({ silent: true });
                const suggestionsByField = new Map(
                    (dataSandboxFieldSuggestions || []).map((item) => [String(item.field || ''), item])
                );
                const fieldsByPath = new Map(
                    (dataSandboxFieldCandidates || []).map((item) => [String(item.path || ''), item])
                );
                if (dataSandboxGuidedHint) {
                    if (selectedJob) {
                        dataSandboxGuidedHint.textContent = 'The setup reflects the paused import’s effective mapping. Save Mapping Memory updates future imports only; Save and Reprocess Import applies this setup to the paused import and resumes processing.';
                    } else if (connectorName) {
                        dataSandboxGuidedHint.textContent = `Selections here save a ${scope.scopeLabel}. Confirmed saves and successful imports become the memory reused on future loads.`;
                    } else {
                        dataSandboxGuidedHint.textContent = '';
                    }
                }
                if (!connectorName) {
                    dataSandboxGuidedMapping.innerHTML = '';
                    return;
                }
                if (!dataSandboxFieldCandidates.length) {
                    dataSandboxGuidedMapping.innerHTML = '<div class="list-empty">No field candidates.</div>';
                    return;
                }

                dataSandboxGuidedMapping.innerHTML = DATA_SANDBOX_MAPPING_FIELDS.map((fieldConfig) => {
                    const fieldKey = fieldConfig.key;
                    const suggestion = suggestionsByField.get(fieldKey) || null;
                    const currentPath = String(currentMapping[fieldKey] || '');
                    const options = [];
                    const seen = new Set();
                    const pushOption = (path) => {
                        const normalizedPath = String(path || '');
                        if (!normalizedPath || seen.has(normalizedPath)) {
                            return;
                        }
                        seen.add(normalizedPath);
                        options.push({
                            path: normalizedPath,
                            samples: fieldsByPath.get(normalizedPath)?.sample_values || [],
                        });
                    };
                    pushOption(currentPath);
                    pushOption(suggestion?.suggested_path);
                    (suggestion?.alternatives || []).forEach((item) => pushOption(item.path));
                    dataSandboxFieldCandidates.forEach((item) => pushOption(item.path));
                    const memory = getDataSandboxMappingMemory().find((item) => item.key === fieldKey) || null;
                    const optionMarkup = ['<option value="">Select raw field path</option>']
                        .concat(options.map((item) => `<option value="${escapeHtml(item.path)}"${item.path === currentPath ? ' selected' : ''}>${escapeHtml(item.path)}</option>`))
                        .join('');
                    const samplePreview = (fieldsByPath.get(currentPath)?.sample_values || suggestion?.sample_values || []).slice(0, 2);
                    const presenceStats = getDataSandboxFieldPresenceStats(currentPath || suggestion?.suggested_path || '');
                    const suggestionText = suggestion?.suggested_path
                        ? `<div><strong>Suggested:</strong> ${escapeHtml(String(suggestion.suggested_path))}</div>`
                        : '<div><strong>Suggested:</strong> pick the best matching raw property path</div>';
                    const suggestionSourceText = suggestion?.suggested_path
                        ? (
                            (Number(suggestion?.successful_import_count || 0) > 0 || Number(suggestion?.manual_confirmation_count || 0) > 0)
                                ? `<div><strong>Learned from:</strong> ${Number(suggestion?.successful_import_count || 0)} successful import${Number(suggestion?.successful_import_count || 0) === 1 ? '' : 's'} and ${Number(suggestion?.manual_confirmation_count || 0)} confirmed save${Number(suggestion?.manual_confirmation_count || 0) === 1 ? '' : 's'}.</div>`
                                : (memory?.topPath && memory.topPath === suggestion.suggested_path
                                    ? `<div><strong>Learned from:</strong> saved source mapping history (${memory.topCount}/${memory.populatedVersions || 1} matching save${memory.topCount === 1 ? '' : 's'})</div>`
                                    : `<div><strong>Learned from:</strong> ${escapeHtml(String(suggestion.engine || 'raw-field heuristics').replace(/_/g, ' '))}</div>`)
                        )
                        : '<div><strong>Learned from:</strong> no suggestion yet</div>';
                    const sampleText = samplePreview.length
                        ? `<div><strong>Samples:</strong> ${escapeHtml(samplePreview.join(', '))}</div>`
                        : '<div><strong>Samples:</strong> no sample values yet</div>';
                    const presenceText = presenceStats
                        ? `<div><strong>Cross-event signal:</strong> present in ${presenceStats.presentCount}/${presenceStats.totalSamples} sampled events across ${presenceStats.eventNameCount} event name${presenceStats.eventNameCount === 1 ? '' : 's'}.</div>`
                        : '<div><strong>Cross-event signal:</strong> load raw samples to compare this path across event names.</div>';
                    const correctionText = currentPath && suggestion?.suggested_path && currentPath !== suggestion.suggested_path
                        ? `<div><strong>Correction:</strong> the setup currently overrides the suggested path with ${escapeHtml(currentPath)}. Save to persist that correction in the selected scope.</div>`
                        : `<div><strong>Correction:</strong> changing this selector updates the internal mapping immediately.</div>`;
                    const fieldHelpContent = `
                        ${suggestionText}
                        ${suggestionSourceText}
                        ${sampleText}
                        ${presenceText}
                        ${correctionText}
                    `;
                    return `
                        <div class="mapping-guided-card">
                            <div class="field-label-with-help">
                                <label for="data-sandbox-guided-${escapeHtml(fieldKey)}">${escapeHtml(fieldConfig.label)}${fieldConfig.required ? ' *' : ''}</label>
                                ${buildHelpTooltip(fieldHelpContent, `Show ${fieldConfig.label} mapping guidance`)}
                            </div>
                            <select id="data-sandbox-guided-${escapeHtml(fieldKey)}" data-field="${escapeHtml(fieldKey)}">
                                ${optionMarkup}
                            </select>
                        </div>
                    `;
                }).join('');

                dataSandboxGuidedMapping.querySelectorAll('select[data-field]').forEach((select) => {
                    select.addEventListener('change', (event) => {
                        const field = String(event.target.dataset.field || '');
                        const nextMapping = getDataSandboxCurrentMapping({ silent: true });
                        const value = String(event.target.value || '').trim();
                        if (value) {
                            nextMapping[field] = value;
                        } else {
                            delete nextMapping[field];
                        }
                        setDataSandboxMappingJsonValue(nextMapping);
                        renderDataSandboxGuidedMapping();
                    });
                });
            }

            function renderDataSandboxCoverage(result = null) {
                if (!dataSandboxCoverageResult) return;

                if (!result || !result.coverage || !Object.keys(result.coverage).length) {
                    dataSandboxCoverageResult.innerHTML = '';
                    return;
                }

                const score = Math.max(0, Math.min(100, Number(result.required_coverage_score || 0) * 100));
                const scoreColor = score >= 90 ? 'var(--green)' : (score >= 70 ? 'var(--yellow)' : 'var(--red)');
                const cardsHtml = Object.entries(result.coverage || {}).map(([field, stat]) => `
                    <div style="border: 1px solid rgba(148, 163, 184, 0.2); border-radius: 8px; padding: 0.75rem; background: rgba(15, 23, 42, 0.45);">
                        <div style="font-weight: 600; margin-bottom: 0.25rem;">${field}</div>
                        <div style="font-size: 0.8rem; color: var(--text-secondary);">path: ${stat.path || '-'}</div>
                        <div style="font-size: 0.85rem; margin-top: 0.25rem;">hit: ${(Number(stat.hit_rate || 0) * 100).toFixed(1)}% (${stat.hits || 0}/${stat.total || 0})</div>
                    </div>
                `).join('');

                dataSandboxCoverageResult.innerHTML = `
                    <div style="border: 1px solid rgba(148, 163, 184, 0.2); border-radius: 10px; padding: 1rem; background: rgba(15, 23, 42, 0.6);">
                        <div style="display: flex; justify-content: space-between; gap: 1rem; align-items: center; margin-bottom: 0.5rem;">
                            <strong>Coverage</strong>
                            <span style="font-size: 0.85rem; color: var(--text-secondary);">Required score: ${score.toFixed(1)}%</span>
                        </div>
                        <div style="width: 100%; height: 10px; background: rgba(71, 85, 105, 0.5); border-radius: 999px; overflow: hidden; margin-bottom: 1rem;">
                            <div style="width: ${score}%; height: 100%; background: ${scoreColor};"></div>
                        </div>
                        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 0.75rem;">
                            ${cardsHtml}
                        </div>
                    </div>
                `;
            }

            function getSelectedAwaitingJob() {
                const selectedJobId = dataSandboxAwaitingJobSelect.value;
                return dataSandboxAwaitingJobs.find((job) => job.id === selectedJobId) || null;
            }

            async function loadDataSandboxMappingCandidates() {
                const connectorName = dataSandboxMappingConnectorSelect.value;
                if (!connectorName) {
                    dataSandboxFieldCandidates = [];
                    dataSandboxFieldSuggestions = [];
                    setDataSandboxSampleEvents([]);
                    renderDataSandboxGuidedMapping();
                    return;
                }
                const selectedJob = getSelectedAwaitingJobForConnector(connectorName);
                const query = new URLSearchParams();
                if (selectedJob?.id) {
                    query.set('job_id', selectedJob.id);
                }
                const suffix = query.toString() ? `?${query.toString()}` : '';
                const payload = await apiRequest(`/mappings/${encodeURIComponent(connectorName)}/candidates${suffix}`);
                dataSandboxFieldCandidates = Array.isArray(payload.fields) ? payload.fields : [];
                dataSandboxFieldSuggestions = Array.isArray(payload.suggestions) ? payload.suggestions : [];
                setDataSandboxSampleEvents(payload.sample_events, { contextKey: getDataSandboxSampleContextKey(connectorName) });
                renderDataSandboxGuidedMapping();
            }

            async function loadDataSandboxMappingVersions() {
                const connectorName = dataSandboxMappingConnectorSelect.value;
                if (!connectorName) {
                    dataSandboxMappingVersions = [];
                    renderDataSandboxMemory();
                    return;
                }
                try {
                    const payload = await apiRequest(`/mappings/${encodeURIComponent(connectorName)}/versions`);
                    dataSandboxMappingVersions = Array.isArray(payload.items) ? payload.items : [];
                } catch (error) {
                    dataSandboxMappingVersions = [];
                }
                renderDataSandboxMemory();
            }

            async function loadDataSandboxMappingControls() {
                if (shouldBlockProtectedAppData()) {
                    dataSandboxMappingConnectorSelect.innerHTML = '<option value="">Finish workspace setup first</option>';
                    dataSandboxAwaitingJobSelect.innerHTML = '<option value="">Finish workspace setup first</option>';
                    dataSandboxFieldCandidates = [];
                    dataSandboxFieldSuggestions = [];
                    dataSandboxMappingVersions = [];
                    setDataSandboxSampleEvents([]);
                    renderDataSandboxGuidedMapping();
                    renderDataSandboxMemory();
                    dataSandboxLoadMappingBtn.disabled = true;
                    dataSandboxSaveMappingBtn.disabled = true;
                    dataSandboxPreviewMappingBtn.disabled = true;
                    dataSandboxCoverageBtn.disabled = true;
                    dataSandboxProcessMappingBtn.disabled = true;
                    syncDataSandboxMappingActions();
                    setDataSandboxMappingStatus(accessToken ? 'Finish workspace setup to load field mapping controls.' : '');
                    return;
                }
                try {
                    const [connectors, imports] = await Promise.all([
                        refreshConnectorsState(),
                        refreshImportsState(),
                    ]);
                    const sources = connectors.map((source) => ({ id: source.name, name: source.name }));
                    dataSandboxAwaitingJobs = imports.filter((job) => job.status === 'Awaiting Mapping');

                    const previousConnector = dataSandboxMappingConnectorSelect.value;
                    dataSandboxMappingConnectorSelect.innerHTML = '';
                    if (sources.length > 0) {
                        sources.forEach((source) => {
                            const option = document.createElement('option');
                            option.value = source.id;
                            option.textContent = source.name;
                            dataSandboxMappingConnectorSelect.appendChild(option);
                        });
                        const suggestedConnector = dataSandboxAwaitingJobs[0]?.source_stats?.[0]?.source;
                        const selectedConnector = sources.some((source) => source.id === previousConnector)
                            ? previousConnector
                            : (sources.some((source) => source.id === suggestedConnector) ? suggestedConnector : sources[0].id);
                        dataSandboxMappingConnectorSelect.value = selectedConnector;
                    } else {
                        dataSandboxMappingConnectorSelect.innerHTML = '<option value="">No configured connectors</option>';
                    }
                    const hasConnectors = sources.length > 0;
                    dataSandboxLoadMappingBtn.disabled = !hasConnectors;
                    dataSandboxSaveMappingBtn.disabled = !hasConnectors;
                    dataSandboxPreviewMappingBtn.disabled = !hasConnectors;
                    dataSandboxCoverageBtn.disabled = !hasConnectors;

                    const previousJob = dataSandboxAwaitingJobSelect.value;
                    dataSandboxAwaitingJobSelect.innerHTML = '';
                    if (dataSandboxAwaitingJobs.length > 0) {
                        const emptyOption = document.createElement('option');
                        emptyOption.value = '';
                        emptyOption.textContent = 'Select paused import job';
                        dataSandboxAwaitingJobSelect.appendChild(emptyOption);

                        dataSandboxAwaitingJobs.forEach((job) => {
                            const option = document.createElement('option');
                            option.value = job.id;
                            option.textContent = `${job.name} (${job.current_step || job.status})`;
                            option.dataset.source = job.source_stats?.[0]?.source || '';
                            dataSandboxAwaitingJobSelect.appendChild(option);
                        });

                        if (dataSandboxAwaitingJobs.some((job) => job.id === previousJob)) {
                            dataSandboxAwaitingJobSelect.value = previousJob;
                        } else {
                            dataSandboxAwaitingJobSelect.value = dataSandboxAwaitingJobs[0].id;
                        }
                    } else {
                        dataSandboxAwaitingJobSelect.innerHTML = '<option value="">No paused import job</option>';
                    }
                    const selectedJob = getSelectedAwaitingJob();
                    const selectedJobSource = selectedJob?.source_stats?.[0]?.source;
                    if (
                        selectedJobSource &&
                        Array.from(dataSandboxMappingConnectorSelect.options).some((option) => option.value === selectedJobSource)
                    ) {
                        dataSandboxMappingConnectorSelect.value = selectedJobSource;
                    }

                    if ((dataSandboxMappingJson.value || '').trim() === '{}' && dataSandboxMappingConnectorSelect.value) {
                        await loadDataSandboxFieldMapping(true);
                    } else if (dataSandboxMappingConnectorSelect.value) {
                        await Promise.all([
                            loadDataSandboxMappingVersions(),
                            loadDataSandboxMappingCandidates(),
                        ]);
                    }

                    if (dataSandboxAwaitingJobs.length > 0) {
                        const activeJob = getSelectedAwaitingJobForConnector(dataSandboxMappingConnectorSelect.value) || dataSandboxAwaitingJobs[0];
                        setDataSandboxMappingStatus(`Paused import job detected: ${activeJob.name}. Save Mapping Memory updates future imports only. Click "Save and Reprocess Import" to continue the paused import.`);
                    } else {
                        setDataSandboxMappingStatus('No paused import jobs. You can still edit, preview, and save connector mapping memory locally for future imports.');
                    }
                    syncDataSandboxMappingActions();
                    syncDataSandboxReprocessState(imports);
                } catch (error) {
                    if (isWorkspaceContextError(error)) {
                        dataSandboxMappingConnectorSelect.innerHTML = '<option value="">Finish workspace setup first</option>';
                        dataSandboxAwaitingJobSelect.innerHTML = '<option value="">Finish workspace setup first</option>';
                        dataSandboxFieldCandidates = [];
                        dataSandboxFieldSuggestions = [];
                        dataSandboxMappingVersions = [];
                        setDataSandboxSampleEvents([]);
                        renderDataSandboxGuidedMapping();
                        renderDataSandboxMemory();
                        dataSandboxLoadMappingBtn.disabled = true;
                        dataSandboxSaveMappingBtn.disabled = true;
                        dataSandboxPreviewMappingBtn.disabled = true;
                        dataSandboxCoverageBtn.disabled = true;
                        dataSandboxProcessMappingBtn.disabled = true;
                        syncDataSandboxMappingActions();
                        setDataSandboxMappingStatus(getWorkspaceResolutionMessage(error.payload || authSessionState));
                        return;
                    }
                    dataSandboxFieldCandidates = [];
                    dataSandboxFieldSuggestions = [];
                    dataSandboxMappingVersions = [];
                    setDataSandboxSampleEvents([]);
                    renderDataSandboxGuidedMapping();
                    renderDataSandboxMemory();
                    syncDataSandboxMappingActions();
                    setDataSandboxMappingStatus(error.message || 'Failed to load field mapping controls.', true);
                }
            }

            async function loadDataSandboxFieldMapping(silent = false) {
                const connectorName = dataSandboxMappingConnectorSelect.value;
                if (!connectorName) {
                    setDataSandboxMappingStatus('Select a connector first.', true);
                    return;
                }

                try {
                    const scope = getDataSandboxMappingScope();
                    const query = new URLSearchParams();
                    if (scope.scopeType !== 'source') {
                        query.set('scope_type', scope.scopeType);
                    }
                    if (scope.scopeKey) {
                        query.set('scope_key', scope.scopeKey);
                    }
                    const suffix = query.toString() ? `?${query.toString()}` : '';
                    const data = await apiRequest(`/mappings/${encodeURIComponent(connectorName)}${suffix}`);
                    const nextMapping = scope.scopeType === 'job'
                        ? (data.effective_mapping || data.mapping || {})
                        : (data.mapping || {});
                    setDataSandboxMappingJsonValue(nextMapping);
                    await Promise.all([
                        loadDataSandboxMappingVersions(),
                        loadDataSandboxMappingCandidates(),
                    ]);
                    renderDataSandboxMemory();
                    syncDataSandboxMappingActions();
                    if (!silent) {
                        setDataSandboxMappingStatus(`Loaded ${scope.scopeLabel}.`);
                    }
                } catch (error) {
                    dataSandboxFieldCandidates = [];
                    dataSandboxFieldSuggestions = [];
                    dataSandboxMappingVersions = [];
                    setDataSandboxSampleEvents([]);
                    renderDataSandboxGuidedMapping();
                    renderDataSandboxMemory();
                    syncDataSandboxMappingActions();
                    setDataSandboxMappingStatus(error.message || 'Failed to load field mapping.', true);
                }
            }

            async function saveDataSandboxFieldMapping(options = {}) {
                const { silent = false, reload = true, rethrow = false } = options;
                const connectorName = dataSandboxMappingConnectorSelect.value;
                if (!connectorName) {
                    setDataSandboxMappingStatus('Select a connector first.', true);
                    return;
                }

                try {
                    const mapping = getDataSandboxCurrentMapping();
                    const scope = getSelectedAwaitingJobForConnector(connectorName)
                        ? getDataSandboxSourceScope()
                        : getDataSandboxMappingScope();
                    await apiRequest(`/mappings/${encodeURIComponent(connectorName)}`, {
                        method: 'PUT',
                        body: {
                            mapping,
                            scope_type: scope.scopeType,
                            scope_key: scope.scopeKey,
                        },
                    });
                    if (reload) {
                        await loadDataSandboxFieldMapping(true);
                    }
                    if (!silent) {
                        if (getSelectedAwaitingJobForConnector(connectorName)) {
                            setDataSandboxMappingStatus(`Saved ${scope.scopeLabel}. Click "Save and Reprocess Import" to rerun the paused import with this corrected mapping.`);
                        } else {
                            setDataSandboxMappingStatus(`Saved ${scope.scopeLabel}.`);
                        }
                    }
                } catch (error) {
                    setDataSandboxMappingStatus(error.message || 'Failed to save field mapping.', true);
                    if (rethrow) {
                        throw error;
                    }
                }
            }

            async function previewDataSandboxFieldMapping() {
                const connectorName = dataSandboxMappingConnectorSelect.value;
                if (!connectorName) {
                    setDataSandboxMappingStatus('Select a connector first.', true);
                    return;
                }

                try {
                    const sampleRecord = JSON.parse(dataSandboxSampleJson.value || '{}');
                    const mapping = JSON.parse(dataSandboxMappingJson.value || '{}');
                    const preview = previewMappedEvent(connectorName, sampleRecord, mapping);
                    renderJsonOutput(dataSandboxPreviewResult, preview || {}, 'No mapping preview available.');
                    setDataSandboxMappingStatus(`Preview generated for ${connectorName}.`);
                } catch (error) {
                    renderJsonOutput(dataSandboxPreviewResult, null, '');
                    setDataSandboxMappingStatus(error.message || 'Failed to preview field mapping.', true);
                }
            }

            async function loadDataSandboxMappingCoverage() {
                const connectorName = dataSandboxMappingConnectorSelect.value;
                if (!connectorName) {
                    setDataSandboxMappingStatus('Select a connector first.', true);
                    return;
                }

                try {
                    const sampleRecord = JSON.parse(dataSandboxSampleJson.value || '{}');
                    const mapping = JSON.parse(dataSandboxMappingJson.value || '{}');
                    const data = buildMappingCoverage(mapping, sampleRecord ? [sampleRecord] : []);
                    renderDataSandboxCoverage(data);
                    setDataSandboxMappingStatus(`Coverage calculated for ${connectorName}.`);
                } catch (error) {
                    renderDataSandboxCoverage(null);
                    setDataSandboxMappingStatus(error.message || 'Failed to calculate mapping coverage.', true);
                }
            }

            async function processDataSandboxAwaitingJob() {
                const selectedJob = getSelectedAwaitingJobForConnector(dataSandboxMappingConnectorSelect.value);
                if (!selectedJob) {
                    setDataSandboxMappingStatus('Select a paused Awaiting Mapping import before trying to reprocess it.', true);
                    return;
                }
                if (dataSandboxProcessMappingBtn) {
                    dataSandboxProcessMappingBtn.disabled = true;
                }
                try {
                    const mapping = getDataSandboxCurrentMapping();
                    const resumed = await apiRequest(`/imports/${encodeURIComponent(selectedJob.id)}/remap-and-resume?background=true`, {
                        method: 'POST',
                        body: {
                            mapping,
                            persist_source_mapping: true,
                        },
                    });
                    dataSandboxReprocessJobId = selectedJob.id;
                    dataSandboxReprocessJobName = selectedJob.name || resumed.name || selectedJob.id;
                    importExpandedJobIds.add(selectedJob.id);
                    await refreshImportsState();
                    await loadImportedDataList();
                    await loadDataSandboxMappingControls();
                    syncDataSandboxReprocessState(cachedImports);
                    if (resumed.started === false) {
                        setDataSandboxMappingStatus(`Reprocessing ${dataSandboxReprocessJobName} is already in progress. Status will update below.`);
                    }
                } catch (error) {
                    setDataSandboxMappingStatus(error.message || 'Failed to process the paused import after saving mapping.', true);
                } finally {
                    syncDataSandboxMappingActions();
                }
            }

            dataSandboxMappingConnectorSelect.addEventListener('change', async () => {
                renderDataSandboxCoverage(null);
                dataSandboxPreviewResult.textContent = '';
                syncDataSandboxMappingActions();
                await loadDataSandboxFieldMapping(true);
            });

            dataSandboxAwaitingJobSelect.addEventListener('change', async () => {
                const selectedJob = getSelectedAwaitingJob();
                const selectedJobSource = selectedJob?.source_stats?.[0]?.source;
                if (
                    selectedJobSource &&
                    Array.from(dataSandboxMappingConnectorSelect.options).some((option) => option.value === selectedJobSource)
                ) {
                    dataSandboxMappingConnectorSelect.value = selectedJobSource;
                    syncDataSandboxMappingActions();
                    await loadDataSandboxFieldMapping(true);
                } else {
                    syncDataSandboxMappingActions();
                    await loadDataSandboxMappingCandidates();
                }
                renderDataSandboxCoverage(null);
            });

