            const COPILOT_AGENT_READY_PLACEHOLDER = 'Ask how to use this page, request a sample payload, summarize the dashboard, or tell the agent to set something up.';
            const COPILOT_AGENT_LOADING_PLACEHOLDER = 'Getting Agents Ready...';

            function setInlineStatus(element, message = '', isError = false) {
                if (!element) return;
                element.textContent = message;
                element.style.color = isError ? 'var(--red)' : 'var(--text-secondary)';
            }

            function setCopilotAgentComposerReady(isReady, { placeholder = '' } = {}) {
                copilotAgentComposerReady = Boolean(isReady);
                const resolvedPlaceholder = placeholder || (
                    copilotAgentComposerReady
                        ? COPILOT_AGENT_READY_PLACEHOLDER
                        : COPILOT_AGENT_LOADING_PLACEHOLDER
                );
                if (copilotAgentMessageInput) {
                    copilotAgentMessageInput.disabled = !copilotAgentComposerReady;
                    copilotAgentMessageInput.setAttribute('aria-disabled', copilotAgentComposerReady ? 'false' : 'true');
                    copilotAgentMessageInput.placeholder = resolvedPlaceholder;
                }
                if (copilotAgentSendBtn) {
                    copilotAgentSendBtn.disabled = !copilotAgentComposerReady;
                    copilotAgentSendBtn.setAttribute('aria-disabled', copilotAgentComposerReady ? 'false' : 'true');
                }
            }

            setCopilotAgentComposerReady(false);

            const jsonExportPayloads = new WeakMap();

            function normalizeJsonExportPayload(payload) {
                if (typeof payload !== 'string') {
                    return payload;
                }
                const trimmed = payload.trim();
                if (!trimmed) {
                    return '';
                }
                try {
                    return JSON.parse(trimmed);
                } catch (error) {
                    return { value: payload };
                }
            }

            function getJsonExportFilename(element) {
                const base = String(element?.id || 'kairyx-output')
                    .replace(/-output$/, '')
                    .replace(/[^a-z0-9_-]+/gi, '-')
                    .replace(/^-+|-+$/g, '')
                    .toLowerCase() || 'kairyx-output';
                const stamp = new Date().toISOString().replace(/[:.]/g, '-');
                return `${base}-${stamp}.json`;
            }

            function downloadJsonPayload(payload, filename) {
                const blob = new Blob([`${JSON.stringify(payload, null, 2)}\n`], { type: 'application/json' });
                const url = URL.createObjectURL(blob);
                const link = document.createElement('a');
                link.href = url;
                link.download = filename;
                document.body.appendChild(link);
                link.click();
                link.remove();
                URL.revokeObjectURL(url);
            }

            function ensureJsonExportButton(element) {
                if (!element) return null;
                const buttonId = element.id ? `${element.id}-export-json-btn` : '';
                if (buttonId) {
                    const existing = document.getElementById(buttonId);
                    if (existing) {
                        return existing;
                    }
                }
                const actions = document.createElement('div');
                actions.className = 'json-export-actions';
                const button = document.createElement('button');
                button.type = 'button';
                button.className = 'secondary-button json-export-button';
                button.textContent = 'Export .json';
                if (buttonId) {
                    button.id = buttonId;
                }
                button.addEventListener('click', () => {
                    if (!jsonExportPayloads.has(element)) {
                        return;
                    }
                    downloadJsonPayload(jsonExportPayloads.get(element), getJsonExportFilename(element));
                });
                actions.appendChild(button);
                element.insertAdjacentElement('afterend', actions);
                return button;
            }

            function renderJsonOutput(element, payload, emptyMessage = 'No data available.') {
                if (!element) return;
                if (payload === null || payload === undefined || payload === '') {
                    jsonExportPayloads.delete(element);
                    element.classList.add('json-export-summary');
                    element.textContent = emptyMessage;
                    const exportButton = ensureJsonExportButton(element);
                    if (exportButton) {
                        exportButton.hidden = true;
                        exportButton.disabled = true;
                        if (exportButton.parentElement) {
                            exportButton.parentElement.hidden = true;
                        }
                    }
                    return;
                }
                const exportPayload = normalizeJsonExportPayload(payload);
                jsonExportPayloads.set(element, exportPayload);
                element.classList.add('json-export-summary');
                element.textContent = 'Structured setup file ready. Export .json to inspect the full payload.';
                const exportButton = ensureJsonExportButton(element);
                if (exportButton) {
                    exportButton.hidden = false;
                    exportButton.disabled = false;
                    if (exportButton.parentElement) {
                        exportButton.parentElement.hidden = false;
                    }
                }
            }

            const noCodeSetupArtifacts = [
                { inputId: 'data-sandbox-mapping-json', outputId: 'data-sandbox-mapping-json-artifact', emptyMessage: 'No mapping setup file loaded.' },
                { inputId: 'data-sandbox-sample-json', outputId: 'data-sandbox-sample-json-artifact', emptyMessage: 'No sample event loaded.' },
                { inputId: 'sql-workspace-textarea', outputId: 'sql-workspace-artifact', kind: 'sql', emptyMessage: 'No SQL artifact loaded.' },
                { inputId: 'email-campaign-merge-fields-input', outputId: 'email-campaign-merge-fields-artifact', emptyMessage: 'No merge fields setup loaded.' },
                { inputId: 'push-dispatch-data-input', outputId: 'push-dispatch-data-artifact', emptyMessage: 'No push data setup loaded.' },
                { inputId: 'push-dispatch-provider-options-input', outputId: 'push-dispatch-provider-options-artifact', emptyMessage: 'No provider options setup loaded.' },
                { inputId: 'push-dispatch-wynn-filters-input', outputId: 'push-dispatch-wynn-filters-artifact', emptyMessage: 'No Wynn filters setup loaded.' },
                { inputId: 'workflow-push-data-input', outputId: 'workflow-push-data-artifact', emptyMessage: 'No workflow push data setup loaded.' },
                { inputId: 'workflow-push-provider-options-input', outputId: 'workflow-push-provider-options-artifact', emptyMessage: 'No workflow provider options setup loaded.' },
                { inputId: 'activation-callbacks-json', outputId: 'activation-callbacks-artifact', emptyMessage: 'No callback payload setup loaded.' },
                { inputId: 'experiment-outcomes-json', outputId: 'experiment-outcomes-artifact', emptyMessage: 'No outcome payload setup loaded.' },
                { inputId: 'copilot-query-filters-json', outputId: 'copilot-query-filters-artifact', emptyMessage: 'No filter setup loaded.' },
                { inputId: 'copilot-insight-json', outputId: 'copilot-insight-artifact', emptyMessage: 'No insight context loaded.' },
                { inputId: 'copilot-metric-context-json', outputId: 'copilot-metric-context-artifact', emptyMessage: 'No metric context loaded.' },
            ];

            function buildNoCodeSetupArtifactPayload(input, definition = {}) {
                const raw = String(input?.value || '').trim();
                if (!raw) {
                    return null;
                }
                if (definition.kind === 'sql') {
                    return {
                        format: 'sql_workspace_artifact.v1',
                        sql: raw,
                    };
                }
                return normalizeJsonExportPayload(raw);
            }

            function syncNoCodeSetupArtifacts(inputIds = null) {
                const filterIds = Array.isArray(inputIds) && inputIds.length ? new Set(inputIds) : null;
                noCodeSetupArtifacts.forEach((definition) => {
                    if (filterIds && !filterIds.has(definition.inputId)) {
                        return;
                    }
                    const input = document.getElementById(definition.inputId);
                    const output = document.getElementById(definition.outputId);
                    if (!input || !output) {
                        return;
                    }
                    renderJsonOutput(
                        output,
                        buildNoCodeSetupArtifactPayload(input, definition),
                        definition.emptyMessage || 'No setup file loaded.',
                    );
                });
            }

            function hideTechnicalJsonInputs() {
                const jsonInputIds = [
                    'data-sandbox-mapping-json',
                    'data-sandbox-sample-json',
                    'sql-workspace-textarea',
                    'email-campaign-merge-fields-input',
                    'push-dispatch-data-input',
                    'push-dispatch-provider-options-input',
                    'push-dispatch-wynn-filters-input',
                    'workflow-push-data-input',
                    'workflow-push-provider-options-input',
                    'activation-callbacks-json',
                    'experiment-outcomes-json',
                    'copilot-query-filters-json',
                    'copilot-insight-json',
                    'copilot-metric-context-json',
                ];
                const shellsToHide = new Set();
                jsonInputIds.forEach((id) => {
                    const input = document.getElementById(id);
                    if (!input) return;
                    if (String(input.getAttribute('type') || '').toLowerCase() === 'hidden') {
                        input.dataset.operatorJsonInput = 'state';
                        return;
                    }
                    const details = input.closest('details.builder-advanced-panel');
                    const shell = details || input.closest('.form-group') || input;
                    shellsToHide.add(shell);
                    input.setAttribute('aria-hidden', 'true');
                    input.setAttribute('tabindex', '-1');
                    input.dataset.operatorJsonInput = 'hidden';
                });
                shellsToHide.forEach((shell) => {
                    shell.classList.add('hidden');
                    shell.setAttribute('aria-hidden', 'true');
                });
            }

            hideTechnicalJsonInputs();
            syncNoCodeSetupArtifacts();

            function parseJsonText(value, fallback = {}) {
                const raw = String(value || '').trim();
                if (!raw) return fallback;
                return JSON.parse(raw);
            }

            function splitCsv(value) {
                return String(value || '')
                    .split(',')
                    .map((item) => item.trim())
                    .filter(Boolean);
            }

            function formatDateTime(value) {
                if (!value) return '-';
                const parsed = parseIsoDate(value);
                return Number.isNaN(parsed.getTime()) ? '-' : parsed.toLocaleString();
            }

            function formatMonitorScore(value) {
                if (value === null || value === undefined || value === '') return '-';
                const parsed = Number(value);
                return Number.isFinite(parsed) ? parsed.toFixed(2) : '-';
            }

            function formatMonitorPercent(value) {
                if (value === null || value === undefined || value === '') return '-';
                const parsed = Number(value);
                return Number.isFinite(parsed) ? `${Math.round(parsed * 100)}%` : '-';
            }

            function formatMonitorLabel(value) {
                return String(value || '-').replace(/_/g, ' ');
            }

            function renderMetricList(container, payload = {}, emptyMessage = 'No metrics available.') {
                if (!container) return;
                const entries = Object.entries(payload || {});
                if (entries.length === 0) {
                    container.innerHTML = `<div class="list-empty">${escapeHtml(emptyMessage)}</div>`;
                    return;
                }
                container.innerHTML = entries.map(([key, value]) => `
                    <div class="metric-line">
                        <span>${escapeHtml(String(key).replace(/_/g, ' '))}</span>
                        <strong>${escapeHtml(typeof value === 'object' ? JSON.stringify(value) : String(value))}</strong>
                    </div>
                `).join('');
            }

            function renderSimpleTable(container, columns, items, emptyMessage = 'No records found.') {
                if (!container) return;
                if (!Array.isArray(items) || items.length === 0) {
                    container.innerHTML = `<div class="list-empty">${escapeHtml(emptyMessage)}</div>`;
                    return;
                }
                const head = columns.map((column) => `<th>${escapeHtml(column.label)}</th>`).join('');
                const rows = items.map((item) => `
                    <tr>
                        ${columns.map((column) => `<td>${column.render ? column.render(item) : escapeHtml(String(item[column.key] ?? '-'))}</td>`).join('')}
                    </tr>
                `).join('');
                container.innerHTML = `
                    <div class="table-shell">
                        <table>
                            <thead><tr>${head}</tr></thead>
                            <tbody>${rows}</tbody>
                        </table>
                    </div>
                `;
            }

            function getCurrentExperimentId() {
                return (document.getElementById('experiment-id-input').value || 'churn_rescue_v1').trim() || 'churn_rescue_v1';
            }

            function getCurrentWorkflowReferenceTime() {
                return (document.getElementById('orchestrator-reference-time-input').value || '').trim() || null;
            }

            function getCohortSourceLabel(cohort = {}) {
                return String(cohort?.source_label || cohort?.source_kind || '').trim();
            }

            function formatCohortSelectLabel(cohort = {}) {
                const sourceLabel = getCohortSourceLabel(cohort);
                const statusLabel = String(cohort?.status || 'unknown').trim();
                const baseLabel = String(cohort?.name || cohort?.cohort_id || 'Cohort').trim();
                return sourceLabel ? `${baseLabel} (${statusLabel}) · ${sourceLabel}` : `${baseLabel} (${statusLabel})`;
            }

            function populateCohortSelectOptions(select, cohorts = []) {
                if (!select) {
                    return;
                }
                const previousValue = select.value;
                select.innerHTML = '<option value="">Select cohort</option>';
                cohorts.forEach((cohort) => {
                    const option = document.createElement('option');
                    option.value = cohort.cohort_id;
                    option.textContent = formatCohortSelectLabel(cohort);
                    select.appendChild(option);
                });
                if (cohorts.some((item) => item.cohort_id === previousValue)) {
                    select.value = previousValue;
                }
            }

            function populateWorkflowCohortSelect(cohorts = []) {
                populateCohortSelectOptions(document.getElementById('workflow-cohort-select'), cohorts);
                populateCohortSelectOptions(pushDispatchCohortSelect, cohorts);
            }

            function populatePushProviderSelect(selectElement, { preferredValue } = {}) {
                if (!selectElement) {
                    return;
                }
                const hasPreferredValue = preferredValue !== undefined;
                const previousValue = String(hasPreferredValue ? preferredValue : (selectElement.value || '')).trim();
                const providers = getPushWorkflowProviderConnections();
                selectElement.innerHTML = '';
                const placeholder = document.createElement('option');
                placeholder.value = '';
                placeholder.textContent = 'Simulator only (no provider connection)';
                selectElement.appendChild(placeholder);
                providers.forEach((provider) => {
                    const option = document.createElement('option');
                    option.value = provider.provider_connection_id;
                    option.textContent = `${provider.name} (${(provider.config || {}).base_url || 'configured'})`;
                    selectElement.appendChild(option);
                });
                if (previousValue && providers.some((item) => item.provider_connection_id === previousValue)) {
                    selectElement.value = previousValue;
                    return;
                }
                selectElement.value = '';
            }

            function populateWorkflowPushProviderSelect({ preferredValue = '' } = {}) {
                populatePushProviderSelect(workflowPushProviderConnectionSelect, { preferredValue });
            }

            function populatePushDispatchProviderSelect({ preferredValue = '' } = {}) {
                populatePushProviderSelect(pushDispatchProviderConnectionSelect, { preferredValue });
            }

            function getPushComposerMode() {
                return String(pushDispatchModeSelect?.value || 'single').trim().toLowerCase() || 'single';
            }

            function getPushComposerSingleTiming() {
                return String(pushDispatchSingleTimingSelect?.value || 'immediate').trim().toLowerCase() || 'immediate';
            }

            function getPushComposerAudienceType() {
                return String(pushDispatchAudienceTypeSelect?.value || 'user_ids').trim().toLowerCase() || 'user_ids';
            }

            function getSelectedPushDispatchProvider() {
                const providerConnectionId = String(pushDispatchProviderConnectionSelect?.value || '').trim();
                return providerConnectionId ? findProviderConnection(providerConnectionId) : null;
            }

            function isSelectedWynnPushProvider() {
                const provider = getSelectedPushDispatchProvider();
                return String(provider?.provider || '').trim().toLowerCase() === 'wynn_push_notifier';
            }

            function getPushComposerAudienceSelection() {
                const audienceType = getPushComposerAudienceType();
                const userIds = splitCsv(pushDispatchUserIdInput?.value || '');
                const cohortId = String(pushDispatchCohortSelect?.value || '').trim();
                const cohort = cohortId ? findCohort(cohortId) : null;
                if (audienceType === 'cohort') {
                    return {
                        audienceType,
                        audienceMode: 'cohort',
                        cohortId,
                        cohort,
                        userIds: [],
                        label: cohort?.name || cohortId || 'selected cohort',
                    };
                }
                if (audienceType === 'all_players') {
                    return {
                        audienceType,
                        audienceMode: 'provider_campaign',
                        cohortId: null,
                        cohort: null,
                        userIds: [],
                        label: 'all players',
                    };
                }
                return {
                    audienceType: 'user_ids',
                    audienceMode: 'provider_campaign',
                    cohortId: null,
                    cohort: null,
                    userIds,
                    label: `${userIds.length || 0} user${userIds.length === 1 ? '' : 's'}`,
                };
            }

            function syncPushDispatchAudienceFieldState() {
                const audienceType = getPushComposerAudienceType();
                if (pushDispatchUserIdGroup) {
                    pushDispatchUserIdGroup.style.display = audienceType === 'user_ids' ? 'block' : 'none';
                }
                if (pushDispatchCohortGroup) {
                    pushDispatchCohortGroup.style.display = audienceType === 'cohort' ? 'block' : 'none';
                }
                if (pushDispatchAllPlayersNote) {
                    pushDispatchAllPlayersNote.style.display = audienceType === 'all_players' ? 'block' : 'none';
                }
                if (pushDispatchUserIdInput) {
                    pushDispatchUserIdInput.required = false;
                    pushDispatchUserIdInput.removeAttribute('required');
                    pushDispatchUserIdInput.setCustomValidity('');
                }
                if (pushDispatchCohortSelect) {
                    pushDispatchCohortSelect.required = false;
                    pushDispatchCohortSelect.removeAttribute('required');
                    pushDispatchCohortSelect.setCustomValidity('');
                }
            }

            function validatePushComposerAudience({ audienceType, cohortId, cohort, userIds, providerConnectionId }) {
                syncPushDispatchAudienceFieldState();
                if (audienceType === 'cohort') {
                    if (!cohortId) {
                        throw new Error('Select an active cohort before sending or scheduling a push.');
                    }
                    if (String(cohort?.status || '').trim().toLowerCase() !== 'active') {
                        throw new Error('Activate the selected cohort before sending or scheduling a push.');
                    }
                    return;
                }
                if (audienceType === 'all_players') {
                    if (String(providerConnectionId || '').trim()) {
                        return;
                    }
                    throw new Error('All-player push sends require a live Wynn PushNotifier provider connection.');
                }
                if (Array.isArray(userIds) && userIds.length > 0) {
                    return;
                }
                throw new Error('Enter one or more User IDs, or switch the audience to Cohort or All players.');
            }

            function parseOptionalWholeNumberInput(input, label, { min = 0, max = null } = {}) {
                const raw = String(input?.value || '').trim();
                if (!raw) {
                    return null;
                }
                const value = Number(raw);
                if (!Number.isInteger(value)) {
                    throw new Error(`${label} must be a whole number.`);
                }
                if (value < min) {
                    throw new Error(`${label} must be at least ${min}.`);
                }
                if (max !== null && value > max) {
                    throw new Error(`${label} must be at most ${max}.`);
                }
                return value;
            }

            function buildPushComposerPolicyPayload() {
                const globalDailyLimit = parseOptionalWholeNumberInput(pushDispatchGlobalLimitInput, 'Global daily limit');
                const channelDailyLimit = parseOptionalWholeNumberInput(pushDispatchChannelLimitInput, 'Channel daily limit');
                const cooldownHours = parseOptionalWholeNumberInput(pushDispatchCooldownHoursInput, 'Cooldown hours');
                const quietStart = parseOptionalWholeNumberInput(pushDispatchQuietStartInput, 'Quiet hours start', { min: 0, max: 23 });
                const quietEnd = parseOptionalWholeNumberInput(pushDispatchQuietEndInput, 'Quiet hours end', { min: 0, max: 23 });
                if ((quietStart === null) !== (quietEnd === null)) {
                    throw new Error('Set both quiet-hours values or leave both blank.');
                }
                return {
                    global_daily_limit: globalDailyLimit,
                    channel_daily_limit: channelDailyLimit,
                    cooldown_hours: cooldownHours,
                    blacklist_ids: splitCsv(pushDispatchBlacklistInput?.value || ''),
                    quiet_hours: quietStart === null ? null : { start: quietStart, end: quietEnd },
                };
            }

            function buildPushComposerBudgetPolicyPayload() {
                const dailyBudgetLimit = parseOptionalWholeNumberInput(pushDispatchBudgetLimitInput, 'Daily budget limit');
                return {
                    daily_budget_limit: dailyBudgetLimit,
                    daily_delivery_limit: dailyBudgetLimit,
                };
            }

            function syncPushDispatchComposerFields() {
                const mode = getPushComposerMode();
                const singleTiming = getPushComposerSingleTiming();
                const audienceType = getPushComposerAudienceType();
                syncPushDispatchAudienceFieldState();
                if (pushDispatchSingleTimingGroup) {
                    pushDispatchSingleTimingGroup.style.display = mode === 'single' ? 'block' : 'none';
                }
                if (pushDispatchScheduleOnceGroup) {
                    pushDispatchScheduleOnceGroup.style.display = mode === 'single' && singleTiming === 'schedule_once' ? 'block' : 'none';
                }
                if (pushDispatchRepeatScheduleGroup) {
                    pushDispatchRepeatScheduleGroup.style.display = mode === 'repeated' ? 'grid' : 'none';
                }
                if (pushDispatchWynnFiltersGroup) {
                    pushDispatchWynnFiltersGroup.style.display = isSelectedWynnPushProvider() ? 'block' : 'none';
                }
                if (pushDispatchSendNowBtn) {
                    if (mode === 'repeated') {
                        pushDispatchSendNowBtn.textContent = 'Create Repeated Workflow';
                    } else if (singleTiming === 'schedule_once') {
                        pushDispatchSendNowBtn.textContent = 'Schedule Once';
                    } else if (audienceType === 'cohort') {
                        pushDispatchSendNowBtn.textContent = 'Run Cohort Now';
                    } else {
                        pushDispatchSendNowBtn.textContent = 'Send Now';
                    }
                }
            }

            function buildPushComposerProviderOptions() {
                const providerOptions = parseJsonText(pushDispatchProviderOptionsInput?.value, {});
                if (isSelectedWynnPushProvider()) {
                    const wynnFilters = parseJsonText(pushDispatchWynnFiltersInput?.value, {});
                    if (wynnFilters && Object.keys(wynnFilters).length > 0) {
                        providerOptions.filters = wynnFilters;
                    }
                }
                return providerOptions;
            }

            function resetPushDispatchForm({ preserveProviderConnection = false } = {}) {
                const preservedProviderConnectionId = preserveProviderConnection
                    ? String(pushDispatchProviderConnectionSelect?.value || '').trim()
                    : '';
                if (pushDispatchNameInput) {
                    pushDispatchNameInput.value = '';
                }
                if (pushDispatchModeSelect) {
                    pushDispatchModeSelect.value = 'single';
                }
                if (pushDispatchSingleTimingSelect) {
                    pushDispatchSingleTimingSelect.value = 'immediate';
                }
                if (pushDispatchAudienceTypeSelect) {
                    pushDispatchAudienceTypeSelect.value = 'user_ids';
                }
                if (pushDispatchUserIdInput) {
                    pushDispatchUserIdInput.value = '';
                }
                if (pushDispatchCohortSelect) {
                    pushDispatchCohortSelect.value = '';
                }
                if (pushDispatchScheduleOnceInput) {
                    pushDispatchScheduleOnceInput.value = '';
                }
                if (pushDispatchRepeatHourInput) {
                    pushDispatchRepeatHourInput.value = 10;
                }
                if (pushDispatchRepeatMinuteInput) {
                    pushDispatchRepeatMinuteInput.value = 0;
                }
                populatePushDispatchProviderSelect({ preferredValue: preservedProviderConnectionId });
                if (pushDispatchCampaignNameInput) {
                    pushDispatchCampaignNameInput.value = '';
                }
                if (pushDispatchTitleInput) {
                    pushDispatchTitleInput.value = '';
                }
                if (pushDispatchBodyInput) {
                    pushDispatchBodyInput.value = '';
                }
                if (pushDispatchDeepLinkInput) {
                    pushDispatchDeepLinkInput.value = '';
                }
                if (pushDispatchDeepLinkTokenInput) {
                    pushDispatchDeepLinkTokenInput.value = '';
                }
                if (pushDispatchGlobalLimitInput) {
                    pushDispatchGlobalLimitInput.value = '';
                }
                if (pushDispatchChannelLimitInput) {
                    pushDispatchChannelLimitInput.value = '';
                }
                if (pushDispatchCooldownHoursInput) {
                    pushDispatchCooldownHoursInput.value = '';
                }
                if (pushDispatchQuietStartInput) {
                    pushDispatchQuietStartInput.value = '';
                }
                if (pushDispatchQuietEndInput) {
                    pushDispatchQuietEndInput.value = '';
                }
                if (pushDispatchBudgetLimitInput) {
                    pushDispatchBudgetLimitInput.value = '';
                }
                if (pushDispatchBlacklistInput) {
                    pushDispatchBlacklistInput.value = '';
                }
                if (pushDispatchDataInput) {
                    pushDispatchDataInput.value = '{}';
                }
                if (pushDispatchProviderOptionsInput) {
                    pushDispatchProviderOptionsInput.value = '{}';
                }
                if (pushDispatchWynnFiltersInput) {
                    pushDispatchWynnFiltersInput.value = '{}';
                }
                syncNoCodeSetupArtifacts([
                    'push-dispatch-data-input',
                    'push-dispatch-provider-options-input',
                    'push-dispatch-wynn-filters-input',
                ]);
                renderJsonOutput(pushDispatchOutput, null, 'No push composer action submitted yet.');
                setInlineStatus(pushDispatchStatus, 'Ready to send or schedule a push.');
                syncPushDispatchComposerFields();
            }

            function syncWorkflowChannelFields() {
                const channel = String(workflowChannelSelect?.value || 'push_notification').trim().toLowerCase() || 'push_notification';
                if (workflowPushFields) {
                    workflowPushFields.style.display = channel === 'push_notification' ? 'block' : 'none';
                }
                if (workflowEmailFields) {
                    workflowEmailFields.style.display = channel === 'email' ? 'block' : 'none';
                }
            }

            function syncWorkflowBuilderState(workflow = null) {
                const selected = workflow && workflow.workflow_id ? workflow : null;
                selectedWorkflowBuilderId = selected ? selected.workflow_id : null;
                if (workflowBuilderSelectedLabel) {
                    workflowBuilderSelectedLabel.textContent = selected
                        ? `${selected.name || selected.workflow_id} · ${String(selected.status || 'draft').replace(/[_-]+/g, ' ')}`
                        : 'No push workflow selected';
                }
                const createButton = document.getElementById('workflow-create-btn');
                if (createButton) {
                    createButton.textContent = selected ? 'Update Push Workflow' : 'Create Push Workflow';
                }
            }

            function resetWorkflowBuilderForm() {
                selectedWorkflowBuilderId = null;
                document.getElementById('workflow-name-input').value = '';
                document.getElementById('workflow-cohort-select').value = '';
                document.getElementById('workflow-experiment-id-input').value = 'churn_rescue_v1';
                document.getElementById('workflow-trigger-type-select').value = 'daily_schedule';
                document.getElementById('workflow-trigger-hour-input').value = 10;
                document.getElementById('workflow-trigger-minute-input').value = 0;
                if (workflowChannelSelect) {
                    workflowChannelSelect.value = 'push_notification';
                }
                document.getElementById('workflow-global-limit-input').value = 5;
                document.getElementById('workflow-channel-limit-input').value = 5;
                document.getElementById('workflow-cooldown-hours-input').value = 24;
                document.getElementById('workflow-quiet-start-input').value = 22;
                document.getElementById('workflow-quiet-end-input').value = 7;
                document.getElementById('workflow-budget-limit-input').value = 25;
                document.getElementById('workflow-blacklist-input').value = '';
                if (workflowContentInput) {
                    workflowContentInput.value = 'Come back for a reward.';
                }
                if (workflowPushProviderConnectionSelect) {
                    workflowPushProviderConnectionSelect.value = '';
                }
                if (workflowPushCampaignNameInput) {
                    workflowPushCampaignNameInput.value = 'winback_push';
                }
                if (workflowPushTitleInput) {
                    workflowPushTitleInput.value = 'Come back';
                }
                if (workflowPushScheduledAtInput) {
                    workflowPushScheduledAtInput.value = '';
                }
                if (workflowPushBodyInput) {
                    workflowPushBodyInput.value = 'Rewards are waiting for you.';
                }
                if (workflowPushDeepLinkInput) {
                    workflowPushDeepLinkInput.value = '';
                }
                if (workflowPushDeepLinkTokenInput) {
                    workflowPushDeepLinkTokenInput.value = '';
                }
                if (workflowPushDataInput) {
                    workflowPushDataInput.value = '{}';
                }
                if (workflowPushProviderOptionsInput) {
                    workflowPushProviderOptionsInput.value = '{}';
                }
                syncNoCodeSetupArtifacts([
                    'workflow-push-data-input',
                    'workflow-push-provider-options-input',
                ]);
                document.getElementById('workflow-requires-confirmation-checkbox').checked = false;
                syncWorkflowChannelFields();
                syncWorkflowBuilderState(null);
                setInlineStatus(workflowCreateStatus, 'Creating a new push workflow.');
            }

            function buildPushComposerChannelConfig(name, providerConnectionId) {
                const body = String(pushDispatchBodyInput?.value || '').trim();
                if (!body) {
                    throw new Error('Body is required.');
                }
                return {
                    channel: 'push_notification',
                    campaign_name: String(pushDispatchCampaignNameInput?.value || '').trim() || name,
                    title: String(pushDispatchTitleInput?.value || '').trim(),
                    body,
                    content: body,
                    deep_link: String(pushDispatchDeepLinkInput?.value || '').trim(),
                    deep_link_token: String(pushDispatchDeepLinkTokenInput?.value || '').trim(),
                    data: parseJsonText(pushDispatchDataInput?.value, {}),
                    provider_connection_id: providerConnectionId,
                    provider_options: buildPushComposerProviderOptions(),
                };
            }

            function buildPushComposerTrigger({ manualTest = false } = {}) {
                const mode = getPushComposerMode();
                if (manualTest) {
                    return { type: 'manual_test', hour: 0, minute: 0 };
                }
                if (mode === 'repeated') {
                    return {
                        type: 'daily_schedule',
                        hour: Number(pushDispatchRepeatHourInput?.value || 0),
                        minute: Number(pushDispatchRepeatMinuteInput?.value || 0),
                    };
                }
                const scheduledAt = toIsoFromLocalDateTimeInput(pushDispatchScheduleOnceInput?.value || '');
                if (!scheduledAt) {
                    throw new Error('Choose a schedule time before creating a one-time push workflow.');
                }
                return {
                    type: 'one_time_schedule',
                    scheduled_at: scheduledAt,
                };
            }

            function setOptionalInputValue(input, value) {
                if (!input) {
                    return;
                }
                input.value = value === null || value === undefined || value === '' ? '' : String(value);
            }

            function buildPushDispatchPayload() {
                const audience = getPushComposerAudienceSelection();
                const body = String(pushDispatchBodyInput?.value || '').trim();
                if (!body) {
                    throw new Error('Body is required.');
                }
                const providerConnectionId = String(pushDispatchProviderConnectionSelect?.value || '').trim();
                validatePushComposerAudience({ ...audience, providerConnectionId });
                if (audience.audienceType === 'cohort') {
                    throw new Error('Immediate cohort sends run through workflow execution, not direct dispatch.');
                }
                const payload = {
                    body,
                    user_ids: audience.userIds,
                    data: parseJsonText(pushDispatchDataInput?.value, {}),
                    provider_options: buildPushComposerProviderOptions(),
                };
                if (audience.userIds.length === 1) {
                    payload.user_id = audience.userIds[0];
                }
                const name = String(pushDispatchNameInput?.value || '').trim();
                const campaignName = String(pushDispatchCampaignNameInput?.value || '').trim();
                const title = String(pushDispatchTitleInput?.value || '').trim();
                const deepLink = String(pushDispatchDeepLinkInput?.value || '').trim();
                const deepLinkToken = String(pushDispatchDeepLinkTokenInput?.value || '').trim();
                if (name) {
                    payload.name = name;
                }
                if (providerConnectionId) {
                    payload.provider_connection_id = providerConnectionId;
                }
                if (campaignName) {
                    payload.campaign_name = campaignName;
                }
                if (title) {
                    payload.title = title;
                }
                if (deepLink) {
                    payload.deep_link = deepLink;
                }
                if (deepLinkToken) {
                    payload.deep_link_token = deepLinkToken;
                }
                return payload;
            }

            function buildPushComposerWorkflowPayload({ manualTest = false } = {}) {
                const name = String(pushDispatchNameInput?.value || '').trim() || `push_campaign_${Date.now()}`;
                const audience = getPushComposerAudienceSelection();
                const providerConnectionId = String(pushDispatchProviderConnectionSelect?.value || '').trim() || null;
                validatePushComposerAudience({ ...audience, providerConnectionId });
                const channelConfig = buildPushComposerChannelConfig(name, providerConnectionId);
                return {
                    name,
                    audience_mode: audience.audienceMode,
                    cohort_id: audience.cohortId,
                    user_ids: audience.userIds,
                    trigger: buildPushComposerTrigger({ manualTest }),
                    action: channelConfig,
                    channel_config: channelConfig,
                    policy: buildPushComposerPolicyPayload(),
                    budget_policy: buildPushComposerBudgetPolicyPayload(),
                    requires_confirmation: false,
                };
            }

            function loadWorkflowIntoPushComposer(workflow) {
                if (!workflow) {
                    resetPushDispatchForm();
                    return;
                }
                const trigger = workflow.trigger || {};
                const channelConfig = workflow.channel_config || {};
                const definition = workflow.definition || {};
                if (pushDispatchNameInput) {
                    pushDispatchNameInput.value = workflow.name || '';
                }
                populatePushDispatchProviderSelect({ preferredValue: channelConfig.provider_connection_id || '' });
                if (pushDispatchProviderConnectionSelect) {
                    pushDispatchProviderConnectionSelect.value = channelConfig.provider_connection_id || '';
                }
                const triggerType = String(trigger.type || '').trim().toLowerCase();
                if (pushDispatchModeSelect) {
                    pushDispatchModeSelect.value = triggerType === 'daily_schedule' ? 'repeated' : 'single';
                }
                if (pushDispatchSingleTimingSelect) {
                    pushDispatchSingleTimingSelect.value = triggerType === 'one_time_schedule' ? 'schedule_once' : 'immediate';
                }
                if (pushDispatchAudienceTypeSelect) {
                    if (String(definition.audience_mode || workflow.audience_mode || '').trim().toLowerCase() === 'cohort' || definition.cohort_id) {
                        pushDispatchAudienceTypeSelect.value = 'cohort';
                    } else if (Array.isArray(definition.user_ids) && definition.user_ids.length > 0) {
                        pushDispatchAudienceTypeSelect.value = 'user_ids';
                    } else {
                        pushDispatchAudienceTypeSelect.value = 'all_players';
                    }
                }
                if (pushDispatchScheduleOnceInput) {
                    pushDispatchScheduleOnceInput.value = fromIsoToLocalDateTimeInput(trigger.scheduled_at || '');
                }
                if (pushDispatchRepeatHourInput) {
                    pushDispatchRepeatHourInput.value = trigger.hour ?? 10;
                }
                if (pushDispatchRepeatMinuteInput) {
                    pushDispatchRepeatMinuteInput.value = trigger.minute ?? 0;
                }
                if (pushDispatchUserIdInput) {
                    pushDispatchUserIdInput.value = Array.isArray(definition.user_ids) ? definition.user_ids.join(', ') : '';
                }
                if (pushDispatchCohortSelect) {
                    pushDispatchCohortSelect.value = definition.cohort_id || '';
                }
                if (pushDispatchCampaignNameInput) {
                    pushDispatchCampaignNameInput.value = channelConfig.campaign_name || '';
                }
                if (pushDispatchTitleInput) {
                    pushDispatchTitleInput.value = channelConfig.title || '';
                }
                if (pushDispatchBodyInput) {
                    pushDispatchBodyInput.value = channelConfig.body || channelConfig.content || '';
                }
                if (pushDispatchDeepLinkInput) {
                    pushDispatchDeepLinkInput.value = channelConfig.deep_link || '';
                }
                if (pushDispatchDeepLinkTokenInput) {
                    pushDispatchDeepLinkTokenInput.value = channelConfig.deep_link_token || '';
                }
                setOptionalInputValue(pushDispatchGlobalLimitInput, workflow.policy?.global_daily_limit);
                setOptionalInputValue(pushDispatchChannelLimitInput, workflow.policy?.channel_daily_limit);
                setOptionalInputValue(pushDispatchCooldownHoursInput, workflow.policy?.cooldown_hours);
                setOptionalInputValue(pushDispatchQuietStartInput, workflow.policy?.quiet_hours?.start);
                setOptionalInputValue(pushDispatchQuietEndInput, workflow.policy?.quiet_hours?.end);
                setOptionalInputValue(
                    pushDispatchBudgetLimitInput,
                    workflow.budget_policy?.daily_budget_limit ?? workflow.budget_policy?.daily_delivery_limit,
                );
                if (pushDispatchBlacklistInput) {
                    pushDispatchBlacklistInput.value = Array.isArray(workflow.policy?.blacklist_ids) ? workflow.policy.blacklist_ids.join(', ') : '';
                }
                if (pushDispatchDataInput) {
                    pushDispatchDataInput.value = JSON.stringify(channelConfig.data || {}, null, 2);
                }
                if (pushDispatchProviderOptionsInput) {
                    const providerOptions = { ...(channelConfig.provider_options || {}) };
                    delete providerOptions.filters;
                    pushDispatchProviderOptionsInput.value = JSON.stringify(providerOptions, null, 2);
                }
                if (pushDispatchWynnFiltersInput) {
                    pushDispatchWynnFiltersInput.value = JSON.stringify((channelConfig.provider_options || {}).filters || {}, null, 2);
                }
                syncNoCodeSetupArtifacts([
                    'push-dispatch-data-input',
                    'push-dispatch-provider-options-input',
                    'push-dispatch-wynn-filters-input',
                ]);
                syncPushDispatchComposerFields();
                renderJsonOutput(pushDispatchOutput, workflow, 'No push workflow selected.');
                setInlineStatus(pushDispatchStatus, `${workflow.name || workflow.workflow_id} loaded into Push Composer.`);
            }

            function loadWorkflowIntoBuilder(workflow) {
                if (!workflow) {
                    resetWorkflowBuilderForm();
                    return;
                }
                const trigger = workflow.trigger || {};
                const policy = workflow.policy || {};
                const budgetPolicy = workflow.budget_policy || {};
                const channelConfig = workflow.channel_config || {};
                document.getElementById('workflow-name-input').value = workflow.name || '';
                document.getElementById('workflow-cohort-select').value = workflow.definition?.cohort_id || '';
                document.getElementById('workflow-experiment-id-input').value = workflow.experiment_id || '';
                document.getElementById('workflow-trigger-type-select').value = trigger.type || 'daily_schedule';
                document.getElementById('workflow-trigger-hour-input').value = trigger.hour ?? 10;
                document.getElementById('workflow-trigger-minute-input').value = trigger.minute ?? 0;
                if (workflowChannelSelect) {
                    workflowChannelSelect.value = String(channelConfig.channel || 'push_notification').trim().toLowerCase() || 'push_notification';
                }
                document.getElementById('workflow-global-limit-input').value = policy.global_daily_limit ?? 5;
                document.getElementById('workflow-channel-limit-input').value = policy.channel_daily_limit ?? 5;
                document.getElementById('workflow-cooldown-hours-input').value = policy.cooldown_hours ?? 24;
                document.getElementById('workflow-quiet-start-input').value = (policy.quiet_hours || {}).start ?? 22;
                document.getElementById('workflow-quiet-end-input').value = (policy.quiet_hours || {}).end ?? 7;
                document.getElementById('workflow-budget-limit-input').value = budgetPolicy.daily_budget_limit ?? 25;
                document.getElementById('workflow-blacklist-input').value = Array.isArray(policy.blacklist_ids) ? policy.blacklist_ids.join(',') : '';
                if (workflowContentInput) {
                    workflowContentInput.value = channelConfig.content || 'Come back for a reward.';
                }
                populateWorkflowPushProviderSelect({ preferredValue: channelConfig.provider_connection_id || '' });
                if (workflowPushProviderConnectionSelect) {
                    workflowPushProviderConnectionSelect.value = channelConfig.provider_connection_id || '';
                }
                if (workflowPushCampaignNameInput) {
                    workflowPushCampaignNameInput.value = channelConfig.campaign_name || '';
                }
                if (workflowPushTitleInput) {
                    workflowPushTitleInput.value = channelConfig.title || '';
                }
                if (workflowPushScheduledAtInput) {
                    workflowPushScheduledAtInput.value = fromIsoToLocalDateTimeInput(channelConfig.scheduled_at);
                }
                if (workflowPushBodyInput) {
                    workflowPushBodyInput.value = channelConfig.body || channelConfig.content || '';
                }
                if (workflowPushDeepLinkInput) {
                    workflowPushDeepLinkInput.value = channelConfig.deep_link || '';
                }
                if (workflowPushDeepLinkTokenInput) {
                    workflowPushDeepLinkTokenInput.value = channelConfig.deep_link_token || '';
                }
                if (workflowPushDataInput) {
                    workflowPushDataInput.value = JSON.stringify(channelConfig.data || {}, null, 2);
                }
                if (workflowPushProviderOptionsInput) {
                    workflowPushProviderOptionsInput.value = JSON.stringify(channelConfig.provider_options || {}, null, 2);
                }
                syncNoCodeSetupArtifacts([
                    'workflow-push-data-input',
                    'workflow-push-provider-options-input',
                ]);
                document.getElementById('workflow-requires-confirmation-checkbox').checked = Boolean(workflow.definition?.requires_confirmation);
                syncWorkflowChannelFields();
                syncWorkflowBuilderState(workflow);
                setInlineStatus(
                    workflowCreateStatus,
                    String(workflow.status || '').toLowerCase() === 'published'
                        ? 'Editing this workflow will create a new draft version.'
                        : `Editing ${workflow.name || workflow.workflow_id}.`,
                );
            }

            function findCohort(cohortId) {
                return (cachedCohorts || []).find((item) => item.cohort_id === cohortId) || null;
            }

            function getPredictionAudienceLabel(job) {
                const details = (job && job.progress && job.progress.details) || {};
                return String(
                    details.audience_label
                    || details.resolved_import_display_name
                    || (job && job.spec && job.spec.source_name)
                    || (job && job.id)
                    || ''
                ).trim();
            }

            function formatPredictionAudienceOption(job) {
                const label = getPredictionAudienceLabel(job) || String(job?.id || 'Prediction');
                const status = String(job?.status || 'unknown').trim();
                return status ? `${label} (${status})` : label;
            }

            function getCurrentEmailCampaignAudienceType() {
                return String(emailCampaignAudienceTypeSelect?.value || 'prediction').trim().toLowerCase() || 'prediction';
            }

            function getSelectedEmailCampaignAudienceSelection() {
                const audienceType = getCurrentEmailCampaignAudienceType();
                if (audienceType === 'cohort') {
                    return {
                        audienceType,
                        audienceId: String(emailCampaignCohortSelect?.value || '').trim(),
                    };
                }
                return {
                    audienceType: 'prediction',
                    audienceId: String(emailCampaignPredictionJobSelect?.value || '').trim(),
                };
            }

            function formatEmailCampaignAudienceLabel(audience = {}) {
                const cohortId = String((audience || {}).cohort_id || '').trim();
                if (cohortId) {
                    const cohort = findCohort(cohortId);
                    const cohortName = String(cohort?.name || '').trim();
                    const sourceLabel = getCohortSourceLabel(cohort || {});
                    if (cohortName) {
                        return sourceLabel ? `${cohortName} (${cohortId}) · ${sourceLabel}` : `${cohortName} (${cohortId})`;
                    }
                    return cohortId;
                }
                const predictionJobId = String((audience || {}).prediction_job_id || '').trim();
                if (!predictionJobId) {
                    return '-';
                }
                const job = (cachedPredictionJobs || []).find((item) => item.id === predictionJobId) || null;
                const label = getPredictionAudienceLabel(job);
                return label ? `${label} (${predictionJobId})` : predictionJobId;
            }

            function populateEmailCampaignCohortSelect(cohorts = cachedCohorts) {
                const items = Array.isArray(cohorts) ? cohorts : [];
                const previousValue = emailCampaignCohortSelect?.value || '';
                emailCampaignCohortSelect.innerHTML = '<option value="">Select a cohort audience</option>';
                items.forEach((cohort) => {
                    const option = document.createElement('option');
                    option.value = cohort.cohort_id;
                    option.textContent = formatCohortSelectLabel(cohort);
                    emailCampaignCohortSelect.appendChild(option);
                });
                if (previousValue && items.some((item) => item.cohort_id === previousValue)) {
                    emailCampaignCohortSelect.value = previousValue;
                }
            }

            function populateExportJobSelect(exportJobs = []) {
                const select = document.getElementById('export-diagnostics-select');
                const previousValue = select.value;
                select.innerHTML = '<option value="">Select export job</option>';
                exportJobs.forEach((job) => {
                    const option = document.createElement('option');
                    option.value = job.id;
                    option.textContent = `${job.id} (${job.status || 'unknown'})`;
                    select.appendChild(option);
                });
                if (exportJobs.some((item) => item.id === previousValue)) {
                    select.value = previousValue;
                }
            }

            function getDefaultEmailCampaignMergeFieldsText() {
                return JSON.stringify({
                    first_name: { source: 'field', value: 'first_name' },
                    reward_name: { source: 'literal', value: 'Welcome Back Pack' },
                }, null, 2);
            }

            function formatEmailCampaignStatusLabel(status) {
                return String(status || 'draft')
                    .replace(/[_-]+/g, ' ')
                    .replace(/\b\w/g, (character) => character.toUpperCase());
            }

            function toIsoFromLocalDateTimeInput(value) {
                const raw = String(value || '').trim();
                if (!raw) return null;
                const parsed = new Date(raw);
                if (Number.isNaN(parsed.getTime())) {
                    throw new Error('Schedule time must be a valid date and time.');
                }
                return parsed.toISOString();
            }

            function fromIsoToLocalDateTimeInput(value) {
                const raw = String(value || '').trim();
                if (!raw) return '';
                const parsed = new Date(raw);
                if (Number.isNaN(parsed.getTime())) {
                    return '';
                }
                const pad = (part) => String(part).padStart(2, '0');
                return `${parsed.getFullYear()}-${pad(parsed.getMonth() + 1)}-${pad(parsed.getDate())}T${pad(parsed.getHours())}:${pad(parsed.getMinutes())}`;
            }

            function getCampaignProviderConfig(providerType = 'sendgrid') {
                const normalizedProvider = String(providerType || 'sendgrid').trim().toLowerCase();
                if (pushProviderTypes.has(normalizedProvider)) {
                    return {
                        provider: 'wynn_push_notifier',
                        label: 'Push Provider',
                        credentialLabel: 'API token',
                        assetLabel: 'Push Delivery API',
                        assetOptionLabel: 'Select a push provider connection',
                        selectProviderMessage: 'Select a push provider connection first.',
                        emptyAssetMessage: 'Push provider connections do not browse messaging assets.',
                        loadingAssetsMessage: 'Loading push provider connection...',
                        loadedAssetNoun: 'connection',
                        namePlaceholder: 'e.g. Push Provider Production',
                    };
                }
                if (normalizedProvider === 'braze') {
                    return {
                        provider: 'braze',
                        label: 'Braze',
                        credentialLabel: 'API key',
                        assetLabel: 'Braze API Campaign',
                        assetOptionLabel: 'Select a Braze API campaign',
                        selectProviderMessage: 'Select a Braze provider connection first.',
                        emptyAssetMessage: 'No API-triggered Braze campaigns found for this provider connection.',
                        loadingAssetsMessage: 'Loading Braze API campaigns...',
                        loadedAssetNoun: 'campaign',
                        namePlaceholder: 'e.g. Lifecycle Braze',
                    };
                }
                return {
                    provider: 'sendgrid',
                    label: 'SendGrid',
                    credentialLabel: 'API key',
                    assetLabel: 'Dynamic Template',
                    assetOptionLabel: 'Select a dynamic template',
                    selectProviderMessage: 'Select a SendGrid provider connection first.',
                    emptyAssetMessage: 'No dynamic templates found for this provider connection.',
                    loadingAssetsMessage: 'Loading SendGrid templates...',
                    loadedAssetNoun: 'template',
                    namePlaceholder: 'e.g. Lifecycle SendGrid',
                };
            }

            function isPushProviderType(providerType = '') {
                return pushProviderTypes.has(String(providerType || '').trim().toLowerCase());
            }

            function getProviderConnections(providerType = '') {
                const normalizedProvider = String(providerType || '').trim().toLowerCase();
                const items = Array.isArray(cachedProviderConnections) ? cachedProviderConnections : [];
                return items.filter((item) => {
                    const provider = String(item.provider || '').trim().toLowerCase();
                    return !normalizedProvider || provider === normalizedProvider;
                });
            }

            function getCampaignCapableProviderConnections(providerType = '') {
                const normalizedProvider = String(providerType || '').trim().toLowerCase();
                return getProviderConnections().filter((item) => {
                    const provider = String(item.provider || '').trim().toLowerCase();
                    if (!['sendgrid', 'braze'].includes(provider)) {
                        return false;
                    }
                    return !normalizedProvider || provider === normalizedProvider;
                });
            }

            function getPushWorkflowProviderConnections(providerType = '') {
                const normalizedProvider = String(providerType || '').trim().toLowerCase();
                return getProviderConnections().filter((item) => {
                    const provider = String(item.provider || '').trim().toLowerCase();
                    if (!isPushProviderType(provider)) {
                        return false;
                    }
                    return !normalizedProvider || provider === normalizedProvider;
                });
            }

            function findProviderConnection(providerConnectionId) {
                return (cachedProviderConnections || []).find((item) => item.provider_connection_id === providerConnectionId) || null;
            }

            function findEmailCampaign(emailCampaignId) {
                return (cachedEmailCampaigns || []).find((item) => item.email_campaign_id === emailCampaignId) || null;
            }

            function findWorkflow(workflowId) {
                return (cachedWorkflows || []).find((item) => item.workflow_id === workflowId) || null;
            }

            function findPushDispatch(pushDispatchId) {
                return (cachedPushDispatches || []).find((item) => item.push_dispatch_id === pushDispatchId) || null;
            }

            async function refreshProviderConnectionsState() {
                if (shouldBlockProtectedAppData()) {
                    return getProviderConnections();
                }
                const payload = await apiRequest('/provider-connections');
                const items = Array.isArray(payload.items) ? payload.items : [];
                cachedProviderConnections = latestByCreatedAt(items);
                renderConnectorEntrySummary();
                return getProviderConnections();
            }

            async function refreshEmailCampaignsState() {
                if (shouldBlockProtectedAppData()) {
                    return cachedEmailCampaigns;
                }
                const payload = await apiRequest('/email-campaigns');
                cachedEmailCampaigns = latestByCreatedAt(Array.isArray(payload.items) ? payload.items : []);
                return cachedEmailCampaigns;
            }

            async function refreshWorkflowsState() {
                if (shouldBlockProtectedAppData()) {
                    return cachedWorkflows;
                }
                const payload = await apiRequest('/workflows');
                cachedWorkflows = latestByCreatedAt(Array.isArray(payload.items) ? payload.items : []);
                return cachedWorkflows;
            }

            async function refreshPushDispatchesState() {
                if (shouldBlockProtectedAppData()) {
                    return cachedPushDispatches;
                }
                const payload = await apiRequest('/push-dispatches');
                cachedPushDispatches = latestByCreatedAt(Array.isArray(payload.items) ? payload.items : []);
                return cachedPushDispatches;
            }

            function ensureSelectOption(select, value, label) {
                if (!select || !value) return;
                if (Array.from(select.options).some((option) => option.value === value)) {
                    return;
                }
                const option = document.createElement('option');
                option.value = value;
                option.textContent = label;
                select.appendChild(option);
            }

            function updateEmailCampaignSummary() {
                const providers = getCampaignCapableProviderConnections();
                const campaigns = Array.isArray(cachedEmailCampaigns) ? cachedEmailCampaigns : [];
                const draftCount = campaigns.filter((item) => String(item.status || '').toLowerCase() === 'draft').length;
                const scheduledCount = campaigns.filter((item) => String(item.status || '').toLowerCase() === 'scheduled').length;
                const pastCount = campaigns.filter((item) => ['sent', 'sent_with_errors', 'failed', 'cancelled'].includes(String(item.status || '').toLowerCase())).length;
                const sendGridCount = getCampaignCapableProviderConnections('sendgrid').length;
                const brazeCount = getCampaignCapableProviderConnections('braze').length;
                const providerBreakdown = [
                    sendGridCount ? `${sendGridCount} SendGrid` : '',
                    brazeCount ? `${brazeCount} Braze` : '',
                ].filter(Boolean).join(' · ');
                emailCampaignsSummary.textContent = providers.length === 0
                    ? 'Save a SendGrid or Braze provider connection under Connectors to start browsing assets and building campaigns.'
                    : `${providers.length} provider connection${providers.length === 1 ? '' : 's'}${providerBreakdown ? ` (${providerBreakdown})` : ''} · ${draftCount} draft${draftCount === 1 ? '' : 's'} · ${scheduledCount} scheduled · ${pastCount} past`;
            }

            function getCurrentProviderConnectionType() {
                return String(providerConnectionTypeSelect?.value || 'sendgrid').trim().toLowerCase() || 'sendgrid';
            }

            function getCurrentEmailCampaignProviderType() {
                return String(
                    emailCampaignProviderTypeSelect?.value
                    || (findProviderConnection(String(emailCampaignProviderSelect?.value || '').trim()) || {}).provider
                    || 'sendgrid'
                ).trim().toLowerCase() || 'sendgrid';
            }

            function getSelectedEmailCampaignProviderConnection() {
                return findProviderConnection(String(emailCampaignProviderSelect?.value || '').trim());
            }

            function sortMessagingAssets(items = []) {
                return [...items].sort((left, right) => {
                    const leftUpdatedAt = parseIsoDate(left.updated_at || left.last_edited || left.created_at).getTime();
                    const rightUpdatedAt = parseIsoDate(right.updated_at || right.last_edited || right.created_at).getTime();
                    if (leftUpdatedAt !== rightUpdatedAt) {
                        return rightUpdatedAt - leftUpdatedAt;
                    }
                    return String(left.name || left.id || '').localeCompare(String(right.name || right.id || ''));
                });
            }

            function getProviderConnectionApiKeyInput(providerType = getCurrentProviderConnectionType()) {
                const normalizedProvider = String(providerType || '').trim().toLowerCase();
                if (normalizedProvider === 'braze') {
                    return document.getElementById('provider-connection-braze-api-key-input');
                }
                if (isPushProviderType(normalizedProvider)) {
                    return document.getElementById('provider-connection-wynn-api-token-input');
                }
                return document.getElementById('provider-connection-sendgrid-api-key-input');
            }

            function isProviderConnectionFormVisible() {
                return providerConnectionFormContainer?.style.display !== 'none';
            }

            function setProviderConnectionFormVisible(isVisible, { providerType = '', preserveValues = false } = {}) {
                if (addProviderConnectionBtn) {
                    addProviderConnectionBtn.style.display = isVisible ? 'none' : 'inline-block';
                }
                if (providerConnectionFormContainer) {
                    providerConnectionFormContainer.style.display = isVisible ? 'block' : 'none';
                }
                if (!isVisible) {
                    selectedProviderConnectionId = null;
                    providerConnectionTypeSelect.value = 'sendgrid';
                    providerConnectionNameInput.value = '';
                    syncProviderConnectionFormFields();
                    setInlineStatus(providerConnectionStatus, '');
                    return;
                }
                if (providerType) {
                    providerConnectionTypeSelect.value = String(providerType || 'sendgrid').trim().toLowerCase() || 'sendgrid';
                }
                syncProviderConnectionFormFields();
                if (!preserveValues) {
                    selectedProviderConnectionId = null;
                    providerConnectionNameInput.value = '';
                    providerConnectionNameInput.focus();
                }
            }

            function syncProviderConnectionFormFields() {
                if (!providerConnectionConfigFields) {
                    return;
                }
                const providerType = getCurrentProviderConnectionType();
                if (providerType === 'braze') {
                    providerConnectionConfigFields.innerHTML = `
                        <div class="grid-2">
                            <div class="form-group">
                                <label for="provider-connection-braze-api-key-input">Braze API Key</label>
                                <input type="password" id="provider-connection-braze-api-key-input" placeholder="Enter your Braze REST API key">
                            </div>
                            <div class="form-group">
                                <label for="provider-connection-braze-rest-endpoint-input">Braze REST Endpoint</label>
                                <input type="text" id="provider-connection-braze-rest-endpoint-input" placeholder="https://rest.iad-01.braze.com">
                            </div>
                        </div>
                    `;
                } else if (isPushProviderType(providerType)) {
                    providerConnectionConfigFields.innerHTML = `
                        <div class="grid-2">
                            <div class="form-group">
                                <label for="provider-connection-wynn-api-token-input">Push API Token</label>
                                <input type="password" id="provider-connection-wynn-api-token-input" placeholder="Enter the push provider bearer token">
                            </div>
                            <div class="form-group">
                                <label for="provider-connection-wynn-base-url-input">Push Provider Base URL</label>
                                <input type="text" id="provider-connection-wynn-base-url-input" placeholder="https://push.example.com">
                            </div>
                        </div>
                        <div class="grid-2">
                            <div class="form-group">
                                <label for="provider-connection-wynn-default-deep-link-token-input">Default Deep Link Token (optional)</label>
                                <input type="text" id="provider-connection-wynn-default-deep-link-token-input" placeholder="campaign-default-token">
                            </div>
                            <div class="form-group">
                                <label for="provider-connection-wynn-callback-signing-secret-input">Callback Signing Secret (optional)</label>
                                <input type="password" id="provider-connection-wynn-callback-signing-secret-input" placeholder="Optional future callback secret">
                            </div>
                        </div>
                        <div class="grid-2">
                            <div class="form-group">
                                <label for="provider-connection-wynn-callback-url-input">Kairyx Callback URL (optional)</label>
                                <input type="text" id="provider-connection-wynn-callback-url-input" placeholder="https://operator.example.com/api/v1/activation/callbacks/wynn_push_notifier">
                            </div>
                            <div class="form-group">
                                <label for="provider-connection-wynn-callback-bearer-token-input">Kairyx Callback Bearer Token (optional)</label>
                                <input type="password" id="provider-connection-wynn-callback-bearer-token-input" placeholder="Required when callback URL is set">
                            </div>
                        </div>
                    `;
                } else {
                    providerConnectionConfigFields.innerHTML = `
                        <div class="grid-2">
                            <div class="form-group">
                                <label for="provider-connection-sendgrid-api-key-input">SendGrid API Key</label>
                                <input type="password" id="provider-connection-sendgrid-api-key-input" placeholder="SG....">
                            </div>
                            <div class="form-group">
                                <label for="provider-connection-sendgrid-from-email-input">Default From Email</label>
                                <input type="email" id="provider-connection-sendgrid-from-email-input" placeholder="rewards@example.com">
                            </div>
                        </div>
                        <div class="grid-2">
                            <div class="form-group">
                                <label for="provider-connection-sendgrid-from-name-input">Default From Name (optional)</label>
                                <input type="text" id="provider-connection-sendgrid-from-name-input" placeholder="Rewards Team">
                            </div>
                            <div class="form-group">
                                <label for="provider-connection-sendgrid-base-url-input">Base URL (optional)</label>
                                <input type="text" id="provider-connection-sendgrid-base-url-input" placeholder="https://api.sendgrid.com">
                            </div>
                        </div>
                    `;
                }
                syncProviderConnectionFormState();
            }

            function syncProviderConnectionFormState() {
                const providerType = getCurrentProviderConnectionType();
                const descriptor = getCampaignProviderConfig(providerType);
                const editingConnection = selectedProviderConnectionId ? findProviderConnection(selectedProviderConnectionId) : null;
                const editing = Boolean(editingConnection && String(editingConnection.provider || '').toLowerCase() === providerType);
                providerConnectionSaveBtn.textContent = editing ? 'Update Provider Connection' : 'Save Provider Connection';
                if (providerConnectionNameInput) {
                    providerConnectionNameInput.placeholder = descriptor.namePlaceholder;
                }
                const apiKeyInput = getProviderConnectionApiKeyInput(providerType);
                if (!apiKeyInput) {
                    return;
                }
                if (editing && !String(apiKeyInput.value || '').trim()) {
                    apiKeyInput.placeholder = 'Stored securely. Enter a new key to rotate it.';
                    return;
                }
                if (providerType === 'braze') {
                    apiKeyInput.placeholder = 'Enter your Braze REST API key';
                    return;
                }
                if (isPushProviderType(providerType)) {
                    apiKeyInput.placeholder = 'Enter the push provider bearer token';
                    return;
                }
                apiKeyInput.placeholder = 'SG....';
            }

            function loadProviderConnectionIntoForm(providerConnectionId) {
                const provider = findProviderConnection(providerConnectionId);
                if (!provider) {
                    setProviderConnectionFormVisible(false);
                    return;
                }
                setProviderConnectionFormVisible(true, {
                    providerType: provider.provider,
                    preserveValues: true,
                });
                selectedProviderConnectionId = provider.provider_connection_id;
                providerConnectionTypeSelect.value = String(provider.provider || 'sendgrid').toLowerCase() || 'sendgrid';
                providerConnectionNameInput.value = provider.name || '';
                syncProviderConnectionFormFields();
                if (provider.provider === 'braze') {
                    const restEndpointInput = document.getElementById('provider-connection-braze-rest-endpoint-input');
                    if (restEndpointInput) {
                        restEndpointInput.value = (provider.config || {}).rest_endpoint || '';
                    }
                } else if (isPushProviderType(provider.provider)) {
                    const baseUrlInput = document.getElementById('provider-connection-wynn-base-url-input');
                    const defaultDeepLinkTokenInput = document.getElementById('provider-connection-wynn-default-deep-link-token-input');
                    const callbackSigningSecretInput = document.getElementById('provider-connection-wynn-callback-signing-secret-input');
                    const callbackUrlInput = document.getElementById('provider-connection-wynn-callback-url-input');
                    const callbackBearerTokenInput = document.getElementById('provider-connection-wynn-callback-bearer-token-input');
                    if (baseUrlInput) {
                        baseUrlInput.value = (provider.config || {}).base_url || '';
                    }
                    if (defaultDeepLinkTokenInput) {
                        defaultDeepLinkTokenInput.value = (provider.config || {}).default_deep_link_token || '';
                    }
                    if (callbackSigningSecretInput) {
                        callbackSigningSecretInput.value = '';
                    }
                    if (callbackUrlInput) {
                        callbackUrlInput.value = (provider.config || {}).callback_url || '';
                    }
                    if (callbackBearerTokenInput) {
                        callbackBearerTokenInput.value = '';
                    }
                } else {
                    const fromEmailInput = document.getElementById('provider-connection-sendgrid-from-email-input');
                    const fromNameInput = document.getElementById('provider-connection-sendgrid-from-name-input');
                    const baseUrlInput = document.getElementById('provider-connection-sendgrid-base-url-input');
                    if (fromEmailInput) {
                        fromEmailInput.value = (provider.config || {}).from_email || '';
                    }
                    if (fromNameInput) {
                        fromNameInput.value = (provider.config || {}).from_name || '';
                    }
                    if (baseUrlInput) {
                        baseUrlInput.value = (provider.config || {}).base_url || '';
                    }
                }
                const apiKeyInput = getProviderConnectionApiKeyInput(provider.provider);
                if (apiKeyInput) {
                    apiKeyInput.value = '';
                }
                syncProviderConnectionFormState();
                setInlineStatus(
                    providerConnectionStatus,
                    ((provider.config || {}).api_key_configured || (provider.config || {}).api_token_configured)
                        ? `Editing ${provider.name}. Leave the ${String(getCampaignProviderConfig(provider.provider).credentialLabel || 'secret').toLowerCase()} blank to keep the stored secret.`
                        : `Editing ${provider.name}.`,
                );
            }

            function resetProviderConnectionForm({ keepType = false } = {}) {
                const preservedType = keepType ? getCurrentProviderConnectionType() : 'sendgrid';
                selectedProviderConnectionId = null;
                providerConnectionTypeSelect.value = preservedType;
                providerConnectionNameInput.value = '';
                syncProviderConnectionFormFields();
                setInlineStatus(providerConnectionStatus, '');
            }

            async function deleteProviderConnection(providerConnectionId) {
                const provider = findProviderConnection(providerConnectionId);
                if (!provider) {
                    throw new Error(`Provider connection '${providerConnectionId}' not found.`);
                }
                const providerLabel = formatConnectorLabel(provider.provider || 'sendgrid');
                if (!confirm(`Delete ${provider.name} (${providerLabel})? This removes the saved campaign provider connection.`)) {
                    return null;
                }
                setInlineStatus(providerConnectionStatus, `Deleting ${provider.name}...`);
                await apiRequest(`/provider-connections/${encodeURIComponent(providerConnectionId)}`, { method: 'DELETE' });
                emailCampaignAssetCache.delete(providerConnectionId);
                if (selectedProviderConnectionId === providerConnectionId) {
                    setProviderConnectionFormVisible(false);
                }
                if (String(emailCampaignProviderSelect?.value || '').trim() === providerConnectionId) {
                    emailCampaignProviderSelect.value = '';
                }
                await loadEmailCampaignWorkspace({ preserveSelection: true, forceTemplateRefresh: false });
                setInlineStatus(providerConnectionStatus, `Deleted ${provider.name}.`);
                return provider;
            }

            async function saveProviderConnection() {
                const providerType = getCurrentProviderConnectionType();
                const descriptor = getCampaignProviderConfig(providerType);
                const name = String(providerConnectionNameInput.value || '').trim();
                const apiKey = String(getProviderConnectionApiKeyInput(providerType)?.value || '').trim();
                if (!name) {
                    throw new Error('Connection name is required.');
                }
                let config = {};
                if (providerType === 'braze') {
                    const restEndpoint = String(document.getElementById('provider-connection-braze-rest-endpoint-input')?.value || '').trim();
                    if (!restEndpoint) {
                        throw new Error('Braze REST endpoint is required.');
                    }
                    config = {
                        rest_endpoint: restEndpoint,
                        ...(apiKey ? { api_key: apiKey } : {}),
                    };
                } else if (isPushProviderType(providerType)) {
                    const baseUrl = String(document.getElementById('provider-connection-wynn-base-url-input')?.value || '').trim();
                    const defaultDeepLinkToken = String(document.getElementById('provider-connection-wynn-default-deep-link-token-input')?.value || '').trim();
                    const callbackSigningSecret = String(document.getElementById('provider-connection-wynn-callback-signing-secret-input')?.value || '').trim();
                    const callbackUrl = String(document.getElementById('provider-connection-wynn-callback-url-input')?.value || '').trim();
                    const callbackBearerToken = String(document.getElementById('provider-connection-wynn-callback-bearer-token-input')?.value || '').trim();
                    if (!baseUrl) {
                        throw new Error('Push provider base URL is required.');
                    }
                    config = {
                        base_url: baseUrl,
                        ...(defaultDeepLinkToken ? { default_deep_link_token: defaultDeepLinkToken } : {}),
                        ...(callbackUrl ? { callback_url: callbackUrl } : {}),
                        ...(callbackBearerToken ? { callback_bearer_token: callbackBearerToken } : {}),
                        ...(callbackSigningSecret ? { callback_signing_secret: callbackSigningSecret } : {}),
                        ...(apiKey ? { api_token: apiKey } : {}),
                    };
                } else {
                    const fromEmail = String(document.getElementById('provider-connection-sendgrid-from-email-input')?.value || '').trim();
                    const fromName = String(document.getElementById('provider-connection-sendgrid-from-name-input')?.value || '').trim();
                    const baseUrl = String(document.getElementById('provider-connection-sendgrid-base-url-input')?.value || '').trim();
                    if (!fromEmail) {
                        throw new Error('Default From Email is required.');
                    }
                    config = {
                        from_email: fromEmail,
                        ...(fromName ? { from_name: fromName } : {}),
                        ...(baseUrl ? { base_url: baseUrl } : {}),
                        ...(apiKey ? { api_key: apiKey } : {}),
                    };
                }
                if (!selectedProviderConnectionId && !apiKey) {
                    throw new Error(`${descriptor.label} ${descriptor.credentialLabel || 'secret'} is required for a new provider connection.`);
                }
                setInlineStatus(
                    providerConnectionStatus,
                    selectedProviderConnectionId ? 'Updating provider connection...' : 'Saving provider connection...',
                );
                const response = selectedProviderConnectionId
                    ? await apiRequest(`/provider-connections/${encodeURIComponent(selectedProviderConnectionId)}`, {
                        method: 'PATCH',
                        body: { name, config },
                    })
                    : await apiRequest('/provider-connections', {
                        method: 'POST',
                        body: { name, provider: providerType, config },
                    });
                emailCampaignAssetCache.delete(response.provider_connection_id);
                await loadProviderConnectionWorkspace({ preserveSelection: true });
                loadProviderConnectionIntoForm(response.provider_connection_id);
                if (getCurrentEmailCampaignProviderType() === providerType) {
                    populateEmailCampaignProviderSelect({ preferredValue: response.provider_connection_id });
                    emailCampaignProviderSelect.value = response.provider_connection_id;
                    try {
                        await loadEmailCampaignAssets(response.provider_connection_id, { forceRefresh: true });
                        setInlineStatus(emailCampaignStatus, `${descriptor.label} connection is ready for the campaign builder.`);
                    } catch (error) {
                        setInlineStatus(emailCampaignStatus, error.message || `Failed to load ${descriptor.label} assets.`, true);
                    }
                }
                setInlineStatus(providerConnectionStatus, `Saved ${descriptor.label} provider ${response.name}.`);
                return response;
            }

            function formatProviderConnectionSummary(provider) {
                const normalizedProvider = String(provider?.provider || '').toLowerCase();
                if (normalizedProvider === 'braze') {
                    return {
                        detail: (provider?.config || {}).rest_endpoint || '-',
                        hint: '',
                    };
                }
                if (isPushProviderType(normalizedProvider)) {
                    return {
                        detail: (provider?.config || {}).base_url || '-',
                        hint: '',
                    };
                }
                return {
                    detail: (provider?.config || {}).from_email || '-',
                    hint: '',
                };
            }

            function renderProviderConnectionList(items = getProviderConnections()) {
                renderSimpleTable(
                    providerConnectionList,
                    [
                        { label: 'Connection', render: (item) => `<strong>${escapeHtml(item.name || '-')}</strong><div class="subtle">${escapeHtml(item.provider_connection_id || '-')}</div>` },
                        { label: 'Provider', render: (item) => `<span class="pill">${escapeHtml(formatConnectorLabel(item.provider))}</span>` },
                        {
                            label: 'Configuration',
                            render: (item) => {
                                const summary = formatProviderConnectionSummary(item);
                                return `<span>${escapeHtml(summary.detail)}</span>`;
                            },
                        },
                        { label: 'API Key', render: (item) => `<span class="pill">${Boolean((item.config || {}).api_key_configured || (item.config || {}).api_token_configured) ? 'Stored' : 'Missing'}</span>` },
                        { label: 'Updated', render: (item) => escapeHtml(formatDateTime(item.updated_at)) },
                        {
                            label: 'Actions',
                            render: (item) => `
                                <div class="table-actions">
                                    <button type="button" data-provider-connection-action="edit" data-provider-connection-id="${escapeHtml(item.provider_connection_id)}">Edit</button>
                                    <button type="button" data-provider-connection-action="use" data-provider-connection-id="${escapeHtml(item.provider_connection_id)}">${isPushProviderType(item.provider) ? 'Use in Push' : 'Use in Campaign'}</button>
                                    <button type="button" data-provider-connection-action="delete" data-provider-connection-id="${escapeHtml(item.provider_connection_id)}" style="background-color: var(--subtle-text);">Delete</button>
                                </div>
                            `,
                        },
                    ],
                    items,
                    'No connections yet.',
                );
                providerConnectionList.querySelectorAll('[data-provider-connection-action]').forEach((button) => {
                    button.addEventListener('click', async () => {
                        const providerConnectionId = button.dataset.providerConnectionId;
                        const action = button.dataset.providerConnectionAction;
                        const provider = findProviderConnection(providerConnectionId);
                        if (!providerConnectionId || !action || !provider) {
                            return;
                        }
                        if (action === 'edit') {
                            loadProviderConnectionIntoForm(providerConnectionId);
                            return;
                        }
                        if (action === 'delete') {
                            try {
                                await deleteProviderConnection(providerConnectionId);
                            } catch (error) {
                                setInlineStatus(providerConnectionStatus, error.message || 'Failed to delete provider connection.', true);
                            }
                            return;
                        }
                        if (isPushProviderType(provider.provider)) {
                            activateModule('action-orchestrator', 'action-orchestrator-push', {
                                targetId: 'push-notifications-section',
                                closeSidebar: true,
                                scrollBehavior: 'smooth',
                            });
                            populatePushDispatchProviderSelect({ preferredValue: providerConnectionId });
                            if (pushDispatchProviderConnectionSelect) {
                                pushDispatchProviderConnectionSelect.value = providerConnectionId;
                            }
                            syncPushDispatchComposerFields();
                            if (workflowChannelSelect) {
                                workflowChannelSelect.value = 'push_notification';
                            }
                            populateWorkflowPushProviderSelect({ preferredValue: providerConnectionId });
                            if (workflowPushProviderConnectionSelect) {
                                workflowPushProviderConnectionSelect.value = providerConnectionId;
                            }
                            syncWorkflowChannelFields();
                            setInlineStatus(pushDispatchStatus, `${provider.name} selected for the Push Composer.`);
                            setInlineStatus(workflowCreateStatus, `${provider.name} selected for the legacy workflow builder.`);
                            return;
                        }
                        emailCampaignProviderTypeSelect.value = String(provider.provider || 'sendgrid').toLowerCase() || 'sendgrid';
                        activateModule('action-orchestrator', 'action-orchestrator-email-campaigns', {
                            closeSidebar: true,
                            scrollBehavior: 'smooth',
                            reloadPage: true,
                        });
                        syncEmailCampaignProviderFields({ preferredProviderConnectionId: providerConnectionId });
                        emailCampaignProviderSelect.value = providerConnectionId;
                        try {
                            await loadEmailCampaignAssets(providerConnectionId, { forceRefresh: false });
                            setInlineStatus(emailCampaignStatus, `${provider.name} selected for the campaign builder.`);
                        } catch (error) {
                            setInlineStatus(emailCampaignStatus, error.message || 'Failed to load messaging assets for the selected provider.', true);
                        }
                    });
                });
            }

            async function loadProviderConnectionWorkspace({ preserveSelection = true } = {}) {
                try {
                    const providers = await refreshProviderConnectionsState();
                    if (!preserveSelection) {
                        setProviderConnectionFormVisible(false);
                    } else if (selectedProviderConnectionId && providers.some((item) => item.provider_connection_id === selectedProviderConnectionId)) {
                        loadProviderConnectionIntoForm(selectedProviderConnectionId);
                    } else if (isProviderConnectionFormVisible()) {
                        syncProviderConnectionFormState();
                    } else {
                        syncProviderConnectionFormFields();
                        syncProviderConnectionFormState();
                    }
                    renderProviderConnectionList(providers);
                    populatePushDispatchProviderSelect();
                    populateWorkflowPushProviderSelect();
                    populateEmailCampaignProviderSelect();
                    updateEmailCampaignSummary();
                } catch (error) {
                    if (isWorkspaceContextError(error)) {
                        cachedProviderConnections = [];
                        setProviderConnectionFormVisible(false);
                        renderProviderConnectionList([]);
                        populatePushDispatchProviderSelect();
                        populateWorkflowPushProviderSelect();
                        setInlineStatus(providerConnectionStatus, getWorkspaceResolutionMessage(error.payload || authSessionState), true);
                        updateEmailCampaignSummary();
                        return;
                    }
                    setInlineStatus(providerConnectionStatus, error.message || 'Failed to load provider connections.', true);
                }
            }

            function populateEmailCampaignProviderSelect({ preferredValue = '' } = {}) {
                const providerType = getCurrentEmailCampaignProviderType();
                const providers = getCampaignCapableProviderConnections(providerType);
                const selectedCampaign = findEmailCampaign(selectedEmailCampaignId);
                const preferredProviderId = String(
                    preferredValue
                    || emailCampaignProviderSelect.value
                    || (
                        selectedProviderConnectionId
                        && String((findProviderConnection(selectedProviderConnectionId) || {}).provider || '').toLowerCase() === providerType
                            ? selectedProviderConnectionId
                            : ''
                    )
                    || (
                        selectedCampaign
                        && String(selectedCampaign.provider || '').toLowerCase() === providerType
                            ? selectedCampaign.provider_connection_id
                            : ''
                    )
                    || ''
                ).trim();
                emailCampaignProviderSelect.innerHTML = '';
                const placeholder = document.createElement('option');
                placeholder.value = '';
                placeholder.textContent = `Select a ${getCampaignProviderConfig(providerType).label} connection`;
                emailCampaignProviderSelect.appendChild(placeholder);
                providers.forEach((provider) => {
                    const option = document.createElement('option');
                    option.value = provider.provider_connection_id;
                    const summary = formatProviderConnectionSummary(provider);
                    option.textContent = `${provider.name} (${summary.detail || 'not configured'})`;
                    emailCampaignProviderSelect.appendChild(option);
                });
                if (preferredProviderId && providers.some((item) => item.provider_connection_id === preferredProviderId)) {
                    emailCampaignProviderSelect.value = preferredProviderId;
                } else if (!preferredValue && providers.length === 1) {
                    emailCampaignProviderSelect.value = providers[0].provider_connection_id;
                } else {
                    emailCampaignProviderSelect.value = '';
                }
            }

            function populateEmailCampaignPredictionSelect(predictionJobs = cachedPredictionJobs) {
                const items = Array.isArray(predictionJobs) ? predictionJobs : [];
                const previousValue = emailCampaignPredictionJobSelect.value;
                emailCampaignPredictionJobSelect.innerHTML = '<option value="">Select a prediction audience</option>';
                items.forEach((job) => {
                    const option = document.createElement('option');
                    option.value = job.id;
                    option.textContent = formatPredictionAudienceOption(job);
                    emailCampaignPredictionJobSelect.appendChild(option);
                });
                if (previousValue && items.some((item) => item.id === previousValue)) {
                    emailCampaignPredictionJobSelect.value = previousValue;
                }
            }

            function resetEmailCampaignAudienceFieldSelects(message = 'Select an audience first.') {
                populateAudienceFieldSelect(emailCampaignRecipientEmailFieldSelect, [], {
                    placeholder: message,
                });
                populateAudienceFieldSelect(emailCampaignRecipientExternalIdFieldSelect, [], {
                    placeholder: message,
                });
                setInlineStatus(emailCampaignAudienceFieldStatus, message);
            }

            function syncEmailCampaignAudienceSourceFields() {
                const audienceType = getCurrentEmailCampaignAudienceType();
                emailCampaignPredictionJobGroup.style.display = audienceType === 'prediction' ? 'block' : 'none';
                emailCampaignCohortGroup.style.display = audienceType === 'cohort' ? 'block' : 'none';
                emailCampaignRiskFiltersGroup.style.display = audienceType === 'prediction' ? 'block' : 'none';
                emailCampaignIncludeChurnedGroup.style.display = audienceType === 'prediction' ? 'inline-flex' : 'none';
                if (audienceType === 'cohort') {
                    emailCampaignRiskFiltersInput.value = '';
                    emailCampaignIncludeChurnedCheckbox.checked = false;
                }
            }

            async function loadEmailCampaignAudienceFieldOptions({ forceRefresh = false, preserveSelection = true } = {}) {
                const { audienceType, audienceId } = getSelectedEmailCampaignAudienceSelection();
                const currentEmailField = preserveSelection ? String(emailCampaignRecipientEmailFieldSelect.value || '').trim() : '';
                const currentExternalIdField = preserveSelection ? String(emailCampaignRecipientExternalIdFieldSelect.value || '').trim() : '';
                if (!audienceId) {
                    resetEmailCampaignAudienceFieldSelects(
                        audienceType === 'cohort' ? 'Select a cohort audience first.' : 'Select a prediction audience first.',
                    );
                    return [];
                }
                const cacheKey = `${audienceType}:${audienceId}`;
                let fieldOptions = forceRefresh ? null : emailCampaignAudienceFieldCache.get(cacheKey);
                let sampleRows = [];
                if (!Array.isArray(fieldOptions)) {
                    const payload = audienceType === 'cohort'
                        ? await apiRequest(`/cohorts/${encodeURIComponent(audienceId)}/members?page=1&page_size=100`)
                        : await apiRequest(`/predictions/${encodeURIComponent(audienceId)}/results?page=1&page_size=100`);
                    sampleRows = Array.isArray(payload.items) ? payload.items : [];
                    const discoveredFields = new Set();
                    sampleRows.forEach((row) => {
                        collectObjectFieldPaths(row, '', discoveredFields);
                    });
                    fieldOptions = [...discoveredFields].sort((left, right) => left.localeCompare(right));
                    emailCampaignAudienceFieldCache.set(cacheKey, fieldOptions);
                    emailCampaignAudienceFieldCache.set(`${cacheKey}:sample-size`, sampleRows.length);
                } else {
                    sampleRows = new Array(Number(emailCampaignAudienceFieldCache.get(`${cacheKey}:sample-size`) || 0));
                }
                populateAudienceFieldSelect(emailCampaignRecipientEmailFieldSelect, fieldOptions, {
                    placeholder: fieldOptions.length ? 'Select recipient email field' : 'No audience fields detected',
                    preferredValue: currentEmailField,
                    fallbackKeys: ['email', 'profile.email', 'attributes.email'],
                });
                populateAudienceFieldSelect(emailCampaignRecipientExternalIdFieldSelect, fieldOptions, {
                    placeholder: fieldOptions.length ? 'Select recipient external id field' : 'No audience fields detected',
                    preferredValue: currentExternalIdField,
                    fallbackKeys: ['braze_external_id', 'external_user_id', 'user_id', 'canonical_user_id', 'email'],
                });
                if (!fieldOptions.length) {
                    setInlineStatus(emailCampaignAudienceFieldStatus, 'No JSON keys were detected from the sampled audience rows.', true);
                    return [];
                }
                const sampleCount = Number(emailCampaignAudienceFieldCache.get(`${cacheKey}:sample-size`) || sampleRows.length || 0);
                setInlineStatus(
                    emailCampaignAudienceFieldStatus,
                    `Detected ${fieldOptions.length} JSON key${fieldOptions.length === 1 ? '' : 's'} from ${sampleCount} sampled row${sampleCount === 1 ? '' : 's'}.`,
                );
                return fieldOptions;
            }

            function syncEmailCampaignProviderFields({ preferredProviderConnectionId = '' } = {}) {
                const providerType = getCurrentEmailCampaignProviderType();
                const descriptor = getCampaignProviderConfig(providerType);
                emailCampaignTemplateLabel.textContent = descriptor.assetLabel;
                emailCampaignRecipientEmailFieldGroup.style.display = providerType === 'braze' ? 'none' : 'block';
                emailCampaignRecipientExternalIdFieldGroup.style.display = providerType === 'braze' ? 'block' : 'none';
                populateEmailCampaignProviderSelect({ preferredValue: preferredProviderConnectionId });
            }

            function resetEmailCampaignTemplateSelect(message = '') {
                const descriptor = getCampaignProviderConfig(getCurrentEmailCampaignProviderType());
                emailCampaignTemplateSelect.innerHTML = '';
                const option = document.createElement('option');
                option.value = '';
                option.textContent = descriptor.selectProviderMessage;
                emailCampaignTemplateSelect.appendChild(option);
                setInlineStatus(emailCampaignTemplateStatus, message || descriptor.selectProviderMessage);
            }

            function formatMessagingAssetOptionLabel(asset, providerType = getCurrentEmailCampaignProviderType()) {
                if (providerType === 'braze') {
                    const tags = Array.isArray(asset.tags) && asset.tags.length ? ` (${asset.tags.join(', ')})` : '';
                    return `${asset.name || asset.id}${tags}`;
                }
                const activeVersion = asset.active_version || {};
                return `${asset.name || asset.id}${activeVersion.subject ? ` (${activeVersion.subject})` : ''}`;
            }

            function populateEmailCampaignAssetSelect(items = [], { selectedValue = '' } = {}) {
                const descriptor = getCampaignProviderConfig(getCurrentEmailCampaignProviderType());
                emailCampaignTemplateSelect.innerHTML = '';
                const placeholder = document.createElement('option');
                placeholder.value = '';
                placeholder.textContent = descriptor.assetOptionLabel;
                emailCampaignTemplateSelect.appendChild(placeholder);
                items.forEach((asset) => {
                    const option = document.createElement('option');
                    option.value = asset.id;
                    option.textContent = formatMessagingAssetOptionLabel(asset);
                    emailCampaignTemplateSelect.appendChild(option);
                });
                if (selectedValue && items.some((item) => item.id === selectedValue)) {
                    emailCampaignTemplateSelect.value = selectedValue;
                }
            }

            async function loadEmailCampaignAssets(providerConnectionId, { forceRefresh = false, preferredTemplateId = '' } = {}) {
                const provider = findProviderConnection(String(providerConnectionId || emailCampaignProviderSelect.value || '').trim()) || getSelectedEmailCampaignProviderConnection();
                const resolvedProviderId = String(provider?.provider_connection_id || providerConnectionId || emailCampaignProviderSelect.value || '').trim();
                const providerType = String(provider?.provider || getCurrentEmailCampaignProviderType()).trim().toLowerCase() || 'sendgrid';
                const descriptor = getCampaignProviderConfig(providerType);
                if (!resolvedProviderId) {
                    resetEmailCampaignTemplateSelect(descriptor.selectProviderMessage);
                    return [];
                }
                const selectedTemplateId = preferredTemplateId || emailCampaignTemplateSelect.value || '';
                if (!forceRefresh && emailCampaignAssetCache.has(resolvedProviderId)) {
                    const cachedAssets = emailCampaignAssetCache.get(resolvedProviderId) || [];
                    populateEmailCampaignAssetSelect(cachedAssets, { selectedValue: selectedTemplateId });
                    setInlineStatus(
                        emailCampaignTemplateStatus,
                        `Loaded ${cachedAssets.length} ${descriptor.loadedAssetNoun}${cachedAssets.length === 1 ? '' : 's'} from cache.`,
                    );
                    return cachedAssets;
                }
                try {
                    setInlineStatus(emailCampaignTemplateStatus, descriptor.loadingAssetsMessage);
                    const payload = await apiRequest(`/provider-connections/${encodeURIComponent(resolvedProviderId)}/messaging-assets`);
                    const assets = sortMessagingAssets(Array.isArray(payload.items) ? payload.items : []);
                    emailCampaignAssetCache.set(resolvedProviderId, assets);
                    populateEmailCampaignAssetSelect(assets, { selectedValue: selectedTemplateId });
                    setInlineStatus(
                        emailCampaignTemplateStatus,
                        assets.length
                            ? `Loaded ${assets.length} ${descriptor.loadedAssetNoun}${assets.length === 1 ? '' : 's'}.`
                            : descriptor.emptyAssetMessage,
                    );
                    return assets;
                } catch (error) {
                    resetEmailCampaignTemplateSelect(error.message || descriptor.selectProviderMessage);
                    setInlineStatus(emailCampaignTemplateStatus, error.message || `Failed to load ${descriptor.label} assets.`, true);
                    throw error;
                }
            }

            function syncEmailCampaignBuilderState(campaign = null) {
                const status = String((campaign || {}).status || '').toLowerCase();
                const locked = Boolean(campaign && !['draft', 'scheduled'].includes(status));
                emailCampaignSaveDraftBtn.disabled = locked;
                emailCampaignScheduleBtn.disabled = locked;
                emailCampaignSendNowBtn.disabled = locked;
                if (!campaign) {
                    emailCampaignSelectedLabel.textContent = 'No campaign selected';
                    return;
                }
                emailCampaignSelectedLabel.textContent = `${campaign.name || campaign.email_campaign_id} · ${formatEmailCampaignStatusLabel(campaign.status)}`;
                if (locked) {
                    setInlineStatus(
                        emailCampaignStatus,
                        `Campaign is ${formatEmailCampaignStatusLabel(status)}. Clear the form to create a new draft.`,
                        true,
                    );
                }
            }

            async function loadEmailCampaignDetail(emailCampaignId) {
                selectedEmailCampaignId = emailCampaignId || null;
                if (!selectedEmailCampaignId) {
                    syncEmailCampaignBuilderState(null);
                    renderJsonOutput(emailCampaignDetailOutput, null, '');
                    return;
                }
                const campaign = await apiRequest(`/email-campaigns/${encodeURIComponent(selectedEmailCampaignId)}`);
                renderJsonOutput(emailCampaignDetailOutput, campaign, '');
                syncEmailCampaignBuilderState(campaign);
                if (selectedWorkflowStudioResourceType === 'email_campaign' && selectedWorkflowStudioResourceId === selectedEmailCampaignId) {
                    if (workflowStudioSelectedLabel) {
                        workflowStudioSelectedLabel.textContent = `${campaign.name || campaign.email_campaign_id} · ${formatEmailCampaignStatusLabel(campaign.status)}`;
                    }
                    renderJsonOutput(workflowStudioDetailOutput, campaign, '');
                    renderWorkflowStudioDetailActions('email_campaign', campaign);
                }
                const providerType = String(
                    campaign.provider
                    || (findProviderConnection(campaign.provider_connection_id) || {}).provider
                    || 'sendgrid'
                ).trim().toLowerCase() || 'sendgrid';
                const audience = campaign.audience || {};
                const audienceType = String(audience.cohort_id || '').trim() ? 'cohort' : 'prediction';
                emailCampaignProviderTypeSelect.value = providerType;
                emailCampaignAudienceTypeSelect.value = audienceType;
                syncEmailCampaignAudienceSourceFields();
                syncEmailCampaignProviderFields({ preferredProviderConnectionId: campaign.provider_connection_id });
                emailCampaignNameInput.value = campaign.name || '';
                if (emailCampaignSubjectInput) {
                    emailCampaignSubjectInput.value = campaign.subject || '';
                }
                if (emailCampaignBodyInput) {
                    emailCampaignBodyInput.value = campaign.body || '';
                }
                emailCampaignRiskFiltersInput.value = Array.isArray(audience.include_risks) ? audience.include_risks.join(',') : '';
                emailCampaignIncludeChurnedCheckbox.checked = Boolean(audience.include_churned);
                emailCampaignDeeplinkTemplateFieldInput.value = campaign.deeplink_template_field || 'deeplink_url';
                emailCampaignDeeplinkOverrideFieldInput.value = campaign.deeplink_override_field || '';
                emailCampaignDeeplinkTemplateInput.value = campaign.deeplink_template || '';
                emailCampaignMergeFieldsInput.value = JSON.stringify(campaign.merge_fields || {}, null, 2);
                syncNoCodeSetupArtifacts(['email-campaign-merge-fields-input']);
                emailCampaignScheduleAtInput.value = fromIsoToLocalDateTimeInput(campaign.schedule_at);
                ensureSelectOption(emailCampaignProviderSelect, campaign.provider_connection_id, campaign.provider_connection_id);
                emailCampaignProviderSelect.value = campaign.provider_connection_id || '';
                const predictionJobId = String(audience.prediction_job_id || '').trim();
                const cohortId = String(audience.cohort_id || '').trim();
                if (predictionJobId) {
                    ensureSelectOption(emailCampaignPredictionJobSelect, predictionJobId, formatEmailCampaignAudienceLabel({ prediction_job_id: predictionJobId }));
                    emailCampaignPredictionJobSelect.value = predictionJobId;
                } else {
                    emailCampaignPredictionJobSelect.value = '';
                }
                if (cohortId) {
                    ensureSelectOption(emailCampaignCohortSelect, cohortId, formatEmailCampaignAudienceLabel({ cohort_id: cohortId }));
                    emailCampaignCohortSelect.value = cohortId;
                } else {
                    emailCampaignCohortSelect.value = '';
                }
                await loadEmailCampaignAudienceFieldOptions({ preserveSelection: false });
                if (providerType === 'braze') {
                    ensureSelectOption(
                        emailCampaignRecipientExternalIdFieldSelect,
                        campaign.recipient_external_id_field || 'user_id',
                        campaign.recipient_external_id_field || 'user_id',
                    );
                    emailCampaignRecipientExternalIdFieldSelect.value = campaign.recipient_external_id_field || 'user_id';
                } else {
                    ensureSelectOption(
                        emailCampaignRecipientEmailFieldSelect,
                        campaign.recipient_email_field || 'email',
                        campaign.recipient_email_field || 'email',
                    );
                    emailCampaignRecipientEmailFieldSelect.value = campaign.recipient_email_field || 'email';
                }
                try {
                    await loadEmailCampaignAssets(campaign.provider_connection_id, {
                        forceRefresh: false,
                        preferredTemplateId: campaign.template_id,
                    });
                    ensureSelectOption(emailCampaignTemplateSelect, campaign.template_id, campaign.template_summary?.name || campaign.template_id);
                    emailCampaignTemplateSelect.value = campaign.template_id || '';
                } catch (error) {
                    ensureSelectOption(emailCampaignTemplateSelect, campaign.template_id, campaign.template_summary?.name || campaign.template_id);
                    emailCampaignTemplateSelect.value = campaign.template_id || '';
                }
            }

            function resetEmailCampaignForm() {
                selectedEmailCampaignId = null;
                emailCampaignNameInput.value = '';
                if (emailCampaignSubjectInput) {
                    emailCampaignSubjectInput.value = '';
                }
                if (emailCampaignBodyInput) {
                    emailCampaignBodyInput.value = '';
                }
                emailCampaignAudienceTypeSelect.value = 'prediction';
                emailCampaignPredictionJobSelect.value = '';
                emailCampaignCohortSelect.value = '';
                emailCampaignRiskFiltersInput.value = '';
                emailCampaignIncludeChurnedCheckbox.checked = false;
                syncEmailCampaignAudienceSourceFields();
                resetEmailCampaignAudienceFieldSelects('Select an audience first.');
                emailCampaignDeeplinkTemplateFieldInput.value = 'deeplink_url';
                emailCampaignDeeplinkOverrideFieldInput.value = '';
                emailCampaignDeeplinkTemplateInput.value = '';
                emailCampaignMergeFieldsInput.value = getDefaultEmailCampaignMergeFieldsText();
                syncNoCodeSetupArtifacts(['email-campaign-merge-fields-input']);
                emailCampaignScheduleAtInput.value = '';
                renderJsonOutput(emailCampaignDetailOutput, null, '');
                setInlineStatus(emailCampaignStatus, 'Creating a new draft.');
                syncEmailCampaignBuilderState(null);
            }

            function buildEmailCampaignPayload({ scheduleAtOverride = undefined } = {}) {
                const mergeFields = parseJsonText(emailCampaignMergeFieldsInput.value, {});
                if (!mergeFields || typeof mergeFields !== 'object' || Array.isArray(mergeFields)) {
                    throw new Error('Merge fields must be a JSON object.');
                }
                const provider = getSelectedEmailCampaignProviderConnection()?.provider || getCurrentEmailCampaignProviderType();
                const descriptor = getCampaignProviderConfig(provider);
                const providerConnectionId = String(emailCampaignProviderSelect.value || '').trim();
                const templateId = String(emailCampaignTemplateSelect.value || '').trim();
                const audienceType = getCurrentEmailCampaignAudienceType();
                const predictionJobId = String(emailCampaignPredictionJobSelect.value || '').trim();
                const cohortId = String(emailCampaignCohortSelect.value || '').trim();
                if (!providerConnectionId) {
                    throw new Error(`Select a ${descriptor.label} provider connection.`);
                }
                if (!templateId) {
                    throw new Error(`Select a ${descriptor.assetLabel.toLowerCase()}.`);
                }
                if (audienceType === 'cohort' && !cohortId) {
                    throw new Error('Select a cohort audience.');
                }
                if (audienceType !== 'cohort' && !predictionJobId) {
                    throw new Error('Select a prediction audience.');
                }
                const payload = {
                    name: String(emailCampaignNameInput.value || '').trim(),
                    provider,
                    provider_connection_id: providerConnectionId,
                    template_id: templateId,
                    subject: String(emailCampaignSubjectInput?.value || '').trim() || null,
                    body: String(emailCampaignBodyInput?.value || '').trim() || null,
                    audience: audienceType === 'cohort'
                        ? {
                            cohort_id: cohortId,
                        }
                        : {
                            prediction_job_id: predictionJobId,
                            include_risks: splitCsv(emailCampaignRiskFiltersInput.value).map((item) => item.toLowerCase()),
                            include_churned: Boolean(emailCampaignIncludeChurnedCheckbox.checked),
                        },
                    merge_fields: mergeFields,
                    deeplink_template_field: String(emailCampaignDeeplinkTemplateFieldInput.value || '').trim() || 'deeplink_url',
                    deeplink_override_field: String(emailCampaignDeeplinkOverrideFieldInput.value || '').trim() || null,
                    deeplink_template: String(emailCampaignDeeplinkTemplateInput.value || '').trim() || null,
                };
                if (provider === 'braze') {
                    payload.recipient_external_id_field = String(emailCampaignRecipientExternalIdFieldSelect.value || '').trim() || 'user_id';
                } else {
                    payload.recipient_email_field = String(emailCampaignRecipientEmailFieldSelect.value || '').trim() || 'email';
                }
                if (!payload.name) {
                    throw new Error('Campaign name is required.');
                }
                if (scheduleAtOverride !== undefined) {
                    payload.schedule_at = scheduleAtOverride;
                } else {
                    payload.schedule_at = toIsoFromLocalDateTimeInput(emailCampaignScheduleAtInput.value);
                }
                return payload;
            }

            async function persistEmailCampaign({ scheduled = false } = {}) {
                const scheduleAt = scheduled ? toIsoFromLocalDateTimeInput(emailCampaignScheduleAtInput.value) : null;
                if (scheduled && !scheduleAt) {
                    throw new Error('Choose a schedule time before scheduling the campaign.');
                }
                const payload = buildEmailCampaignPayload({ scheduleAtOverride: scheduleAt });
                if (selectedEmailCampaignId) {
                    return apiRequest(`/email-campaigns/${encodeURIComponent(selectedEmailCampaignId)}`, {
                        method: 'PATCH',
                        body: payload,
                    });
                }
                return apiRequest('/email-campaigns', {
                    method: 'POST',
                    body: payload,
                });
            }

            async function sendEmailCampaignNow() {
                let emailCampaignId = selectedEmailCampaignId;
                if (!emailCampaignId) {
                    setInlineStatus(emailCampaignStatus, 'Saving draft before sending...');
                    const created = await persistEmailCampaign({ scheduled: false });
                    emailCampaignId = created.email_campaign_id;
                    selectedEmailCampaignId = emailCampaignId;
                }
                const response = await apiRequest(`/email-campaigns/${encodeURIComponent(emailCampaignId)}/send-now`, {
                    method: 'POST',
                });
                return response;
            }

            function bindEmailCampaignActionButtons(container) {
                if (!container) return;
                container.querySelectorAll('[data-email-campaign-action]').forEach((button) => {
                    button.addEventListener('click', async () => {
                        const emailCampaignId = button.dataset.emailCampaignId;
                        const action = button.dataset.emailCampaignAction;
                        if (!emailCampaignId || !action) return;
                        try {
                            if (action === 'view' || action === 'edit') {
                                await loadEmailCampaignDetail(emailCampaignId);
                                return;
                            }
                            if (action === 'send-now') {
                                setInlineStatus(emailCampaignStatus, 'Sending campaign now...');
                                await apiRequest(`/email-campaigns/${encodeURIComponent(emailCampaignId)}/send-now`, { method: 'POST' });
                            }
                            if (action === 'cancel') {
                                await apiRequest(`/email-campaigns/${encodeURIComponent(emailCampaignId)}/cancel`, { method: 'POST' });
                            }
                            if (action === 'delete') {
                                await apiRequest(`/email-campaigns/${encodeURIComponent(emailCampaignId)}`, { method: 'DELETE' });
                                if (selectedEmailCampaignId === emailCampaignId) {
                                    resetEmailCampaignForm();
                                }
                            }
                            await loadEmailCampaignWorkspace({ preserveSelection: action !== 'delete', forceTemplateRefresh: false });
                            if (action !== 'delete') {
                                await loadEmailCampaignDetail(emailCampaignId);
                            }
                        } catch (error) {
                            setInlineStatus(emailCampaignStatus, error.message || `Failed to ${action} campaign.`, true);
                        }
                    });
                });
            }

            function renderTableActionMenu(buttons = []) {
                const validButtons = buttons.filter(Boolean);
                if (!validButtons.length) {
                    return '';
                }
                return `
                    <details class="table-action-more">
                        <summary>More</summary>
                        <div class="table-action-more-menu">
                            ${validButtons.join('')}
                        </div>
                    </details>
                `;
            }

            function renderEmailCampaignActionButton(action, campaignId, label) {
                return `<button type="button" data-email-campaign-action="${escapeHtml(action)}" data-email-campaign-id="${escapeHtml(campaignId)}">${escapeHtml(label)}</button>`;
            }

            function renderEmailCampaignLists(items = cachedEmailCampaigns) {
                const campaigns = Array.isArray(items) ? items : [];
                const upcomingItems = campaigns.filter((item) => ['draft', 'scheduled'].includes(String(item.status || '').toLowerCase()));
                const pastItems = campaigns.filter((item) => ['sent', 'sent_with_errors', 'failed', 'cancelled'].includes(String(item.status || '').toLowerCase()));
                renderSimpleTable(
                    emailCampaignUpcomingList,
                    [
                        { label: 'Campaign', render: (item) => `<strong>${escapeHtml(item.name || '-')}</strong><div class="subtle">${escapeHtml(item.email_campaign_id || '-')}</div>` },
                        { label: 'Provider', render: (item) => `<span class="pill">${escapeHtml(formatConnectorLabel(item.provider || (findProviderConnection(item.provider_connection_id) || {}).provider || 'sendgrid'))}</span>` },
                        { label: 'Status', render: (item) => `<span class="pill">${escapeHtml(formatEmailCampaignStatusLabel(item.status))}</span>` },
                        { label: 'Audience', render: (item) => escapeHtml(formatEmailCampaignAudienceLabel(item.audience || {})) },
                        { label: 'Schedule', render: (item) => escapeHtml(formatDateTime(item.schedule_at)) },
                        {
                            label: 'Actions',
                            render: (item) => {
                                const status = String(item.status || '').toLowerCase();
                                const campaignId = item.email_campaign_id;
                                const visibleButtons = [
                                    renderEmailCampaignActionButton('edit', campaignId, 'Edit'),
                                    renderEmailCampaignActionButton('send-now', campaignId, 'Send Now'),
                                ];
                                const moreButtons = [
                                    status === 'scheduled'
                                        ? renderEmailCampaignActionButton('cancel', campaignId, 'Cancel')
                                        : renderEmailCampaignActionButton('delete', campaignId, 'Delete'),
                                ];
                                return `
                                    <div class="table-actions">
                                        ${visibleButtons.join('')}
                                        ${renderTableActionMenu(moreButtons)}
                                    </div>
                                `;
                            },
                        },
                    ],
                    upcomingItems,
                    'No draft or scheduled campaigns yet.',
                );
                renderSimpleTable(
                    emailCampaignPastList,
                    [
                        { label: 'Campaign', render: (item) => `<strong>${escapeHtml(item.name || '-')}</strong><div class="subtle">${escapeHtml(item.email_campaign_id || '-')}</div>` },
                        { label: 'Provider', render: (item) => `<span class="pill">${escapeHtml(formatConnectorLabel(item.provider || (findProviderConnection(item.provider_connection_id) || {}).provider || 'sendgrid'))}</span>` },
                        { label: 'Status', render: (item) => `<span class="pill">${escapeHtml(formatEmailCampaignStatusLabel(item.status))}</span>` },
                        { label: 'Completed', render: (item) => escapeHtml(formatDateTime(item.last_send_completed_at || item.cancelled_at)) },
                        { label: 'Sent', render: (item) => escapeHtml(String(((item.result_summary || {}).sent_count) || 0)) },
                        { label: 'Actions', render: (item) => `<button type="button" data-email-campaign-action="view" data-email-campaign-id="${escapeHtml(item.email_campaign_id)}">View</button>` },
                    ],
                    pastItems,
                    'No completed campaigns yet.',
                );
                bindEmailCampaignActionButtons(emailCampaignUpcomingList);
                bindEmailCampaignActionButtons(emailCampaignPastList);
                updateEmailCampaignSummary();
            }

            async function loadEmailCampaignWorkspace({ preserveSelection = true, forceTemplateRefresh = false } = {}) {
                try {
                    const [providers, predictionJobs, cohorts, campaigns] = await Promise.all([
                        refreshProviderConnectionsState(),
                        refreshPredictionJobsState(),
                        refreshCohortsState(),
                        refreshEmailCampaignsState(),
                    ]);
                    renderProviderConnectionList(providers);
                    populateEmailCampaignPredictionSelect(predictionJobs);
                    populateEmailCampaignCohortSelect(cohorts);
                    syncEmailCampaignAudienceSourceFields();
                    syncEmailCampaignProviderFields();
                    renderEmailCampaignLists(campaigns);
                    renderWorkflowStudioList();
                    const hasSelectedCampaign = preserveSelection && selectedEmailCampaignId && campaigns.some((item) => item.email_campaign_id === selectedEmailCampaignId);
                    if (hasSelectedCampaign) {
                        await loadEmailCampaignDetail(selectedEmailCampaignId);
                    } else {
                        if (selectedEmailCampaignId && !campaigns.some((item) => item.email_campaign_id === selectedEmailCampaignId)) {
                            resetEmailCampaignForm();
                        }
                        if (emailCampaignProviderSelect.value) {
                            await loadEmailCampaignAssets(emailCampaignProviderSelect.value, {
                                forceRefresh: forceTemplateRefresh,
                                preferredTemplateId: emailCampaignTemplateSelect.value,
                            });
                        } else {
                            resetEmailCampaignTemplateSelect(getCampaignProviderConfig(getCurrentEmailCampaignProviderType()).selectProviderMessage);
                        }
                        await loadEmailCampaignAudienceFieldOptions({ forceRefresh: forceTemplateRefresh, preserveSelection: true });
                    }
                    if (selectedProviderConnectionId && providers.some((item) => item.provider_connection_id === selectedProviderConnectionId)) {
                        loadProviderConnectionIntoForm(selectedProviderConnectionId);
                    } else if (isProviderConnectionFormVisible()) {
                        syncProviderConnectionFormState();
                    } else {
                        syncProviderConnectionFormFields();
                        syncProviderConnectionFormState();
                    }
                } catch (error) {
                    if (isWorkspaceContextError(error)) {
                        cachedProviderConnections = [];
                        cachedCohorts = [];
                        cachedEmailCampaigns = [];
                        setProviderConnectionFormVisible(false);
                        renderProviderConnectionList([]);
                        renderEmailCampaignLists([]);
                        renderWorkflowStudioList();
                        resetEmailCampaignTemplateSelect('Finish workspace setup to load campaign messaging assets.');
                        resetEmailCampaignAudienceFieldSelects('Finish workspace setup to inspect audience fields.');
                        setInlineStatus(providerConnectionStatus, getWorkspaceResolutionMessage(error.payload || authSessionState), true);
                        setInlineStatus(emailCampaignStatus, getWorkspaceResolutionMessage(error.payload || authSessionState), true);
                        return;
                    }
                    setInlineStatus(providerConnectionStatus, error.message || 'Failed to load provider connections.', true);
                    setInlineStatus(emailCampaignStatus, error.message || 'Failed to load email campaigns.', true);
                }
            }

            function getSelectedMultiSelectValues(select) {
                if (!select) return [];
                return Array.from(select.selectedOptions || [])
                    .map((option) => String(option.value || '').trim())
                    .filter(Boolean);
            }

            function setSelectedMultiSelectValues(select, values = []) {
                if (!select) return;
                const selectedValues = new Set((Array.isArray(values) ? values : []).map((item) => String(item || '').trim()).filter(Boolean));
                Array.from(select.options || []).forEach((option) => {
                    option.selected = selectedValues.has(String(option.value || '').trim());
                });
            }

            function setSelectOptions(select, items = [], { placeholder = '', valueKey = 'id', labelKey = 'label', selectedValues = [] } = {}) {
                if (!select) return;
                const multiple = Boolean(select.multiple);
                const normalizedItems = Array.isArray(items) ? items : [];
                const preservedValues = multiple
                    ? new Set((Array.isArray(selectedValues) && selectedValues.length ? selectedValues : getSelectedMultiSelectValues(select)).map((item) => String(item || '').trim()))
                    : null;
                const preservedValue = multiple
                    ? ''
                    : String(
                        (Array.isArray(selectedValues) && selectedValues.length ? selectedValues[0] : select.value)
                        || '',
                    ).trim();
                select.innerHTML = '';
                if (!multiple && placeholder) {
                    const placeholderOption = document.createElement('option');
                    placeholderOption.value = '';
                    placeholderOption.textContent = placeholder;
                    select.appendChild(placeholderOption);
                }
                normalizedItems.forEach((item) => {
                    const option = document.createElement('option');
                    option.value = String(item?.[valueKey] ?? '');
                    option.textContent = String(item?.[labelKey] ?? item?.label ?? item?.name ?? option.value);
                    select.appendChild(option);
                });
                if (multiple) {
                    setSelectedMultiSelectValues(select, Array.from(preservedValues || []));
                } else if (preservedValue && Array.from(select.options).some((option) => option.value === preservedValue)) {
                    select.value = preservedValue;
                } else if (!multiple && !placeholder && select.options.length) {
                    select.value = select.options[0].value;
                } else {
                    select.value = '';
                }
            }

            function getAudienceBuilderBasis() {
                return String(audienceBuilderBasisSelect?.value || audienceBuilderOptions?.defaults?.audience_basis || 'prediction').trim().toLowerCase() || 'prediction';
            }

            function populateAudienceBuilderSavedQuerySelect({ preserveSelection = true } = {}) {
                if (!audienceBuilderSavedQuerySelect) {
                    return;
                }
                setSelectOptions(
                    audienceBuilderSavedQuerySelect,
                    (cachedSavedQueries || []).map((query) => ({
                        id: query.query_id,
                        label: `${query.name || query.query_id} · ${formatDateTime(query.updated_at)}`,
                    })),
                    {
                        placeholder: 'Use the current SQL below',
                        valueKey: 'id',
                        labelKey: 'label',
                        selectedValues: preserveSelection && audienceBuilderSavedQuerySelect.value
                            ? [audienceBuilderSavedQuerySelect.value]
                            : [],
                    },
                );
            }

            function getAudienceBuilderSelectedConnector() {
                const connectorId = String(audienceBuilderConnectorSelect?.value || '').trim();
                return (audienceBuilderOptions?.warehouse_connectors || []).find((item) => String(item.connector_id || '') === connectorId) || null;
            }

            function populateAudienceBuilderConnectorSelect({ preserveSelection = true } = {}) {
                if (!audienceBuilderConnectorSelect) {
                    return;
                }
                setSelectOptions(
                    audienceBuilderConnectorSelect,
                    (audienceBuilderOptions?.warehouse_connectors || []).map((connector) => ({
                        id: connector.connector_id,
                        label: `${connector.name || connector.connector_id} · ${(connector.project_id || 'project').toString()}.${(connector.dataset_id || 'dataset').toString()}`,
                    })),
                    {
                        placeholder: 'Select connector',
                        valueKey: 'id',
                        labelKey: 'label',
                        selectedValues: preserveSelection && audienceBuilderConnectorSelect.value
                            ? [audienceBuilderConnectorSelect.value]
                            : [],
                    },
                );
            }

            function populateAudienceBuilderConnectorTableSelect({ preserveSelection = true } = {}) {
                if (!audienceBuilderConnectorTableSelect) {
                    return;
                }
                setSelectOptions(
                    audienceBuilderConnectorTableSelect,
                    (audienceBuilderConnectorTables || []).map((item) => ({
                        id: item.table_name,
                        label: `${item.table_name || '-'} · ${item.table_type || 'table'}${Number.isFinite(item.row_count) ? ` · ${item.row_count} rows` : ''}`,
                    })),
                    {
                        placeholder: 'Select table or view',
                        valueKey: 'id',
                        labelKey: 'label',
                        selectedValues: preserveSelection && audienceBuilderConnectorTableSelect.value
                            ? [audienceBuilderConnectorTableSelect.value]
                            : [],
                    },
                );
            }

            async function loadAudienceBuilderConnectorTables({ preserveSelection = true } = {}) {
                const connector = getAudienceBuilderSelectedConnector();
                if (!connector) {
                    audienceBuilderConnectorTables = [];
                    populateAudienceBuilderConnectorTableSelect({ preserveSelection: false });
                    setInlineStatus(audienceBuilderConnectorStatus, 'Choose a BigQuery connector to list tables.');
                    return;
                }
                try {
                    setInlineStatus(audienceBuilderConnectorStatus, 'Loading connector tables...');
                    const payload = await apiRequest(`/connectors/${encodeURIComponent(connector.name)}/tables`);
                    audienceBuilderConnectorTables = Array.isArray(payload.items) ? payload.items : [];
                    populateAudienceBuilderConnectorTableSelect({ preserveSelection });
                    setInlineStatus(
                        audienceBuilderConnectorStatus,
                        audienceBuilderConnectorTables.length
                            ? `Loaded ${audienceBuilderConnectorTables.length} table(s) from ${connector.name}.`
                            : `No tables were returned for ${connector.name}.`,
                    );
                } catch (error) {
                    audienceBuilderConnectorTables = [];
                    populateAudienceBuilderConnectorTableSelect({ preserveSelection: false });
                    setInlineStatus(audienceBuilderConnectorStatus, error.message || 'Failed to load connector tables.', true);
                }
            }

            function getAudienceBuilderColumnMapping() {
                const mapping = {};
                const canonicalUserIdField = String(audienceBuilderCanonicalUserIdFieldInput?.value || '').trim();
                const emailField = String(audienceBuilderEmailFieldInput?.value || '').trim();
                const externalUserIdField = String(audienceBuilderExternalUserIdFieldInput?.value || '').trim();
                if (canonicalUserIdField) {
                    mapping.canonical_user_id = canonicalUserIdField;
                }
                if (emailField) {
                    mapping.email = emailField;
                }
                if (externalUserIdField) {
                    mapping.external_user_id = externalUserIdField;
                }
                return mapping;
            }

            function getAudienceBuilderPredictionScope() {
                return String(audienceBuilderPredictionScopeSelect?.value || audienceBuilderOptions?.defaults?.prediction_scope || 'source').trim().toLowerCase() || 'source';
            }

            function getAudienceBuilderAvailableFields(basis = getAudienceBuilderBasis()) {
                return (audienceBuilderOptions?.filter_fields || []).filter((item) => Array.isArray(item.available_in) && item.available_in.includes(basis));
            }

            function getAudienceBuilderFieldMeta(fieldName, basis = getAudienceBuilderBasis()) {
                return getAudienceBuilderAvailableFields(basis).find((item) => item.field === fieldName) || null;
            }

            function createAudienceBuilderCondition(fieldMeta = null) {
                const availableFields = getAudienceBuilderAvailableFields();
                const resolvedField = fieldMeta || availableFields[0] || { field: 'email', value_type: 'string', operators: ['contains'] };
                const firstOption = Array.isArray(resolvedField.options) && resolvedField.options.length ? resolvedField.options[0] : '';
                return {
                    id: `builder_condition_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`,
                    field: resolvedField.field,
                    op: Array.isArray(resolvedField.operators) && resolvedField.operators.length ? resolvedField.operators[0] : '=',
                    value: resolvedField.value_type === 'enum' ? firstOption : '',
                    value_type: resolvedField.value_type || 'string',
                };
            }

            function resetAudienceBuilderPreview(message = 'No preview yet.') {
                audienceBuilderPreview = null;
                if (audienceBuilderPreviewSummary) {
                    audienceBuilderPreviewSummary.innerHTML = `<div class="list-empty">${escapeHtml(message)}</div>`;
                }
                if (audienceBuilderPreviewMembers) {
                    audienceBuilderPreviewMembers.innerHTML = '<div class="list-empty">No members.</div>';
                }
                if (audienceBuilderPreviewBreakdown) {
                    audienceBuilderPreviewBreakdown.innerHTML = '<div class="list-empty">No breakdown.</div>';
                }
            }

            function formatAudienceBuilderCondition(condition = {}) {
                const fieldMeta = getAudienceBuilderFieldMeta(condition.field, condition.available_in?.[0] || getAudienceBuilderBasis())
                    || (audienceBuilderOptions?.filter_fields || []).find((item) => item.field === condition.field)
                    || {};
                const fieldLabel = fieldMeta.label || condition.field || 'Field';
                const operator = String(condition.op || '=').trim();
                const rawValue = condition.value;
                const value = Array.isArray(rawValue) ? rawValue.join(', ') : rawValue;
                return `${fieldLabel} ${operator} ${String(value ?? '').trim() || 'value'}`;
            }

            function renderAudienceBuilderPreview(preview = audienceBuilderPreview) {
                if (!preview) {
                    resetAudienceBuilderPreview();
                    return;
                }
                const request = preview.request || {};
                const warnings = Array.isArray(preview.warnings) ? preview.warnings : [];
                const proposedNames = Array.isArray(preview.proposed_names) ? preview.proposed_names : [];
                const conditions = Array.isArray(request.conditions) ? request.conditions : [];
                const previewFields = Array.isArray(preview.preview_fields) ? preview.preview_fields : [];
                const summaryCards = [
                    { label: 'Members', value: String(preview.member_count || 0) },
                    { label: 'Mode', value: String(preview.mode || 'combined').replace(/_/g, ' ') },
                    { label: 'Refresh', value: String(request.refresh_mode || 'manual') },
                    { label: 'Output', value: proposedNames.length > 1 ? `${proposedNames.length} draft cohorts` : '1 draft cohort' },
                    { label: 'Source', value: String(preview.source_label || preview.source_kind || request.audience_basis || '-').replace(/_/g, ' ') },
                ];
                const warningsMarkup = warnings.length
                    ? `<div class="subtle" style="color: var(--danger-600);">${warnings.map((item) => escapeHtml(item)).join('<br>')}</div>`
                    : '';
                const conditionsMarkup = conditions.length
                    ? conditions.map((item) => `<span class="pill">${escapeHtml(formatAudienceBuilderCondition(item))}</span>`).join('')
                    : '<span class="subtle">None</span>';
                const namesMarkup = proposedNames.length
                    ? proposedNames.map((item) => `<span class="pill">${escapeHtml(item)}</span>`).join('')
                    : '<span class="subtle">None</span>';
                audienceBuilderPreviewSummary.innerHTML = `
                    ${summaryCards.map((item) => `
                        <div class="builder-preview-stat">
                            <span>${escapeHtml(item.label)}</span>
                            <strong>${escapeHtml(item.value)}</strong>
                        </div>
                    `).join('')}
                    <div class="builder-preview-stat" style="grid-column: 1 / -1;">
                        <span>Draft Names</span>
                        <div>${namesMarkup}</div>
                    </div>
                    <div class="builder-preview-stat" style="grid-column: 1 / -1;">
                        <span>Tags</span>
                        <div>${(request.tags || []).length ? request.tags.map((item) => `<span class="pill">${escapeHtml(item)}</span>`).join('') : '<span class="subtle">No tags yet.</span>'}</div>
                    </div>
                    <div class="builder-preview-stat" style="grid-column: 1 / -1;">
                        <span>Discovered Fields</span>
                        <div>${previewFields.length ? previewFields.map((item) => `<span class="pill">${escapeHtml(item)}</span>`).join('') : '<span class="subtle">No sampled fields.</span>'}</div>
                    </div>
                    <div class="builder-preview-stat" style="grid-column: 1 / -1;">
                        <span>Filters</span>
                        <div>${conditionsMarkup}</div>
                    </div>
                    ${warningsMarkup}
                `;
                renderSimpleTable(
                    audienceBuilderPreviewMembers,
                    [
                        { label: 'Canonical User ID', render: (item) => escapeHtml(String(item.canonical_user_id || '-')) },
                        { label: 'Email', render: (item) => escapeHtml(String(item.email || '-')) },
                        { label: 'Risk', render: (item) => escapeHtml(String(item.predicted_churn_risk || item.churn_state || '-')) },
                        { label: 'Sources', render: (item) => escapeHtml((item.matched_sources || [item.source_name]).filter(Boolean).join(', ') || '-') },
                    ],
                    preview.preview_members || [],
                    'No members.',
                );
                renderSimpleTable(
                    audienceBuilderPreviewBreakdown,
                    [
                        { label: 'Source', render: (item) => escapeHtml(String(item.source_name || item.prediction_job_id || '-')) },
                        { label: 'Prediction Run', render: (item) => escapeHtml(String(item.prediction_job_id || '-')) },
                        { label: 'Members', render: (item) => escapeHtml(String(item.member_count || 0)) },
                        { label: 'Rows', render: (item) => escapeHtml(String(item.row_count || 0)) },
                        { label: 'Completed', render: (item) => escapeHtml(formatDateTime(item.completed_at)) },
                    ],
                    preview.source_breakdown || [],
                    'No breakdown.',
                );
            }

            function renderAudienceBuilderSourceSummary() {
                if (!audienceBuilderSourceSummary) return;
                if (!audienceBuilderOptions) {
                    audienceBuilderSourceSummary.innerHTML = '<div class="list-empty">No sources.</div>';
                    return;
                }
                const basis = getAudienceBuilderBasis();
                if (basis === 'managed_warehouse_sql') {
                    const savedQuery = (cachedSavedQueries || []).find((item) => item.query_id === String(audienceBuilderSavedQuerySelect?.value || '').trim()) || null;
                    audienceBuilderSourceSummary.innerHTML = savedQuery
                        ? `
                            <div class="builder-source-card">
                                <div class="builder-source-head">
                                    <strong>${escapeHtml(savedQuery.name || savedQuery.query_id || 'Saved query')}</strong>
                                    <span class="pill">saved query</span>
                                </div>
                                <div class="subtle">${escapeHtml(savedQuery.query_id || '-')}</div>
                                <div class="subtle">${escapeHtml(savedQuery.description || 'The current SQL artifact will be frozen into the cohort definition.')}</div>
                            </div>
                        `
                        : '<div class="list-empty">Using the current SQL artifact.</div>';
                    return;
                }
                if (basis === 'connector_bigquery_table') {
                    const connector = getAudienceBuilderSelectedConnector();
                    const tableName = String(audienceBuilderConnectorTableSelect?.value || '').trim();
                    audienceBuilderSourceSummary.innerHTML = connector
                        ? `
                            <div class="builder-source-card">
                                <div class="builder-source-head">
                                    <strong>${escapeHtml(connector.name || connector.connector_id || 'BigQuery connector')}</strong>
                                    <span class="pill">${escapeHtml(tableName || 'select table')}</span>
                                </div>
                                <div class="subtle">${escapeHtml(`${connector.project_id || 'project'}.${connector.dataset_id || 'dataset'}`)}</div>
                                <div class="subtle">${escapeHtml(String(audienceBuilderWhereSqlInput?.value || '').trim() || 'No optional filter applied.')}</div>
                            </div>
                        `
                        : '<div class="list-empty">Choose a BigQuery connector and table.</div>';
                    return;
                }
                if (basis !== 'prediction') {
                    audienceBuilderSourceSummary.innerHTML = '<div class="list-empty">Not used here.</div>';
                    return;
                }
                const predictionScope = getAudienceBuilderPredictionScope();
                const selectedSourceNames = getSelectedMultiSelectValues(audienceBuilderSourceSelect);
                const selectedJobIds = getSelectedMultiSelectValues(audienceBuilderJobSelect);
                const selectedItems = predictionScope === 'prediction_job'
                    ? (audienceBuilderOptions.prediction_jobs || []).filter((item) => selectedJobIds.includes(String(item.prediction_job_id || '')))
                    : (audienceBuilderOptions.prediction_sources || []).filter((item) => selectedSourceNames.includes(String(item.source_name || '')));
                const items = selectedItems.length
                    ? selectedItems
                    : (predictionScope === 'prediction_job'
                        ? (audienceBuilderOptions.prediction_jobs || []).slice(0, 4)
                        : (audienceBuilderOptions.prediction_sources || []).slice(0, 4));
                if (!items.length) {
                    audienceBuilderSourceSummary.innerHTML = '<div class="list-empty">No runs.</div>';
                    return;
                }
                audienceBuilderSourceSummary.innerHTML = `
                    ${items.map((item) => `
                        <div class="builder-source-card">
                            <div class="builder-source-head">
                                <strong>${escapeHtml(item.source_name || item.audience_label || item.prediction_job_id || 'Prediction')}</strong>
                                <span class="pill">${escapeHtml(item.status || (item.is_latest_for_source ? 'latest' : 'completed'))}</span>
                            </div>
                            <div class="subtle">${escapeHtml(item.prediction_job_id || '-')}${item.prediction_mode ? ` · ${escapeHtml(item.prediction_mode)}` : ''}</div>
                            <div class="subtle">Completed ${escapeHtml(formatDateTime(item.completed_at))}</div>
                        </div>
                    `).join('')}
                `;
            }

            function renderAudienceBuilderValueControl(condition, fieldMeta) {
                const operator = String(condition.op || '=').trim().toLowerCase();
                const isMultiValue = operator === 'between' || operator === 'in' || operator === 'not in';
                const normalizedValue = Array.isArray(condition.value) ? condition.value.join(', ') : String(condition.value ?? '');
                if (fieldMeta?.value_type === 'enum' && Array.isArray(fieldMeta.options) && fieldMeta.options.length && !isMultiValue) {
                    return `
                        <select data-builder-value>
                            ${fieldMeta.options.map((item) => `
                                <option value="${escapeHtml(item)}" ${String(item) === normalizedValue ? 'selected' : ''}>${escapeHtml(item)}</option>
                            `).join('')}
                        </select>
                    `;
                }
                const inputType = fieldMeta?.value_type === 'number' && operator !== 'between' ? 'number' : 'text';
                const placeholder = operator === 'between'
                    ? 'min,max'
                    : (operator === 'in' || operator === 'not in')
                        ? 'value_a,value_b'
                        : `Enter ${String(fieldMeta?.label || 'value').toLowerCase()}`;
                return `<input data-builder-value type="${inputType}" value="${escapeHtml(normalizedValue)}" placeholder="${escapeHtml(placeholder)}">`;
            }

            function renderAudienceBuilderFilters() {
                if (!audienceBuilderFilters) return;
                const basis = getAudienceBuilderBasis();
                const supportsFilters = basis === 'prediction' || basis === 'behavior';
                if (!supportsFilters) {
                    audienceBuilderFilters.innerHTML = `<div class="list-empty">${escapeHtml(
                        basis === 'manual_list'
                            ? 'Not used here.'
                            : 'Not used here.',
                    )}</div>`;
                    return;
                }
                const availableFields = getAudienceBuilderAvailableFields(basis);
                if (!audienceBuilderConditions.length) {
                    audienceBuilderFilters.innerHTML = '<div class="list-empty">No filters.</div>';
                    return;
                }
                audienceBuilderConditions = audienceBuilderConditions
                    .map((condition) => {
                        const fallbackField = availableFields[0] || { field: 'email', operators: ['contains'], value_type: 'string' };
                        const fieldMeta = getAudienceBuilderFieldMeta(condition.field, basis) || fallbackField;
                        const operators = Array.isArray(fieldMeta.operators) && fieldMeta.operators.length ? fieldMeta.operators : ['='];
                        const op = operators.includes(condition.op) ? condition.op : operators[0];
                        return {
                            ...condition,
                            field: fieldMeta.field,
                            op,
                            value_type: fieldMeta.value_type || condition.value_type || 'string',
                        };
                    });
                audienceBuilderFilters.innerHTML = audienceBuilderConditions.map((condition) => {
                    const fieldMeta = getAudienceBuilderFieldMeta(condition.field, basis) || availableFields[0] || {};
                    const operators = Array.isArray(fieldMeta.operators) && fieldMeta.operators.length ? fieldMeta.operators : ['='];
                    return `
                        <div class="card builder-filter-row" data-condition-id="${escapeHtml(condition.id)}">
                            <div class="builder-filter-row-grid">
                                <div class="form-group">
                                    <label>Field</label>
                                    <select data-builder-field>
                                        ${availableFields.map((item) => `
                                            <option value="${escapeHtml(item.field)}" ${item.field === condition.field ? 'selected' : ''}>${escapeHtml(item.label)}</option>
                                        `).join('')}
                                    </select>
                                </div>
                                <div class="form-group">
                                    <label>Operator</label>
                                    <select data-builder-op>
                                        ${operators.map((item) => `
                                            <option value="${escapeHtml(item)}" ${item === condition.op ? 'selected' : ''}>${escapeHtml(item)}</option>
                                        `).join('')}
                                    </select>
                                </div>
                                <div class="form-group">
                                    <label>Value</label>
                                    ${renderAudienceBuilderValueControl(condition, fieldMeta)}
                                </div>
                                <div class="inline-actions" style="align-items: end;">
                                    <button type="button" data-builder-remove>Remove</button>
                                </div>
                            </div>
                        </div>
                    `;
                }).join('');
                audienceBuilderFilters.querySelectorAll('[data-condition-id]').forEach((row) => {
                    const conditionId = row.dataset.conditionId;
                    if (!conditionId) return;
                    const fieldSelect = row.querySelector('[data-builder-field]');
                    const operatorSelect = row.querySelector('[data-builder-op]');
                    const valueInput = row.querySelector('[data-builder-value]');
                    const removeButton = row.querySelector('[data-builder-remove]');
                    fieldSelect?.addEventListener('change', () => {
                        const fieldMeta = getAudienceBuilderFieldMeta(fieldSelect.value, basis) || availableFields[0] || null;
                        audienceBuilderConditions = audienceBuilderConditions.map((condition) => (
                            condition.id === conditionId ? createAudienceBuilderCondition(fieldMeta) : condition
                        ));
                        resetAudienceBuilderPreview('Preview cleared.');
                        renderAudienceBuilderFilters();
                    });
                    operatorSelect?.addEventListener('change', () => {
                        audienceBuilderConditions = audienceBuilderConditions.map((condition) => (
                            condition.id === conditionId ? { ...condition, op: operatorSelect.value } : condition
                        ));
                        resetAudienceBuilderPreview('Preview cleared.');
                        renderAudienceBuilderFilters();
                    });
                    valueInput?.addEventListener('input', () => {
                        audienceBuilderConditions = audienceBuilderConditions.map((condition) => (
                            condition.id === conditionId ? { ...condition, value: valueInput.value } : condition
                        ));
                    });
                    valueInput?.addEventListener('change', () => {
                        resetAudienceBuilderPreview('Preview cleared.');
                    });
                    removeButton?.addEventListener('click', () => {
                        audienceBuilderConditions = audienceBuilderConditions.filter((condition) => condition.id !== conditionId);
                        resetAudienceBuilderPreview('Preview cleared.');
                        renderAudienceBuilderFilters();
                    });
                });
            }

            function syncAudienceBuilderVisibility() {
                const basis = getAudienceBuilderBasis();
                const predictionScope = getAudienceBuilderPredictionScope();
                const supportsPrediction = basis === 'prediction';
                const supportsFilters = basis === 'prediction' || basis === 'behavior';
                const isManagedWarehouse = basis === 'managed_warehouse_sql';
                const isConnectorTable = basis === 'connector_bigquery_table';
                audienceBuilderPredictionControls?.classList.toggle('hidden', !supportsPrediction);
                audienceBuilderSourceGroup?.classList.toggle('hidden', !supportsPrediction || predictionScope !== 'source');
                audienceBuilderJobGroup?.classList.toggle('hidden', !supportsPrediction || predictionScope === 'source');
                audienceBuilderManagedSqlGroup?.classList.toggle('hidden', !isManagedWarehouse);
                audienceBuilderConnectorGroup?.classList.toggle('hidden', !isConnectorTable);
                audienceBuilderManualListGroup?.classList.toggle('hidden', basis !== 'manual_list');
                if (audienceBuilderOutputModeSelect) {
                    audienceBuilderOutputModeSelect.disabled = !supportsPrediction;
                    if (!supportsPrediction) {
                        audienceBuilderOutputModeSelect.value = 'combined';
                    }
                }
                if (audienceBuilderAddConditionBtn) {
                    audienceBuilderAddConditionBtn.style.display = supportsFilters ? 'inline-flex' : 'none';
                }
                if (isManagedWarehouse) {
                    document.getElementById('audience-sql-section')?.setAttribute('open', 'open');
                }
                renderAudienceBuilderSourceSummary();
                renderAudienceBuilderFilters();
            }

            function populateAudienceBuilderOptionSelects({ preserveSelection = true } = {}) {
                if (!audienceBuilderOptions) {
                    return;
                }
                const defaults = audienceBuilderOptions.defaults || {};
                setSelectOptions(
                    audienceBuilderBasisSelect,
                    audienceBuilderOptions.audience_bases || [],
                    {
                        placeholder: '',
                        valueKey: 'id',
                        labelKey: 'label',
                        selectedValues: preserveSelection && audienceBuilderBasisSelect?.value
                            ? [audienceBuilderBasisSelect.value]
                            : [defaults.audience_basis || 'prediction'],
                    },
                );
                setSelectOptions(
                    audienceBuilderPredictionScopeSelect,
                    audienceBuilderOptions.prediction_scopes || [],
                    {
                        placeholder: '',
                        valueKey: 'id',
                        labelKey: 'label',
                        selectedValues: preserveSelection && audienceBuilderPredictionScopeSelect?.value
                            ? [audienceBuilderPredictionScopeSelect.value]
                            : [defaults.prediction_scope || 'source'],
                    },
                );
                setSelectOptions(
                    audienceBuilderOutputModeSelect,
                    audienceBuilderOptions.output_modes || [],
                    {
                        placeholder: '',
                        valueKey: 'id',
                        labelKey: 'label',
                        selectedValues: preserveSelection && audienceBuilderOutputModeSelect?.value
                            ? [audienceBuilderOutputModeSelect.value]
                            : [defaults.output_mode || 'combined'],
                    },
                );
                if (audienceBuilderLogicSelect && !audienceBuilderLogicSelect.value) {
                    audienceBuilderLogicSelect.value = defaults.logic || 'AND';
                }
                setSelectOptions(
                    audienceBuilderSourceSelect,
                    (audienceBuilderOptions.prediction_sources || []).map((item) => ({
                        id: item.source_name,
                        label: `${item.source_name || item.audience_label || item.prediction_job_id} · latest ${formatDateTime(item.completed_at)}`,
                    })),
                    {
                        valueKey: 'id',
                        labelKey: 'label',
                        selectedValues: preserveSelection ? getSelectedMultiSelectValues(audienceBuilderSourceSelect) : [],
                    },
                );
                setSelectOptions(
                    audienceBuilderJobSelect,
                    (audienceBuilderOptions.prediction_jobs || []).map((item) => ({
                        id: item.prediction_job_id,
                        label: `${item.source_name || item.audience_label || item.prediction_job_id} · ${item.prediction_job_id} · ${formatDateTime(item.completed_at)}`,
                    })),
                    {
                        valueKey: 'id',
                        labelKey: 'label',
                        selectedValues: preserveSelection ? getSelectedMultiSelectValues(audienceBuilderJobSelect) : [],
                    },
                );
                populateAudienceBuilderConnectorSelect({ preserveSelection });
                syncAudienceBuilderVisibility();
            }

            async function loadAudienceBuilderOptions({ preserveSelection = true } = {}) {
                const payload = await apiRequest('/cohorts/builder/options');
                audienceBuilderOptions = payload || {};
                populateAudienceBuilderOptionSelects({ preserveSelection });
                populateAudienceBuilderSavedQuerySelect({ preserveSelection });
                if (audienceBuilderLogicSelect && !audienceBuilderLogicSelect.value) {
                    audienceBuilderLogicSelect.value = audienceBuilderOptions?.defaults?.logic || 'AND';
                }
                renderAudienceBuilderSourceSummary();
                renderAudienceBuilderFilters();
            }

            function parseAudienceBuilderMembersInput() {
                const raw = String(audienceBuilderMembersInput?.value || '').trim();
                if (!raw) {
                    return [];
                }
                try {
                    const parsed = parseJsonText(raw, []);
                    if (Array.isArray(parsed)) {
                        return parsed;
                    }
                    if (parsed && typeof parsed === 'object') {
                        return [parsed];
                    }
                } catch (error) {
                    // Fall back to CSV/plain text parsing below.
                }
                return raw
                    .split(/\r?\n/)
                    .map((line) => line.trim())
                    .filter(Boolean)
                    .map((line) => {
                        if (line.includes(',')) {
                            const [canonicalUserId, email] = line.split(',').map((item) => item.trim()).filter(Boolean);
                            if (canonicalUserId && email) {
                                return { canonical_user_id: canonicalUserId, email };
                            }
                        }
                        return { canonical_user_id: line };
                    });
            }

            function buildAudienceBuilderRequest() {
                const basis = getAudienceBuilderBasis();
                const request = {
                    name: String(document.getElementById('audience-name-input')?.value || '').trim(),
                    audience_basis: basis,
                    prediction_scope: getAudienceBuilderPredictionScope(),
                    source_names: getSelectedMultiSelectValues(audienceBuilderSourceSelect),
                    prediction_job_ids: getSelectedMultiSelectValues(audienceBuilderJobSelect),
                    output_mode: String(audienceBuilderOutputModeSelect?.value || 'combined').trim().toLowerCase() || 'combined',
                    refresh_mode: String(document.getElementById('audience-refresh-mode-select')?.value || 'manual').trim().toLowerCase() || 'manual',
                    owner: String(document.getElementById('audience-owner-input')?.value || 'frontend_operator').trim() || 'frontend_operator',
                    description: String(document.getElementById('audience-description-input')?.value || '').trim(),
                    tags: splitCsv(document.getElementById('audience-tags-input')?.value || ''),
                    logic: String(audienceBuilderLogicSelect?.value || 'AND').trim().toUpperCase() || 'AND',
                    conditions: audienceBuilderConditions
                        .filter((condition) => String(condition.field || '').trim())
                        .map((condition) => ({
                            field: condition.field,
                            op: condition.op,
                            value: condition.value,
                            value_type: condition.value_type || getAudienceBuilderFieldMeta(condition.field)?.value_type || 'string',
                        })),
                    members: basis === 'manual_list' ? parseAudienceBuilderMembersInput() : [],
                    sql: basis === 'managed_warehouse_sql' ? String(document.getElementById('sql-workspace-textarea')?.value || '').trim() : '',
                    saved_query_id: basis === 'managed_warehouse_sql' ? String(audienceBuilderSavedQuerySelect?.value || '').trim() : '',
                    connector_id: basis === 'connector_bigquery_table' ? String(audienceBuilderConnectorSelect?.value || '').trim() : '',
                    table_name: basis === 'connector_bigquery_table' ? String(audienceBuilderConnectorTableSelect?.value || '').trim() : '',
                    selected_columns: basis === 'connector_bigquery_table' ? splitCsv(audienceBuilderSelectedColumnsInput?.value || '') : [],
                    where_sql: basis === 'connector_bigquery_table' ? String(audienceBuilderWhereSqlInput?.value || '').trim() : '',
                    column_mapping: basis === 'connector_bigquery_table' ? getAudienceBuilderColumnMapping() : {},
                };
                if (basis !== 'prediction') {
                    request.output_mode = 'combined';
                }
                return request;
            }

            async function previewAudienceBuilder(requestOverride = null, { statusElement = audienceCreateStatus } = {}) {
                try {
                    setInlineStatus(statusElement, 'Previewing cohort...');
                    const payload = await apiRequest('/cohorts/builder/preview', {
                        method: 'POST',
                        body: requestOverride || buildAudienceBuilderRequest(),
                    });
                    audienceBuilderPreview = payload;
                    renderAudienceBuilderPreview(payload);
                    setInlineStatus(
                        statusElement,
                        payload.warnings?.length
                            ? payload.warnings.join(' ')
                            : `Preview ready with ${payload.member_count || 0} matching member(s).`,
                    );
                    return payload;
                } catch (error) {
                    resetAudienceBuilderPreview('Preview failed.');
                    setInlineStatus(statusElement, error.message || 'Failed to preview cohort.', true);
                    throw error;
                }
            }

            async function createAudienceBuilderCohort(requestOverride = null, { statusElement = audienceCreateStatus } = {}) {
                try {
                    setInlineStatus(statusElement, 'Validating and creating draft cohort...');
                    const preview = await previewAudienceBuilder(requestOverride, { statusElement });
                    const payload = await apiRequest('/cohorts/builder/create', {
                        method: 'POST',
                        body: preview.request || requestOverride || buildAudienceBuilderRequest(),
                    });
                    const createdItems = Array.isArray(payload.items) ? payload.items : [];
                    selectedAudienceCohortId = createdItems[0]?.cohort_id || selectedAudienceCohortId;
                    setInlineStatus(
                        statusElement,
                        createdItems.length > 1
                            ? `Created ${createdItems.length} draft cohorts from the guided builder.`
                            : `Created draft cohort ${createdItems[0]?.name || preview.request?.name || 'cohort'}.`,
                    );
                    await loadAudienceEngine();
                    if (selectedAudienceCohortId) {
                        await loadAudienceCohortDetails(selectedAudienceCohortId);
                    }
                    return payload;
                } catch (error) {
                    setInlineStatus(statusElement, error.message || 'Failed to create cohort.', true);
                    throw error;
                }
            }

            function applyAudienceBuilderState(builderState = {}, { preservePreview = true } = {}) {
                const preview = builderState.preview || null;
                const request = preview?.request || builderState.request || builderState || {};
                document.getElementById('audience-name-input').value = String(request.name || builderState.name || '').trim();
                document.getElementById('audience-owner-input').value = String(request.owner || 'frontend_operator').trim() || 'frontend_operator';
                document.getElementById('audience-description-input').value = String(request.description || '').trim();
                document.getElementById('audience-tags-input').value = Array.isArray(request.tags) ? request.tags.join(', ') : '';
                document.getElementById('audience-refresh-mode-select').value = String(request.refresh_mode || 'manual').trim().toLowerCase() || 'manual';
                if (audienceBuilderBasisSelect) {
                    audienceBuilderBasisSelect.value = String(request.audience_basis || 'prediction').trim().toLowerCase() || 'prediction';
                }
                if (audienceBuilderPredictionScopeSelect) {
                    audienceBuilderPredictionScopeSelect.value = String(request.prediction_scope || 'source').trim().toLowerCase() || 'source';
                }
                if (audienceBuilderOutputModeSelect) {
                    audienceBuilderOutputModeSelect.value = String(request.output_mode || 'combined').trim().toLowerCase() || 'combined';
                }
                if (audienceBuilderLogicSelect) {
                    audienceBuilderLogicSelect.value = String(request.logic || 'AND').trim().toUpperCase() || 'AND';
                }
                (request.source_names || []).forEach((value) => ensureSelectOption(audienceBuilderSourceSelect, value, value));
                (request.prediction_job_ids || []).forEach((value) => ensureSelectOption(audienceBuilderJobSelect, value, value));
                setSelectedMultiSelectValues(audienceBuilderSourceSelect, request.source_names || []);
                setSelectedMultiSelectValues(audienceBuilderJobSelect, request.prediction_job_ids || []);
                if (audienceBuilderMembersInput) {
                    const members = Array.isArray(request.members) ? request.members : [];
                    audienceBuilderMembersInput.value = members
                        .map((member) => {
                            if (!member || typeof member !== 'object') {
                                return String(member || '').trim();
                            }
                            const canonicalUserId = String(member.canonical_user_id || member.user_id || '').trim();
                            const email = String(member.email || '').trim();
                            return email && canonicalUserId ? `${canonicalUserId},${email}` : canonicalUserId || email;
                        })
                        .filter(Boolean)
                        .join('\n');
                }
                if (audienceBuilderSavedQuerySelect) {
                    ensureSelectOption(
                        audienceBuilderSavedQuerySelect,
                        String(request.saved_query_id || '').trim(),
                        String(
                            (cachedSavedQueries || []).find((item) => item.query_id === String(request.saved_query_id || '').trim())?.name
                            || request.saved_query_id
                            || 'Saved query'
                        ),
                    );
                    audienceBuilderSavedQuerySelect.value = String(request.saved_query_id || '').trim();
                }
                if (audienceBuilderConnectorSelect) {
                    ensureSelectOption(
                        audienceBuilderConnectorSelect,
                        String(request.connector_id || '').trim(),
                        String(
                            (audienceBuilderOptions?.warehouse_connectors || []).find((item) => item.connector_id === String(request.connector_id || '').trim())?.name
                            || request.connector_id
                            || 'Connector'
                        ),
                    );
                    audienceBuilderConnectorSelect.value = String(request.connector_id || '').trim();
                }
                if (audienceBuilderConnectorTableSelect) {
                    ensureSelectOption(
                        audienceBuilderConnectorTableSelect,
                        String(request.table_name || '').trim(),
                        String(request.table_name || '').trim(),
                    );
                    audienceBuilderConnectorTableSelect.value = String(request.table_name || '').trim();
                }
                if (audienceBuilderSelectedColumnsInput) {
                    audienceBuilderSelectedColumnsInput.value = Array.isArray(request.selected_columns) ? request.selected_columns.join(', ') : '';
                }
                if (audienceBuilderWhereSqlInput) {
                    audienceBuilderWhereSqlInput.value = String(request.where_sql || '').trim();
                }
                if (audienceBuilderCanonicalUserIdFieldInput) {
                    audienceBuilderCanonicalUserIdFieldInput.value = String((request.column_mapping || {}).canonical_user_id || '').trim();
                }
                if (audienceBuilderEmailFieldInput) {
                    audienceBuilderEmailFieldInput.value = String((request.column_mapping || {}).email || '').trim();
                }
                if (audienceBuilderExternalUserIdFieldInput) {
                    audienceBuilderExternalUserIdFieldInput.value = String((request.column_mapping || {}).external_user_id || '').trim();
                }
                document.getElementById('sql-workspace-textarea').value = String(request.sql || builderState.sql || '').trim()
                    || document.getElementById('sql-workspace-textarea').value;
                syncNoCodeSetupArtifacts(['sql-workspace-textarea']);
                audienceBuilderConditions = Array.isArray(request.conditions)
                    ? request.conditions.map((condition) => ({
                        id: `builder_condition_${Math.random().toString(16).slice(2, 8)}`,
                        field: condition.field,
                        op: condition.op,
                        value: Array.isArray(condition.value) ? condition.value.join(', ') : condition.value,
                        value_type: condition.value_type,
                    }))
                    : [];
                syncAudienceBuilderVisibility();
                renderAudienceBuilderFilters();
                renderAudienceBuilderSourceSummary();
                if (preservePreview && preview) {
                    audienceBuilderPreview = preview;
                    renderAudienceBuilderPreview(preview);
                } else {
                    resetAudienceBuilderPreview('Preview cleared.');
                }
            }

            async function requestAudienceBuilderDraft({ create = false } = {}) {
                const prompt = String(audienceBuilderAiPrompt?.value || '').trim();
                if (!prompt) {
                    setInlineStatus(audienceBuilderAiStatus, 'Enter a prompt for the audience builder assistant.', true);
                    return;
                }
                try {
                    setInlineStatus(audienceBuilderAiStatus, create ? 'Drafting builder and creating cohorts...' : 'Drafting guided audience builder...');
                    renderJsonOutput(audienceBuilderAiOutput, null, '');
                    await ensureCopilotAgentSession(false);
                    const payload = await apiRequest(`/copilot/agent/sessions/${encodeURIComponent(copilotAgentSessionId)}/messages`, {
                        method: 'POST',
                        body: {
                            message: `Draft a guided audience builder for this request: ${prompt}`,
                            ui_context: getCopilotAgentUiContext(),
                        },
                    });
                    const turnsPayload = await apiRequest(`/copilot/agent/sessions/${encodeURIComponent(copilotAgentSessionId)}/turns`);
                    renderCopilotAgentWorkspace(payload, turnsPayload.items || []);
                    const artifacts = Array.isArray(payload.artifacts)
                        ? payload.artifacts
                        : (payload.session_state?.latest_artifacts || []);
                    const builderArtifact = artifacts.find((item) => String(item.resource_type || '').trim() === 'audience_builder_state');
                    if (!builderArtifact) {
                        throw new Error('The AI assistant did not return a guided audience builder draft.');
                    }
                    const builderState = builderArtifact.focus?.builder_state || {};
                    applyAudienceBuilderState(builderState, { preservePreview: true });
                    renderJsonOutput(audienceBuilderAiOutput, builderState, '');
                    setInlineStatus(
                        audienceBuilderAiStatus,
                        `Drafted builder with ${builderState.preview?.member_count || 0} matching member(s).`,
                    );
                    if (create) {
                        await createAudienceBuilderCohort(builderState.preview?.request || builderState, { statusElement: audienceBuilderAiStatus });
                    }
                } catch (error) {
                    setInlineStatus(audienceBuilderAiStatus, error.message || 'Failed to draft the audience builder.', true);
                    renderJsonOutput(audienceBuilderAiOutput, { error: error.message || 'Failed to draft audience builder.' }, '');
                }
            }

            function renderAudienceCohortDetail(cohort) {
                if (!cohort) {
                    return '<div class="list-empty">Select a cohort from the table.</div>';
                }
                const definition = cohort.definition || {};
                const isGuided = String(definition.entrypoint || '').trim().toLowerCase() === 'guided_builder';
                const resolvedPredictions = (definition.provenance || {}).resolved_predictions || [];
                const sourceBreakdown = (definition.provenance || {}).source_breakdown || [];
                const conditions = Array.isArray(definition.conditions) ? definition.conditions : [];
                const description = String(cohort.description || '').trim();
                const sourceLabel = getCohortSourceLabel(cohort);
                const sourceSummary = cohort.source_summary || {};
                const sourceSummaryText = sourceSummary.saved_query_name
                    ? `${sourceSummary.saved_query_name}${sourceSummary.saved_query_id ? ` (${sourceSummary.saved_query_id})` : ''}`
                    : sourceSummary.connector_name
                        ? `${sourceSummary.connector_name}${sourceSummary.table_name ? ` · ${sourceSummary.table_name}` : ''}`
                        : '';
                return `
                    <div class="stats-grid">
                        <div class="stat-card"><div class="label">Status</div><div class="value">${escapeHtml(cohort.status || '-')}</div></div>
                        <div class="stat-card"><div class="label">Members</div><div class="value">${escapeHtml(String(cohort.member_count || 0))}</div></div>
                        <div class="stat-card"><div class="label">Refresh Mode</div><div class="value">${escapeHtml(cohort.refresh_mode || '-')}</div></div>
                        <div class="stat-card"><div class="label">Version</div><div class="value">${escapeHtml(String(cohort.version || cohort.version_id || 1))}</div></div>
                        ${sourceLabel ? `<div class="stat-card"><div class="label">Source</div><div class="value">${escapeHtml(sourceLabel)}</div></div>` : ''}
                    </div>
                    <div class="subtle">Last refreshed: ${escapeHtml(formatDateTime(cohort.last_refreshed_at))}</div>
                    ${description ? `<p>${escapeHtml(description)}</p>` : ''}
                    ${sourceSummaryText ? `<div class="subtle">Source summary: ${escapeHtml(sourceSummaryText)}</div>` : ''}
                    ${isGuided ? `
                        <div class="builder-preview-summary" style="margin-top: 1rem;">
                            <div class="builder-preview-stat">
                                <span>Audience Basis</span>
                                <strong>${escapeHtml(String(definition.audience_basis || cohort.type || '-').replace(/_/g, ' '))}</strong>
                            </div>
                            <div class="builder-preview-stat">
                                <span>Source Kind</span>
                                <strong>${escapeHtml(String(definition.source_kind || cohort.type || '-').replace(/_/g, ' '))}</strong>
                            </div>
                            <div class="builder-preview-stat">
                                <span>Split Strategy</span>
                                <strong>${escapeHtml(String(definition.split_strategy || 'combined').replace(/_/g, ' '))}</strong>
                            </div>
                            <div class="builder-preview-stat">
                                <span>Dedupe Key</span>
                                <strong>${escapeHtml(String(definition.dedupe_key || 'canonical_user_id'))}</strong>
                            </div>
                            <div class="builder-preview-stat" style="grid-column: 1 / -1;">
                                <span>Filters</span>
                                <div>${conditions.length ? conditions.map((item) => `<span class="pill">${escapeHtml(formatAudienceBuilderCondition(item))}</span>`).join('') : '<span class="subtle">None</span>'}</div>
                            </div>
                            <div class="builder-preview-stat" style="grid-column: 1 / -1;">
                                <span>Tags</span>
                                <div>${(cohort.tags || []).length ? cohort.tags.map((item) => `<span class="pill">${escapeHtml(item)}</span>`).join('') : '<span class="subtle">No tags.</span>'}</div>
                            </div>
                        </div>
                        <div class="builder-source-summary" style="margin-top: 1rem;">
                            ${resolvedPredictions.length ? resolvedPredictions.map((item) => `
                                <div class="builder-source-card">
                                    <div class="builder-source-head">
                                        <strong>${escapeHtml(item.source_name || item.prediction_job_id || 'Prediction')}</strong>
                                        <span class="pill">${escapeHtml(item.prediction_mode || 'completed')}</span>
                                    </div>
                                    <div class="subtle">${escapeHtml(item.prediction_job_id || '-')}</div>
                                    <div class="subtle">Completed ${escapeHtml(formatDateTime(item.completed_at))}</div>
                                </div>
                            `).join('') : '<div class="list-empty">No provenance.</div>'}
                        </div>
                        ${sourceBreakdown.length ? `
                            <div style="margin-top: 1rem;">
                                <strong>Per-source contribution</strong>
                                <div class="subtle">${sourceBreakdown.map((item) => `${item.source_name || item.prediction_job_id}: ${item.member_count || 0}`).join(' · ')}</div>
                            </div>
                        ` : ''}
                    ` : ''}
                    <details class="builder-advanced-panel" style="margin-top: 1rem;">
                        <summary>Advanced Definition</summary>
                        <pre id="audience-cohort-definition-output" class="json-output"></pre>
                    </details>
                `;
            }

            async function loadAudienceMembers(cohortId = selectedAudienceCohortId) {
                if (!cohortId) {
                    audienceMembersList.innerHTML = '<div class="list-empty">Select a cohort first.</div>';
                    return;
                }
                const payload = await apiRequest(`/cohorts/${encodeURIComponent(cohortId)}/members?page=1&page_size=50`);
                renderSimpleTable(
                    audienceMembersList,
                    [
                        { label: 'Canonical User ID', render: (item) => escapeHtml(String(item.canonical_user_id || item.user_id || '-')) },
                        { label: 'Email', render: (item) => escapeHtml(String(item.email || '-')) },
                        { label: 'Attributes', render: (item) => `<span class="subtle">${escapeHtml(JSON.stringify(item))}</span>` },
                    ],
                    payload.items || [],
                    'No members in the latest snapshot.',
                );
            }

            async function loadAudienceVersions(cohortId = selectedAudienceCohortId) {
                if (!cohortId) {
                    audienceVersionsList.innerHTML = '<div class="list-empty">Select a cohort first.</div>';
                    return;
                }
                const payload = await apiRequest(`/cohorts/${encodeURIComponent(cohortId)}/versions`);
                renderSimpleTable(
                    audienceVersionsList,
                    [
                        { label: 'Version', render: (item) => escapeHtml(String(item.version || '-')) },
                        { label: 'Created', render: (item) => escapeHtml(formatDateTime(item.created_at)) },
                        { label: 'Status', render: (item) => `<span class="pill">${escapeHtml(String((item.payload || {}).status || '-'))}</span>` },
                    ],
                    payload.items || [],
                    'No saved versions yet.',
                );
            }

            async function loadAudienceMetrics(cohortId = selectedAudienceCohortId) {
                if (!cohortId) {
                    renderJsonOutput(audienceMetricsOutput, null, 'Select a cohort first.');
                    return;
                }
                const payload = await apiRequest(`/cohorts/${encodeURIComponent(cohortId)}/metrics`);
                renderJsonOutput(audienceMetricsOutput, payload, 'No metrics available.');
            }

            async function loadAudienceCohortDetails(cohortId) {
                selectedAudienceCohortId = cohortId;
                audienceSelectedCohortLabel.textContent = cohortId || 'No cohort selected';
                if (!cohortId) {
                    audienceCohortDetail.innerHTML = renderAudienceCohortDetail(null);
                    audienceMembersList.innerHTML = '';
                    audienceVersionsList.innerHTML = '';
                    renderJsonOutput(audienceMetricsOutput, null, '');
                    renderJsonOutput(audienceCompareOutput, null, '');
                    return;
                }
                const cohort = await apiRequest(`/cohorts/${encodeURIComponent(cohortId)}`);
                document.getElementById('audience-base-version-input').value = cohort.version || 1;
                document.getElementById('audience-target-version-input').value = cohort.version || 1;
                audienceCohortDetail.innerHTML = renderAudienceCohortDetail(cohort);
                renderJsonOutput(
                    document.getElementById('audience-cohort-definition-output'),
                    {
                        definition: cohort.definition,
                        delta: cohort.delta,
                        activation_preflight: cohort.activation_preflight,
                        metrics_summary: cohort.metrics_summary,
                    },
                    '',
                );
                await Promise.all([loadAudienceMetrics(cohortId), loadAudienceMembers(cohortId), loadAudienceVersions(cohortId)]);
            }

            function renderSavedQueries(items = []) {
                cachedSavedQueries = Array.isArray(items) ? items : [];
                populateAudienceBuilderSavedQuerySelect({ preserveSelection: true });
                renderSimpleTable(
                    sqlSavedQueryList,
                    [
                        { label: 'Name', render: (item) => escapeHtml(item.name || '-') },
                        { label: 'Description', render: (item) => `<span class="subtle">${escapeHtml(item.description || '-')}</span>` },
                        { label: 'Updated', render: (item) => escapeHtml(formatDateTime(item.updated_at)) },
                        {
                            label: 'Actions',
                            render: (item) => `
                                <div class="table-actions">
                                    <button type="button" data-sql-action="preview" data-query-id="${escapeHtml(item.query_id)}">Preview</button>
                                    <button type="button" data-sql-action="cohort" data-query-id="${escapeHtml(item.query_id)}">To Cohort</button>
                                </div>
                            `,
                        },
                    ],
                    cachedSavedQueries,
                    'No saved SQL queries yet.',
                );
                sqlSavedQueryList.querySelectorAll('[data-sql-action]').forEach((button) => {
                    button.addEventListener('click', async () => {
                        const query = cachedSavedQueries.find((item) => item.query_id === button.dataset.queryId);
                        if (!query) return;
                        if (button.dataset.sqlAction === 'preview') {
                            document.getElementById('sql-workspace-textarea').value = query.sql || '';
                            syncNoCodeSetupArtifacts(['sql-workspace-textarea']);
                            await previewSqlWorkspace();
                            return;
                        }
                        if (button.dataset.sqlAction === 'cohort') {
                            await createCohortFromSavedQuery(query.query_id);
                        }
                    });
                });
            }

            async function previewSqlWorkspace() {
                try {
                    setInlineStatus(sqlWorkspaceStatus, 'Previewing query...');
                    const payload = await apiRequest('/sql-workspace/preview', {
                        method: 'POST',
                        body: {
                            sql: document.getElementById('sql-workspace-textarea').value,
                            limit: Number(document.getElementById('sql-preview-limit').value || 20),
                            timeout_seconds: Number(document.getElementById('sql-timeout-seconds').value || 30),
                        },
                    });
                    renderJsonOutput(sqlPreviewOutput, payload, 'Preview returned no rows.');
                    setInlineStatus(sqlWorkspaceStatus, `Preview returned ${payload.row_count || 0} row(s).`);
                } catch (error) {
                    setInlineStatus(sqlWorkspaceStatus, error.message || 'SQL preview failed.', true);
                    renderJsonOutput(sqlPreviewOutput, null, 'SQL preview failed.');
                }
            }

            async function saveSqlWorkspaceQuery() {
                try {
                    setInlineStatus(sqlWorkspaceStatus, 'Saving query...');
                    await apiRequest('/sql-workspace/queries', {
                        method: 'POST',
                        body: {
                            name: document.getElementById('sql-saved-query-name').value || 'Untitled query',
                            description: document.getElementById('sql-saved-query-description').value || '',
                            sql: document.getElementById('sql-workspace-textarea').value,
                        },
                    });
                    setInlineStatus(sqlWorkspaceStatus, 'Saved query.');
                    await loadAudienceEngine();
                } catch (error) {
                    setInlineStatus(sqlWorkspaceStatus, error.message || 'Failed to save query.', true);
                }
            }

            async function createCohortFromSavedQuery(queryId) {
                try {
                    setInlineStatus(sqlWorkspaceStatus, 'Creating draft cohort from saved query...');
                    const name = document.getElementById('audience-name-input').value.trim()
                        || document.getElementById('sql-saved-query-name').value.trim()
                        || `cohort_${Date.now()}`;
                    await apiRequest(`/sql-workspace/queries/${encodeURIComponent(queryId)}/cohort`, {
                        method: 'POST',
                        body: {
                            name,
                            refresh_mode: document.getElementById('audience-refresh-mode-select').value || 'manual',
                            owner: document.getElementById('audience-owner-input').value || 'frontend_operator',
                            activate: false,
                        },
                    });
                    setInlineStatus(sqlWorkspaceStatus, 'Saved query converted to a draft cohort.');
                    await loadAudienceEngine();
                } catch (error) {
                    setInlineStatus(sqlWorkspaceStatus, error.message || 'Failed to create cohort from query.', true);
                }
            }

            function renderAudienceCohorts(items = []) {
                renderSimpleTable(
                    audienceCohortList,
                    [
                        {
                            label: 'Name',
                            render: (item) => `
                                <strong>${escapeHtml(item.name || '-')}</strong>
                                <div class="subtle">${escapeHtml(item.cohort_id || '-')}</div>
                                ${getCohortSourceLabel(item) ? `<div><span class="pill">${escapeHtml(getCohortSourceLabel(item))}</span></div>` : ''}
                            `,
                        },
                        { label: 'Type', render: (item) => `<span class="pill">${escapeHtml(item.type || '-')}</span>` },
                        { label: 'Status', render: (item) => `<span class="pill">${escapeHtml(item.status || '-')}</span>` },
                        { label: 'Members', render: (item) => escapeHtml(String(item.member_count || 0)) },
                        { label: 'Last Refreshed', render: (item) => escapeHtml(formatDateTime(item.last_refreshed_at)) },
                        {
                            label: 'Actions',
                            render: (item) => `
                                <div class="table-actions">
                                    <button type="button" data-cohort-action="view" data-cohort-id="${escapeHtml(item.cohort_id)}">View</button>
                                    <button type="button" data-cohort-action="refresh" data-cohort-id="${escapeHtml(item.cohort_id)}">Refresh</button>
                                    <button type="button" data-cohort-action="activate" data-cohort-id="${escapeHtml(item.cohort_id)}">Activate</button>
                                    <button type="button" data-cohort-action="pause" data-cohort-id="${escapeHtml(item.cohort_id)}">Pause</button>
                                    <button type="button" data-cohort-action="archive" data-cohort-id="${escapeHtml(item.cohort_id)}">Archive</button>
                                    <button type="button" data-cohort-action="restore" data-cohort-id="${escapeHtml(item.cohort_id)}">Restore</button>
                                </div>
                            `,
                        },
                    ],
                    items,
                    'No cohorts yet.',
                );

                audienceCohortList.querySelectorAll('[data-cohort-action]').forEach((button) => {
                    button.addEventListener('click', async () => {
                        const cohortId = button.dataset.cohortId;
                        const action = button.dataset.cohortAction;
                        try {
                            if (action === 'view') {
                                await loadAudienceCohortDetails(cohortId);
                                return;
                            }
                            if (action === 'refresh') {
                                await apiRequest(`/cohorts/${encodeURIComponent(cohortId)}/refresh`, { method: 'POST' });
                            }
                            if (action === 'activate') {
                                await apiRequest(`/cohorts/${encodeURIComponent(cohortId)}/activate`, { method: 'POST' });
                            }
                            if (action === 'pause') {
                                await apiRequest(`/cohorts/${encodeURIComponent(cohortId)}/pause`, { method: 'POST' });
                            }
                            if (action === 'archive') {
                                await apiRequest(`/cohorts/${encodeURIComponent(cohortId)}/archive`, { method: 'POST' });
                            }
                            if (action === 'restore') {
                                await apiRequest(`/cohorts/${encodeURIComponent(cohortId)}/restore`, { method: 'POST' });
                            }
                            await loadAudienceEngine();
                            await loadAudienceCohortDetails(cohortId);
                        } catch (error) {
                            setInlineStatus(audienceCreateStatus, error.message || `Failed to ${action} cohort.`, true);
                        }
                    });
                });
            }

            async function loadAudienceEngine() {
                try {
                    const [cohortPayload, savedQueryPayload] = await Promise.all([
                        refreshCohortsState().then((items) => ({ items })),
                        apiRequest('/sql-workspace/queries'),
                    ]);
                    await loadAudienceBuilderOptions({ preserveSelection: true });
                    const cohorts = Array.isArray(cohortPayload.items) ? cohortPayload.items : [];
                    renderAudienceCohorts(cohorts);
                    renderSavedQueries(savedQueryPayload.items || []);
                    populateWorkflowCohortSelect(cohorts);
                    if (selectedAudienceCohortId && cohorts.some((item) => item.cohort_id === selectedAudienceCohortId)) {
                        await loadAudienceCohortDetails(selectedAudienceCohortId);
                    } else if (!selectedAudienceCohortId && cohorts[0]) {
                        await loadAudienceCohortDetails(cohorts[0].cohort_id);
                    } else if (!cohorts.length) {
                        await loadAudienceCohortDetails(null);
                    }
                } catch (error) {
                    if (isWorkspaceContextError(error)) {
                        setInlineStatus(audienceCreateStatus, getWorkspaceResolutionMessage(error.payload || authSessionState));
                        renderAudienceCohorts([]);
                        renderSavedQueries([]);
                        await loadAudienceCohortDetails(null);
                        return;
                    }
                    setInlineStatus(audienceCreateStatus, error.message || 'Failed to load audience engine.', true);
                }
            }

            async function createAudienceCohort() {
                await createAudienceBuilderCohort();
            }

            async function compareAudienceVersions() {
                if (!selectedAudienceCohortId) {
                    renderJsonOutput(audienceCompareOutput, null, 'Select a cohort first.');
                    return;
                }
                try {
                    const baseVersion = Number(document.getElementById('audience-base-version-input').value || 1);
                    const targetVersion = Number(document.getElementById('audience-target-version-input').value || 1);
                    const payload = await apiRequest(`/cohorts/${encodeURIComponent(selectedAudienceCohortId)}/compare?base_version=${baseVersion}&target_version=${targetVersion}`);
                    renderJsonOutput(audienceCompareOutput, payload, 'No version comparison available.');
                } catch (error) {
                    renderJsonOutput(audienceCompareOutput, { error: error.message }, 'Comparison failed.');
                }
            }

            async function rollbackAudienceVersion() {
                if (!selectedAudienceCohortId) {
                    setInlineStatus(audienceCreateStatus, 'Select a cohort first.', true);
                    return;
                }
                try {
                    const version = Number(document.getElementById('audience-base-version-input').value || 1);
                    await apiRequest(`/cohorts/${encodeURIComponent(selectedAudienceCohortId)}/rollback?version=${version}`, { method: 'POST' });
                    setInlineStatus(audienceCreateStatus, `Rolled back cohort to version ${version}.`);
                    await loadAudienceEngine();
                    await loadAudienceCohortDetails(selectedAudienceCohortId);
                } catch (error) {
                    setInlineStatus(audienceCreateStatus, error.message || 'Failed to rollback cohort.', true);
                }
            }

            function getWorkflowStudioItems() {
                const emailItems = (cachedEmailCampaigns || []).map((item) => ({
                    studio_type: 'email_campaign',
                    studio_id: item.email_campaign_id,
                    name: item.name || item.email_campaign_id,
                    provider: item.provider || (findProviderConnection(item.provider_connection_id) || {}).provider || 'sendgrid',
                    status: item.status || 'draft',
                    last_run_at: item.last_send_completed_at || item.last_send_started_at || null,
                    next_run_at: ['draft', 'scheduled'].includes(String(item.status || '').toLowerCase()) ? item.schedule_at : null,
                    last_results: item.result_summary || {},
                    total_results: item.result_summary || {},
                    resource: item,
                }));
                const workflowItems = (cachedWorkflows || []).map((item) => ({
                    studio_type: 'workflow',
                    studio_id: item.workflow_id,
                    name: item.name || item.workflow_id,
                    provider: (item.channel_config || {}).provider || (findProviderConnection((item.channel_config || {}).provider_connection_id) || {}).provider || ((item.channel_config || {}).channel || 'workflow'),
                    status: item.status || 'draft',
                    last_run_at: (item.runtime_summary || {}).last_run_at || null,
                    next_run_at: (item.runtime_summary || {}).next_run_at || null,
                    last_results: (item.runtime_summary || {}).last_result || {},
                    total_results: (item.runtime_summary || {}).totals || {},
                    resource: item,
                }));
                const pushDispatchItems = (cachedPushDispatches || []).map((item) => ({
                    studio_type: 'push_dispatch',
                    studio_id: item.push_dispatch_id,
                    name: item.name || item.campaign_name || item.push_dispatch_id,
                    provider: item.provider || (findProviderConnection(item.provider_connection_id) || {}).provider || 'push_notification',
                    status: item.status || 'sent',
                    last_run_at: item.last_send_completed_at || item.last_send_started_at || item.updated_at || item.created_at || null,
                    next_run_at: null,
                    last_results: item.result_summary || {},
                    total_results: item.result_summary || {},
                    resource: item,
                }));
                return [...emailItems, ...workflowItems, ...pushDispatchItems].sort((left, right) => {
                    const leftTime = parseIsoDate(left.last_run_at || left.next_run_at || left.resource.updated_at || left.resource.created_at).getTime();
                    const rightTime = parseIsoDate(right.last_run_at || right.next_run_at || right.resource.updated_at || right.resource.created_at).getTime();
                    return rightTime - leftTime;
                });
            }

            function getFilteredWorkflowStudioItems() {
                const filter = String(selectedWorkflowStudioType || 'all').trim().toLowerCase() || 'all';
                const items = getWorkflowStudioItems();
                if (filter === 'scheduled') {
                    return items.filter((item) => ['scheduled', 'published'].includes(String(item.status || '').toLowerCase()));
                }
                if (filter === 'sent') {
                    return items.filter((item) => {
                        const status = String(item.status || '').toLowerCase();
                        if (item.studio_type === 'email_campaign') {
                            return ['sent', 'sent_with_errors', 'failed', 'cancelled'].includes(status);
                        }
                        if (item.studio_type === 'push_dispatch') {
                            return ['sent', 'failed'].includes(status);
                        }
                        return ['sent', 'sent_with_errors', 'failed'].includes(status);
                    });
                }
                if (filter === 'archived') {
                    return items.filter((item) => String(item.status || '').toLowerCase() === 'archived');
                }
                return items;
            }

            function syncWorkflowStudioFilterButtons() {
                document.querySelectorAll('[data-workflow-studio-filter]').forEach((button) => {
                    const active = String(button.dataset.workflowStudioFilter || '').trim().toLowerCase() === selectedWorkflowStudioType;
                    button.classList.toggle('active', active);
                    button.setAttribute('aria-pressed', active ? 'true' : 'false');
                });
            }

            function formatWorkflowStudioChannel(item) {
                if (item.studio_type === 'email_campaign') {
                    return 'Email';
                }
                const channel = String(((item.resource || {}).channel_config || {}).channel || '').trim().toLowerCase();
                if (channel === 'email') {
                    return 'Email';
                }
                return 'Push';
            }

            function formatWorkflowStudioLastResults(item) {
                if (item.studio_type === 'email_campaign') {
                    const summary = item.last_results || {};
                    return `sent ${summary.sent_count || 0} · failed ${summary.failed_count || 0}`;
                }
                if (item.studio_type === 'push_dispatch') {
                    const resource = item.resource || {};
                    return `accepted ${resource.provider_accepted ? 1 : 0} · attempts ${resource.send_attempts || 0}`;
                }
                const summary = item.last_results || {};
                return `ok ${summary.success || 0} · fail ${summary.failures || 0}`;
            }

            function formatWorkflowStudioTotalResults(item) {
                if (item.studio_type === 'email_campaign') {
                    const summary = item.total_results || {};
                    return `sent ${summary.sent_count || 0}`;
                }
                if (item.studio_type === 'push_dispatch') {
                    const resource = item.resource || {};
                    return `callbacks ${resource.callback_count || 0} · attempts ${resource.send_attempts || 0}`;
                }
                const totals = item.total_results || {};
                return `runs ${totals.runs || 0} · success ${totals.success || 0}`;
            }

            function renderWorkflowStudioActionButton(item, action, label) {
                return `<button type="button" data-workflow-studio-action="${escapeHtml(action)}" data-workflow-studio-type="${escapeHtml(item.studio_type)}" data-workflow-studio-id="${escapeHtml(item.studio_id)}">${escapeHtml(label)}</button>`;
            }

            function renderWorkflowStudioActions(item) {
                const status = String(item.status || '').toLowerCase();
                const visibleButtons = [renderWorkflowStudioActionButton(item, 'view', 'View')];
                if (item.studio_type !== 'push_dispatch') {
                    visibleButtons.push(renderWorkflowStudioActionButton(item, 'edit', 'Edit'));
                }
                if (item.studio_type === 'email_campaign') {
                    const moreButtons = [
                        status !== 'scheduled' ? renderWorkflowStudioActionButton(item, 'schedule', 'Schedule') : '',
                        ['draft', 'scheduled'].includes(status) ? renderWorkflowStudioActionButton(item, 'send-now', 'Send Now') : '',
                        status === 'scheduled'
                            ? renderWorkflowStudioActionButton(item, 'cancel', 'Cancel')
                            : status === 'draft'
                                ? renderWorkflowStudioActionButton(item, 'delete', 'Delete')
                                : '',
                    ];
                    return `
                        <div class="table-actions">
                            ${visibleButtons.join('')}
                            ${renderTableActionMenu(moreButtons)}
                        </div>
                    `;
                }
                if (item.studio_type === 'push_dispatch') {
                    const moreButtons = [
                        status !== 'archived' ? renderWorkflowStudioActionButton(item, 'archive', 'Archive') : '',
                    ];
                    return `
                        <div class="table-actions">
                            ${visibleButtons.join('')}
                            ${renderTableActionMenu(moreButtons)}
                        </div>
                    `;
                }
                const moreButtons = [
                    status === 'draft' ? renderWorkflowStudioActionButton(item, 'publish', 'Publish') : '',
                    status === 'published' ? renderWorkflowStudioActionButton(item, 'pause', 'Pause') : '',
                    status === 'paused' ? renderWorkflowStudioActionButton(item, 'resume', 'Resume') : '',
                    ['draft', 'published', 'paused'].includes(status) ? renderWorkflowStudioActionButton(item, 'test-run', 'Test Run') : '',
                    status === 'draft'
                        ? renderWorkflowStudioActionButton(item, 'delete', 'Delete')
                        : ['sent', 'sent_with_errors', 'failed'].includes(status)
                            ? renderWorkflowStudioActionButton(item, 'archive', 'Archive')
                            : '',
                ];
                return `
                    <div class="table-actions">
                        ${visibleButtons.join('')}
                        ${renderTableActionMenu(moreButtons)}
                    </div>
                `;
            }

            function syncWorkflowStudioPaginationSummary(totalItems, startIndex, endIndex) {
                if (!workflowStudioPaginationSummary) return;
                if (totalItems <= 0) {
                    workflowStudioPaginationSummary.textContent = 'Showing 0 items';
                    return;
                }
                workflowStudioPaginationSummary.textContent = `Showing ${startIndex}-${endIndex} of ${totalItems}`;
            }

            function renderWorkflowStudioPaginationControls(totalItems) {
                if (!workflowStudioPaginationControls) return;
                workflowStudioPaginationControls.innerHTML = '';
                const totalPages = Math.ceil(totalItems / workflowStudioItemsPerPage);
                if (totalPages <= 1) {
                    return;
                }

                const prevButton = document.createElement('button');
                prevButton.type = 'button';
                prevButton.textContent = 'Previous';
                prevButton.disabled = workflowStudioCurrentPage === 1;
                prevButton.addEventListener('click', () => {
                    if (workflowStudioCurrentPage > 1) {
                        workflowStudioCurrentPage -= 1;
                        renderWorkflowStudioList();
                    }
                });

                const pageInfo = document.createElement('span');
                pageInfo.textContent = `Page ${workflowStudioCurrentPage} of ${totalPages}`;

                const nextButton = document.createElement('button');
                nextButton.type = 'button';
                nextButton.textContent = 'Next';
                nextButton.disabled = workflowStudioCurrentPage === totalPages;
                nextButton.addEventListener('click', () => {
                    if (workflowStudioCurrentPage < totalPages) {
                        workflowStudioCurrentPage += 1;
                        renderWorkflowStudioList();
                    }
                });

                workflowStudioPaginationControls.appendChild(prevButton);
                workflowStudioPaginationControls.appendChild(pageInfo);
                workflowStudioPaginationControls.appendChild(nextButton);
            }

            function renderWorkflowStudioList() {
                const items = getFilteredWorkflowStudioItems();
                const totalItems = items.length;
                const totalPages = Math.max(1, Math.ceil(totalItems / workflowStudioItemsPerPage));
                workflowStudioCurrentPage = Math.min(workflowStudioCurrentPage, totalPages);
                const startIndex = totalItems > 0 ? ((workflowStudioCurrentPage - 1) * workflowStudioItemsPerPage) + 1 : 0;
                const endIndex = totalItems > 0 ? Math.min(startIndex + workflowStudioItemsPerPage - 1, totalItems) : 0;
                const paginatedItems = items.slice(startIndex > 0 ? startIndex - 1 : 0, endIndex);
                syncWorkflowStudioFilterButtons();
                renderSimpleTable(
                    workflowStudioList,
                    [
                        { label: 'Name', render: (item) => `<strong>${escapeHtml(item.name || '-')}</strong><div class="subtle">${escapeHtml(item.studio_id || '-')}</div>` },
                        { label: 'Channel', render: (item) => `<span class="pill">${escapeHtml(formatWorkflowStudioChannel(item))}</span>` },
                        { label: 'Provider', render: (item) => `<span class="pill">${escapeHtml(formatConnectorLabel(item.provider || '-'))}</span>` },
                        { label: 'Status', render: (item) => `<span class="pill">${escapeHtml(String(item.status || '-').replace(/[_-]+/g, ' '))}</span>` },
                        { label: 'Last Run', render: (item) => escapeHtml(formatDateTime(item.last_run_at)) },
                        { label: 'Next Run', render: (item) => escapeHtml(formatDateTime(item.next_run_at)) },
                        { label: 'Last Results', render: (item) => escapeHtml(formatWorkflowStudioLastResults(item)) },
                        { label: 'Total Results', render: (item) => escapeHtml(formatWorkflowStudioTotalResults(item)) },
                        { label: 'Actions', render: (item) => renderWorkflowStudioActions(item) },
                    ],
                    paginatedItems,
                    selectedWorkflowStudioType === 'sent'
                        ? 'No sent email or push items yet.'
                        : selectedWorkflowStudioType === 'archived'
                            ? 'No archived email or push items yet.'
                            : selectedWorkflowStudioType === 'all'
                                ? 'No email or push items yet.'
                                : 'No scheduled email or push items yet.',
                );
                syncWorkflowStudioPaginationSummary(totalItems, startIndex, endIndex);
                renderWorkflowStudioPaginationControls(totalItems);
                bindWorkflowStudioActionButtons(workflowStudioList);
            }

            function renderWorkflowStudioDetailActions(resourceType, resource) {
                if (!workflowStudioActions) return;
                if (!resourceType || !resource) {
                    workflowStudioActions.innerHTML = '';
                    if (workflowStudioEmailScheduleGroup) {
                        workflowStudioEmailScheduleGroup.style.display = 'none';
                    }
                    return;
                }
                if (workflowStudioEmailScheduleGroup) {
                    workflowStudioEmailScheduleGroup.style.display = resourceType === 'email_campaign' ? 'block' : 'none';
                }
                if (resourceType === 'email_campaign' && workflowStudioEmailScheduleInput) {
                    workflowStudioEmailScheduleInput.value = fromIsoToLocalDateTimeInput(resource.schedule_at);
                }
                workflowStudioActions.innerHTML = renderWorkflowStudioActions({
                    studio_type: resourceType,
                    studio_id: resourceType === 'workflow'
                        ? resource.workflow_id
                        : resourceType === 'push_dispatch'
                            ? resource.push_dispatch_id
                            : resource.email_campaign_id,
                    status: resource.status,
                    resource,
                });
                bindWorkflowStudioActionButtons(workflowStudioActions);
            }

            async function loadWorkflowStudioSelection(resourceType, resourceId) {
                selectedWorkflowStudioResourceType = resourceType || null;
                selectedWorkflowStudioResourceId = resourceId || null;
                if (!resourceType || !resourceId) {
                    if (workflowStudioSelectedLabel) {
                        workflowStudioSelectedLabel.textContent = 'No item selected';
                    }
                    renderJsonOutput(workflowStudioDetailOutput, null, '');
                    renderWorkflowStudioDetailActions(null, null);
                    await loadWorkflowDetail(null);
                    return;
                }
                if (resourceType === 'workflow') {
                    const workflow = await apiRequest(`/workflows/${encodeURIComponent(resourceId)}`);
                    if (workflowStudioSelectedLabel) {
                        workflowStudioSelectedLabel.textContent = `${workflow.name || workflow.workflow_id} · ${String(workflow.status || 'draft').replace(/[_-]+/g, ' ')}`;
                    }
                    renderJsonOutput(workflowStudioDetailOutput, workflow, '');
                    renderWorkflowStudioDetailActions('workflow', workflow);
                    await loadWorkflowDetail(resourceId);
                    return;
                }
                if (resourceType === 'push_dispatch') {
                    const dispatch = findPushDispatch(resourceId) || await apiRequest(`/push-dispatches/${encodeURIComponent(resourceId)}`);
                    if (workflowStudioSelectedLabel) {
                        workflowStudioSelectedLabel.textContent = `${dispatch.name || dispatch.push_dispatch_id} · ${String(dispatch.status || 'sent').replace(/[_-]+/g, ' ')}`;
                    }
                    renderJsonOutput(workflowStudioDetailOutput, dispatch, '');
                    renderWorkflowStudioDetailActions('push_dispatch', dispatch);
                    await loadWorkflowDetail(null);
                    return;
                }
                const campaign = await apiRequest(`/email-campaigns/${encodeURIComponent(resourceId)}`);
                if (workflowStudioSelectedLabel) {
                    workflowStudioSelectedLabel.textContent = `${campaign.name || campaign.email_campaign_id} · ${formatEmailCampaignStatusLabel(campaign.status)}`;
                }
                renderJsonOutput(workflowStudioDetailOutput, campaign, '');
                renderWorkflowStudioDetailActions('email_campaign', campaign);
                await loadWorkflowDetail(null);
            }

            async function handleWorkflowStudioAction(resourceType, resourceId, action) {
                if (!resourceType || !resourceId || !action) return;
                if (action === 'view') {
                    await loadWorkflowStudioSelection(resourceType, resourceId);
                    return;
                }
                if (resourceType === 'push_dispatch') {
                    if (action === 'archive') {
                        await apiRequest(`/push-dispatches/${encodeURIComponent(resourceId)}/archive`, { method: 'POST' });
                        await loadActionOrchestrator();
                        await loadWorkflowStudioSelection('push_dispatch', resourceId);
                    }
                    return;
                }
                if (resourceType === 'workflow') {
                    if (action === 'edit') {
                        const workflow = findWorkflow(resourceId) || await apiRequest(`/workflows/${encodeURIComponent(resourceId)}`);
                        const workflowAudienceMode = String(workflow.audience_mode || workflow.definition?.audience_mode || '').trim().toLowerCase();
                        const workflowChannel = String(
                            workflow.channel_config?.channel
                            || workflow.definition?.channel_config?.channel
                            || workflow.definition?.action?.channel
                            || ''
                        ).trim().toLowerCase();
                        if (workflowChannel === 'push_notification' || workflowAudienceMode === 'provider_campaign') {
                            loadWorkflowIntoPushComposer(workflow);
                        } else {
                            loadWorkflowIntoBuilder(workflow);
                        }
                        activateModule('action-orchestrator', 'action-orchestrator-push', {
                            targetId: 'push-notifications-section',
                            closeSidebar: true,
                            scrollBehavior: 'smooth',
                        });
                        return;
                    }
                    if (action === 'publish') {
                        await apiRequest(`/workflows/${encodeURIComponent(resourceId)}/publish`, { method: 'POST' });
                    }
                    if (action === 'pause') {
                        await apiRequest(`/workflows/${encodeURIComponent(resourceId)}/pause`, { method: 'POST' });
                    }
                    if (action === 'resume') {
                        await apiRequest(`/workflows/${encodeURIComponent(resourceId)}/resume`, { method: 'POST' });
                    }
                    if (action === 'archive') {
                        await apiRequest(`/workflows/${encodeURIComponent(resourceId)}/archive`, { method: 'POST' });
                    }
                    if (action === 'delete') {
                        await apiRequest(`/workflows/${encodeURIComponent(resourceId)}`, { method: 'DELETE' });
                        if (selectedWorkflowBuilderId === resourceId) {
                            resetWorkflowBuilderForm();
                        }
                    }
                    if (action === 'test-run') {
                        const payload = await apiRequest(`/workflows/${encodeURIComponent(resourceId)}/test-run`, {
                            method: 'POST',
                            body: { limit: 10, confirm: true, sandbox: true, reference_time: getCurrentWorkflowReferenceTime() },
                        });
                        renderJsonOutput(orchestratorRunOutput, payload, 'No workflow run output.');
                        setInlineStatus(orchestratorRunStatus, `Workflow ${resourceId} test-run completed.`);
                    }
                    await loadActionOrchestrator();
                    if (action === 'delete') {
                        await loadWorkflowStudioSelection(null, null);
                    } else {
                        await loadWorkflowStudioSelection('workflow', resourceId);
                    }
                    return;
                }
                if (action === 'edit') {
                    await loadEmailCampaignDetail(resourceId);
                    activateModule('action-orchestrator', 'action-orchestrator-email-campaigns', {
                        targetId: 'email-campaigns-section',
                        closeSidebar: true,
                        scrollBehavior: 'smooth',
                    });
                    return;
                }
                if (action === 'schedule') {
                    if (selectedWorkflowStudioResourceType !== 'email_campaign' || selectedWorkflowStudioResourceId !== resourceId) {
                        await loadWorkflowStudioSelection('email_campaign', resourceId);
                    }
                    const scheduleAt = toIsoFromLocalDateTimeInput(workflowStudioEmailScheduleInput?.value || '');
                    if (!scheduleAt) {
                        throw new Error('Choose a schedule time in Workflow Studio before scheduling the campaign.');
                    }
                    await apiRequest(`/email-campaigns/${encodeURIComponent(resourceId)}`, {
                        method: 'PATCH',
                        body: { schedule_at: scheduleAt },
                    });
                }
                if (action === 'send-now') {
                    await apiRequest(`/email-campaigns/${encodeURIComponent(resourceId)}/send-now`, { method: 'POST' });
                }
                if (action === 'cancel') {
                    await apiRequest(`/email-campaigns/${encodeURIComponent(resourceId)}/cancel`, { method: 'POST' });
                }
                if (action === 'delete') {
                    await apiRequest(`/email-campaigns/${encodeURIComponent(resourceId)}`, { method: 'DELETE' });
                    if (selectedEmailCampaignId === resourceId) {
                        resetEmailCampaignForm();
                    }
                }
                await loadActionOrchestrator();
                if (action === 'delete') {
                    await loadWorkflowStudioSelection(null, null);
                } else {
                    await loadWorkflowStudioSelection('email_campaign', resourceId);
                }
            }

            function bindWorkflowStudioActionButtons(container) {
                if (!container) return;
                container.querySelectorAll('[data-workflow-studio-action]').forEach((button) => {
                    button.addEventListener('click', async () => {
                        try {
                            await handleWorkflowStudioAction(
                                button.dataset.workflowStudioType,
                                button.dataset.workflowStudioId,
                                button.dataset.workflowStudioAction,
                            );
                            setInlineStatus(workflowStudioStatus, '');
                        } catch (error) {
                            setInlineStatus(workflowStudioStatus, error.message || 'Failed to update Workflow Studio item.', true);
                        }
                    });
                });
            }

            async function loadWorkflowDetail(workflowId) {
                selectedWorkflowId = workflowId;
                workflowSelectedLabel.textContent = workflowId || 'No workflow selected';
                if (!workflowId) {
                    workflowExecutionsList.innerHTML = '<div class="list-empty">Select a workflow first.</div>';
                    workflowDeliveriesList.innerHTML = '<div class="list-empty">Select a workflow first.</div>';
                    renderJsonOutput(workflowPolicyOutput, null, '');
                    renderJsonOutput(workflowDeliveryDiagnosticsOutput, null, '');
                    return;
                }
                const [executionsPayload, deliveriesPayload, policyPayload, diagnosticsPayload] = await Promise.all([
                    apiRequest(`/workflows/${encodeURIComponent(workflowId)}/executions`),
                    apiRequest(`/workflows/${encodeURIComponent(workflowId)}/deliveries`),
                    apiRequest(`/workflows/${encodeURIComponent(workflowId)}/policy-counters`),
                    apiRequest(`/workflows/${encodeURIComponent(workflowId)}/delivery-diagnostics`),
                ]);
                if (selectedWorkflowStudioResourceType === 'workflow' && selectedWorkflowStudioResourceId === workflowId) {
                    const workflow = findWorkflow(workflowId) || await apiRequest(`/workflows/${encodeURIComponent(workflowId)}`);
                    if (workflowStudioSelectedLabel) {
                        workflowStudioSelectedLabel.textContent = `${workflow.name || workflow.workflow_id} · ${String(workflow.status || 'draft').replace(/[_-]+/g, ' ')}`;
                    }
                    renderJsonOutput(workflowStudioDetailOutput, workflow, '');
                    renderWorkflowStudioDetailActions('workflow', workflow);
                }
                renderSimpleTable(
                    workflowExecutionsList,
                    [
                        { label: 'Recorded At', render: (item) => escapeHtml(formatDateTime(item.reference_time || item.executed_at || item.recorded_at)) },
                        { label: 'Triggered', render: (item) => escapeHtml(String(item.triggered || 0)) },
                        { label: 'Success', render: (item) => escapeHtml(String(item.success || 0)) },
                        { label: 'Sandbox', render: (item) => escapeHtml(String(Boolean(item.sandbox))) },
                    ],
                    executionsPayload.items || [],
                    'No workflow executions recorded yet.',
                );
                renderSimpleTable(
                    workflowDeliveriesList,
                    [
                        {
                            label: 'Delivery',
                            render: (item) => {
                                const audienceLabel = Array.isArray(item.user_ids) && item.user_ids.length > 0
                                    ? item.user_ids.join(', ')
                                    : (item.audience_mode === 'provider_broadcast_all_players' ? 'all players' : (item.user_id || '-'));
                                return `<strong>${escapeHtml(item.delivery_id || '-')}</strong><div class="subtle">${escapeHtml(audienceLabel)}</div>`;
                            },
                        },
                        { label: 'Status', render: (item) => `<span class="pill">${escapeHtml(item.delivery_status || item.status || '-')}</span>` },
                        { label: 'Channel', render: (item) => escapeHtml(item.channel || '-') },
                        { label: 'Sandbox', render: (item) => escapeHtml(String(Boolean(item.sandbox))) },
                    ],
                    deliveriesPayload.items || [],
                    'No deliveries recorded yet.',
                );
                renderJsonOutput(workflowPolicyOutput, policyPayload, 'No policy counters recorded.');
                renderJsonOutput(workflowDeliveryDiagnosticsOutput, diagnosticsPayload, 'No workflow delivery diagnostics recorded.');
            }

            async function sendPushDispatchNow() {
                try {
                    const audience = getPushComposerAudienceSelection();
                    const providerConnectionId = String(pushDispatchProviderConnectionSelect?.value || '').trim();
                    validatePushComposerAudience({ ...audience, providerConnectionId });
                    if (audience.audienceType === 'cohort') {
                        throw new Error('Use Run Cohort Now to execute cohort-backed immediate sends.');
                    }
                    const audienceLabel = audience.label || 'selected audience';
                    setInlineStatus(
                        pushDispatchStatus,
                        providerConnectionId ? `Sending push to ${audienceLabel}...` : `Running simulator push for ${audienceLabel}...`,
                    );
                    const response = await apiRequest('/push-dispatches/send-now', {
                        method: 'POST',
                        body: buildPushDispatchPayload(),
                    });
                    renderJsonOutput(pushDispatchOutput, response, 'No push response.');
                    const dispatchFailed = String(response.status || '').trim().toLowerCase() === 'failed';
                    const resolvedAudienceLabel = Array.isArray(response.user_ids) && response.user_ids.length > 0
                        ? `${response.user_ids.length} user${response.user_ids.length === 1 ? '' : 's'}`
                        : 'all players';
                    const dispatchStatusMessage = dispatchFailed
                        ? `Push failed for ${resolvedAudienceLabel}: ${response.last_error || 'provider delivery failed'}.`
                        : (
                            response.simulated
                                ? `Simulator send completed for ${resolvedAudienceLabel}.`
                                : `Push sent for ${resolvedAudienceLabel}.`
                        );
                    setInlineStatus(
                        pushDispatchStatus,
                        dispatchStatusMessage,
                        dispatchFailed,
                    );
                    await loadActionOrchestrator();
                    await loadWorkflowStudioSelection('push_dispatch', response.push_dispatch_id);
                } catch (error) {
                    renderJsonOutput(pushDispatchOutput, { error: error.message }, 'Failed to send push.');
                    setInlineStatus(pushDispatchStatus, error.message || 'Failed to send push.', true);
                }
            }

            async function runPushComposerWorkflowNow() {
                const audience = getPushComposerAudienceSelection();
                const providerConnectionId = String(pushDispatchProviderConnectionSelect?.value || '').trim() || null;
                validatePushComposerAudience({ ...audience, providerConnectionId });
                const cohortLimit = Math.max(1000, Number(audience.cohort?.member_count || 0));
                setInlineStatus(pushDispatchStatus, `Running immediate push workflow for ${audience.label}...`);
                const createdWorkflow = await apiRequest('/workflows', {
                    method: 'POST',
                    body: buildPushComposerWorkflowPayload({ manualTest: true }),
                });
                const runResult = await apiRequest(`/workflows/${encodeURIComponent(createdWorkflow.workflow_id)}/test-run`, {
                    method: 'POST',
                    body: {
                        limit: cohortLimit,
                        confirm: true,
                        sandbox: false,
                        reference_time: getCurrentWorkflowReferenceTime(),
                    },
                });
                renderJsonOutput(
                    pushDispatchOutput,
                    { workflow: createdWorkflow, execution: runResult },
                    'No push workflow response.',
                );
                setInlineStatus(
                    pushDispatchStatus,
                    `Draft workflow ${createdWorkflow.name || createdWorkflow.workflow_id} ran immediately for ${audience.label}.`,
                    Number(runResult.failures || 0) > 0,
                );
                await loadActionOrchestrator();
                await loadWorkflowStudioSelection('workflow', createdWorkflow.workflow_id);
            }

            async function submitPushComposer() {
                const mode = getPushComposerMode();
                const singleTiming = getPushComposerSingleTiming();
                const audience = getPushComposerAudienceSelection();
                if (mode === 'single' && singleTiming === 'immediate') {
                    if (audience.audienceType === 'cohort') {
                        await runPushComposerWorkflowNow();
                        return;
                    }
                    await sendPushDispatchNow();
                    return;
                }
                try {
                    const isRepeated = mode === 'repeated';
                    const actionLabel = isRepeated ? 'Creating repeated push workflow...' : 'Creating one-time scheduled push workflow...';
                    setInlineStatus(
                        pushDispatchStatus,
                        actionLabel,
                    );
                    const createdWorkflow = await apiRequest('/workflows', {
                        method: 'POST',
                        body: buildPushComposerWorkflowPayload(),
                    });
                    const publishedWorkflow = await apiRequest(`/workflows/${encodeURIComponent(createdWorkflow.workflow_id)}/publish`, {
                        method: 'POST',
                    });
                    renderJsonOutput(pushDispatchOutput, publishedWorkflow, 'No push workflow response.');
                    setInlineStatus(
                        pushDispatchStatus,
                        isRepeated
                            ? `Repeated push workflow ${publishedWorkflow.name || publishedWorkflow.workflow_id} created and published.`
                            : `One-time scheduled push workflow ${publishedWorkflow.name || publishedWorkflow.workflow_id} created and published.`,
                    );
                    await loadActionOrchestrator();
                    await loadWorkflowStudioSelection('workflow', publishedWorkflow.workflow_id);
                } catch (error) {
                    renderJsonOutput(pushDispatchOutput, { error: error.message }, 'Failed to schedule push.');
                    setInlineStatus(pushDispatchStatus, error.message || 'Failed to schedule push.', true);
                }
            }

            async function createWorkflow() {
                try {
                    const editingWorkflowId = selectedWorkflowBuilderId;
                    setInlineStatus(workflowCreateStatus, editingWorkflowId ? 'Updating workflow...' : 'Creating workflow...');
                    const channel = String(workflowChannelSelect?.value || 'push_notification').trim().toLowerCase() || 'push_notification';
                    const pushChannelConfig = channel === 'push_notification'
                        ? {
                            channel,
                            campaign_name: String(workflowPushCampaignNameInput?.value || '').trim() || `push_campaign_${Date.now()}`,
                            title: String(workflowPushTitleInput?.value || '').trim(),
                            body: String(workflowPushBodyInput?.value || '').trim(),
                            content: String(workflowPushBodyInput?.value || '').trim(),
                            deep_link: String(workflowPushDeepLinkInput?.value || '').trim(),
                            deep_link_token: String(workflowPushDeepLinkTokenInput?.value || '').trim(),
                            scheduled_at: toIsoFromLocalDateTimeInput(workflowPushScheduledAtInput?.value || ''),
                            data: parseJsonText(workflowPushDataInput?.value, {}),
                            provider_connection_id: String(workflowPushProviderConnectionSelect?.value || '').trim() || null,
                            provider_options: parseJsonText(workflowPushProviderOptionsInput?.value, {}),
                        }
                        : null;
                    const emailChannelConfig = channel === 'email'
                        ? {
                            channel,
                            content: String(workflowContentInput?.value || '').trim(),
                        }
                        : null;
                    const actionConfig = pushChannelConfig || emailChannelConfig || {channel, content: ''};
                    const requestBody = {
                        name: document.getElementById('workflow-name-input').value || `workflow_${Date.now()}`,
                        cohort_id: document.getElementById('workflow-cohort-select').value,
                        experiment_id: document.getElementById('workflow-experiment-id-input').value || null,
                        requires_confirmation: document.getElementById('workflow-requires-confirmation-checkbox').checked,
                        schedule: { type: 'daily' },
                        trigger: {
                            type: document.getElementById('workflow-trigger-type-select').value || 'daily_schedule',
                            hour: Number(document.getElementById('workflow-trigger-hour-input').value || 0),
                            minute: Number(document.getElementById('workflow-trigger-minute-input').value || 0),
                        },
                        action: actionConfig,
                        channel_config: actionConfig,
                        policy: {
                            global_daily_limit: Number(document.getElementById('workflow-global-limit-input').value || 5),
                            channel_daily_limit: Number(document.getElementById('workflow-channel-limit-input').value || 5),
                            cooldown_hours: Number(document.getElementById('workflow-cooldown-hours-input').value || 24),
                            blacklist_ids: splitCsv(document.getElementById('workflow-blacklist-input').value),
                            quiet_hours: {
                                start: Number(document.getElementById('workflow-quiet-start-input').value || 22),
                                end: Number(document.getElementById('workflow-quiet-end-input').value || 7),
                            },
                        },
                        budget_policy: {
                            daily_budget_limit: Number(document.getElementById('workflow-budget-limit-input').value || 25),
                        },
                    };
                    const payload = await apiRequest(editingWorkflowId ? `/workflows/${encodeURIComponent(editingWorkflowId)}` : '/workflows', {
                        method: editingWorkflowId ? 'PUT' : 'POST',
                        body: requestBody,
                    });
                    selectedWorkflowId = payload.workflow_id;
                    setInlineStatus(workflowCreateStatus, `${editingWorkflowId ? 'Updated' : 'Created'} workflow ${payload.name}.`);
                    await loadActionOrchestrator();
                    await loadWorkflowStudioSelection('workflow', payload.workflow_id);
                } catch (error) {
                    setInlineStatus(workflowCreateStatus, error.message || 'Failed to create workflow.', true);
                }
            }

